export interface TarefaCompetenciaCatalogo {
  titulo: string;
  comoFazer: string;
  comprovacao: string;
}

export interface CompetenciaTarefasCatalogo {
  numero: number;
  nome: string;
  descricao: string;
  tarefas: TarefaCompetenciaCatalogo[];
}

// Fonte: Trilha_de_Competencias.docx fornecido pela CKM.
// 99 competências e 6 tarefas por competência. Não editar manualmente sem revisar a fonte.
export const COMPETENCIAS_TAREFAS: CompetenciaTarefasCatalogo[] = [
{"numero":1,"nome":"Accountability","descricao":"Accountability é assumir de verdade o que é seu: suas entregas, suas escolhas e seus resultados, inclusive quando algo dá errado. Quem tem accountability não procura culpados. Procura a próxima ação possível.","tarefas":[{"titulo":"Ler a introdução e o capítulo 1 do livro “Responsabilidade Extrema”, de Jocko Willink e Leif Babin","comoFazer":"Os autores são ex-comandantes militares e mostram como a postura de “o resultado é meu, sem desculpas” muda uma equipe inteira. Leia com um caderno ao lado e, sempre que aparecer uma atitude de quem assume a responsabilidade, anote. Depois pense em uma situação recente do seu trabalho em que você poderia ter agido assim e não agiu. Não precisa se cobrar: a ideia é enxergar.","comprovacao":"Traga 3 atitudes que chamaram sua atenção no livro e, para cada uma, um exemplo concreto de como aplicá-la na sua rotina."},{"titulo":"Assistir ao filme “Coach Carter: Treino para a Vida”","comoFazer":"O filme conta a história de um treinador que exige que os jogadores cumpram um contrato de compromisso, dentro e fora da quadra. Preste atenção nos momentos em que alguém precisa lidar com as consequências das próprias escolhas e em como o treinador cobra sem abrir exceções. Pause e anote as cenas que te marcarem.","comprovacao":"Traga 3 cenas que você escolheu e explique, com suas palavras, o que cada uma ensina sobre cumprir compromissos e assumir consequências."},{"titulo":"Aplicar a técnica “Acima da Linha / Abaixo da Linha”","comoFazer":"Pegue uma folha e desenhe uma linha horizontal no meio. Abaixo da linha ficam as reações de quem se esquiva: culpar os outros, fingir que não viu, esperar alguém resolver, dizer “isso não é comigo”. Acima da linha ficam 4 passos de quem assume: Enxergar o problema como ele é, Assumir a sua parte, Buscar a solução e Fazer acontecer. Escolha uma situação difícil do seu trabalho, escreva embaixo qual seria sua reação automática e em cima o que vai fazer em cada passo. Depois, coloque em prática.","comprovacao":"Traga a folha preenchida e conte o que aconteceu quando você agiu “acima da linha”."},{"titulo":"Manter um Diário de Compromissos por 5 dias","comoFazer":"Todo dia de manhã, anote até 3 compromissos que você assumiu com alguém, com o prazo de cada um. No fim do expediente, volte ao diário e marque: concluído, pendente ou renegociado. Se algo não saiu, anote o motivo e responda com sinceridade: “Eu avisei a pessoa antes do prazo vencer ou só depois?”. Esse detalhe faz muita diferença na confiança que os outros depositam em você.","comprovacao":"Traga os 5 dias de registro e sua resposta para: “Quantas vezes renegociei antes do prazo e quantas vezes só me expliquei depois?”"},{"titulo":"Avaliar sua própria confiabilidade (e, se possível, pedir feedback)","comoFazer":"Responda por escrito, com honestidade, 3 perguntas: “Quando eu assumo algo, as pessoas podem confiar que vai ser entregue?”, “Em que situação recente eu poderia ter assumido mais responsabilidade?” e “O que me faria ser ainda mais confiável?”. Se tiver abertura com seu gestor ou anjo, faça as mesmas perguntas a ele em uma conversa de 15 minutos e escute sem se defender. Se não for possível, compare suas respostas com os registros do Diário de Compromissos.","comprovacao":"Traga suas respostas (e as do gestor ou anjo, se houver conversa) e uma ação concreta que vai colocar em prática."},{"titulo":"Fazer a análise de um erro seu","comoFazer":"Escolha um erro recente, grande ou pequeno, e responda por escrito, com calma: O que aconteceu? Qual foi exatamente a minha parte? Qual foi o impacto para outras pessoas? O que eu fiz para corrigir? O que faço diferente a partir de agora? Se sentir que é o momento, compartilhe essa análise com quem foi afetado ou com seu gestor. Mostrar que você reconhece e aprende com os próprios erros gera muito mais confiança do que parecer que nunca erra.","comprovacao":"Traga a análise escrita e, se compartilhou com alguém, conte como foi a reação."}]},
{"numero":2,"nome":"Adaptabilidade","descricao":"Adaptabilidade é a capacidade de ajustar a forma como você trabalha quando o contexto muda: novas pessoas, novas ferramentas, novas regras, novas prioridades. Não é aceitar tudo; é não travar e continuar entregando bem.","tarefas":[{"titulo":"Ler o livro “Quem Mexeu no Meu Queijo?”, de Spencer Johnson","comoFazer":"É um livro curto, dá para ler em uma tarde. Ele conta a história de 4 personagens que reagem de formas bem diferentes quando o “queijo” deles some. Enquanto lê, identifique como cada um se comporta: quem percebe a mudança antes, quem nega, quem se adapta rápido, quem sofre mais. E seja sincero com você: com qual deles você mais se parece hoje?","comprovacao":"Traga sua resposta para “Com qual personagem eu mais me pareço e por quê?”, com um exemplo real de uma mudança que você viveu no trabalho."},{"titulo":"Assistir ao filme “Um Senhor Estagiário”","comoFazer":"O filme mostra um aposentado de 70 anos que vai trabalhar como estagiário em uma startup cheia de jovens, com outra linguagem, outras ferramentas e outro ritmo. Repare em como ele se adapta sem abrir mão do que tem de melhor: experiência, educação e calma. Repare também na fundadora, que precisa se adaptar a ele.","comprovacao":"Traga 3 atitudes de adaptação que você viu no filme e diga qual delas gostaria de trazer para o seu dia a dia."},{"titulo":"Assistir ao TED “3 formas de medir sua adaptabilidade e como melhorá-la”, de Natalie Fratto","comoFazer":"É uma palestra curta, de uns 10 minutos, no site do TED e no YouTube. A palestrante mostra perguntas que revelam o quanto uma pessoa é adaptável, como o hábito de pensar “e se…?”. Assista, anote as perguntas que ela sugere e depois responda a cada uma pensando em você e no seu trabalho.","comprovacao":"Traga suas respostas às perguntas da palestra e o que elas mostraram sobre sua forma de lidar com mudanças."},{"titulo":"Criar um Plano A, B e C para uma entrega importante","comoFazer":"Escolha uma entrega relevante que você tem pela frente. Escreva o Plano A: como vai fazer se tudo correr bem. Depois o Plano B: como vai fazer se acontecer um imprevisto, por exemplo o sistema cair ou alguém importante faltar. Por fim, o Plano C: como vai entregar se o prazo ou os recursos forem cortados pela metade. Com alternativas pensadas antes, a mudança assusta muito menos.","comprovacao":"Traga os três planos em uma página. Se algum imprevisto acontecer durante a entrega, conte qual plano usou."},{"titulo":"Conhecer a história de alguém que passou por uma grande mudança profissional","comoFazer":"Se puder, convide para um café de 15 minutos um colega que tenha mudado de área, função, empresa ou sistema e pergunte: “O que foi mais difícil?”, “O que te ajudou a se adaptar?” e “O que faria diferente?”. Se não for possível, faça o mesmo exercício com uma entrevista, podcast ou biografia de alguém que mudou de carreira, e responda às 3 perguntas com base no que viu.","comprovacao":"Traga 3 aprendizados e diga qual deles faz mais sentido para o seu momento."},{"titulo":"Fazer a “Semana do Faça Diferente”","comoFazer":"Durante 5 dias, mude uma coisa pequena por dia na forma como você trabalha: a ordem das tarefas, o horário de responder e-mails, o jeito de anotar pendências, a ferramenta de organização. O objetivo é treinar o “músculo” da adaptação em situações de baixo risco. Repare no incômodo que aparece e em como ele diminui com o tempo.","comprovacao":"Traga o registro das 5 mudanças, o que sentiu em cada uma e se alguma delas vale a pena manter."}]},
{"numero":3,"nome":"Adaptabilidade Dinâmica","descricao":"Adaptabilidade dinâmica é se adaptar no calor do momento. É quando o plano muda no meio do caminho e você precisa reorganizar tudo rápido, com a cabeça no lugar, sem perder de vista o objetivo.","tarefas":[{"titulo":"Assistir ao filme “Apollo 13: Do Desastre ao Triunfo”","comoFazer":"O filme conta a história real de uma missão espacial que sofre uma pane grave a caminho da Lua. A partir daí, a equipe precisa mudar de plano várias vezes, com pouco tempo e recursos limitados. Repare em como eles reagem a cada novo problema: ninguém fica parado lamentando, todos partem para a próxima solução.","comprovacao":"Traga 3 momentos em que a equipe mudou de plano e explique o que permitiu que reagissem tão rápido."},{"titulo":"Ler o prólogo e o capítulo 1 do livro “Antifrágil”, de Nassim Taleb","comoFazer":"O autor divide as coisas em três tipos: as frágeis, que quebram com o caos; as robustas, que aguentam; e as antifrágeis, que ficam melhores com ele. A leitura é um pouco mais densa, então vá devagar e anote as ideias principais. Depois olhe para o seu trabalho e pense: quais processos, hábitos ou rotinas meus são frágeis?","comprovacao":"Traga 3 processos ou hábitos seus classificados como frágil, robusto ou antifrágil e uma ideia para fortalecer o mais frágil."},{"titulo":"Aplicar o Ciclo OODA em uma situação real","comoFazer":"O Ciclo OODA foi criado por um piloto militar para decidir rápido em ambientes que mudam o tempo todo. Da próxima vez que algo mudar no seu trabalho, siga os 4 passos: Observar (o que exatamente mudou?), Orientar (o que isso afeta e quem é impactado?), Decidir (qual a melhor resposta agora, com o que eu tenho?) e Agir. Depois de agir, observe o resultado e, se precisar, recomece o ciclo.","comprovacao":"Traga a situação que viveu e o que você fez em cada uma das 4 etapas."},{"titulo":"Praticar o “Sim, e…” do teatro de improviso","comoFazer":"No improviso, os atores nunca negam o que o colega trouxe para a cena: eles aceitam e constroem em cima, dizendo “Sim, e…”. Leve isso para o trabalho. Quando alguém trouxer uma ideia nova ou uma mudança, comece sua resposta com “Sim, e…” em vez de “Sim, mas…” ou “Não, porque…”. Faça isso pelo menos 3 vezes na semana. Vale também para mudanças que chegam por e-mail ou mensagem: antes de responder, escreva mentalmente o “Sim, e…”.","comprovacao":"Traga as 3 situações e conte como a conversa ou a situação andou depois do “Sim, e…”."},{"titulo":"Fazer um Registro de Imprevistos por 5 dias","comoFazer":"Deixe um bloco de notas à mão. Sempre que algo inesperado acontecer, anote rapidinho: o que mudou, qual foi sua primeira reação (irritação, ansiedade, travamento, ação rápida), o que decidiu fazer e quanto tempo levou para voltar ao ritmo. No fim da semana, leia tudo e procure padrões.","comprovacao":"Traga pelo menos 3 registros e o padrão que você percebeu nas suas reações."},{"titulo":"Mapear as mudanças mais comuns da sua área e preparar respostas","comoFazer":"Liste as mudanças que mais acontecem no seu dia a dia: prioridade que muda, prazo que encurta, demanda urgente, sistema que cai, pessoa que falta. Para cada uma, escreva a resposta ideal que você quer ter quando ela acontecer. Se tiver abertura, valide essa lista em 10 minutos com seu gestor, perguntando o que ele espera de você nesses momentos; se não, use sua própria experiência e o Registro de Imprevistos.","comprovacao":"Traga a lista de mudanças com a resposta planejada para cada uma e escolha uma para praticar nas próximas semanas."}]},
{"numero":4,"nome":"Agilidade","descricao":"Agilidade é fazer as coisas andarem com rapidez e fluidez, eliminando esperas, etapas desnecessárias e retrabalho. Não é correr nem fazer malfeito: é fazer bem, sem desperdício.","tarefas":[{"titulo":"Ler os 3 primeiros capítulos de “Scrum: A Arte de Fazer o Dobro do Trabalho na Metade do Tempo”, de Jeff Sutherland","comoFazer":"O autor é um dos criadores do Scrum, método usado no mundo todo para acelerar projetos. Nos primeiros capítulos, ele conta como percebeu que o jeito tradicional de trabalhar gerava muita demora e desperdício. Enquanto lê, anote as ideias que poderiam reduzir tempo ou retrabalho nas suas atividades.","comprovacao":"Traga 3 ideias do livro e escolha uma para testar na próxima semana. Depois conte como foi."},{"titulo":"Assistir ao filme “Fome de Poder”","comoFazer":"O filme conta a história do McDonald’s. Preste atenção especial na cena em que os irmãos McDonald desenham a cozinha em giz numa quadra de tênis e ensaiam com os funcionários até encontrar o fluxo mais rápido possível. É uma aula de como redesenhar um processo.","comprovacao":"Escolha uma atividade sua, desenhe o passo a passo dela e mostre onde ela poderia ser “redesenhada” para ficar mais rápida."},{"titulo":"Usar um Kanban pessoal por 5 dias","comoFazer":"Pegue uma folha, um quadro ou um aplicativo como o Trello e crie 3 colunas: A fazer, Fazendo e Feito. Coloque cada tarefa em um post-it ou cartão. A regra de ouro: no máximo 3 tarefas na coluna “Fazendo” ao mesmo tempo. Só puxe uma nova quando terminar uma que já está lá. Isso reduz muito aquela sensação de começar mil coisas e não terminar nenhuma.","comprovacao":"Traga uma foto do quadro no primeiro e no último dia e responda: “Terminei mais coisas quando limitei o que fazia ao mesmo tempo?”"},{"titulo":"Aplicar a Regra dos 2 Minutos por uma semana","comoFazer":"Essa regra é de David Allen, autor do método GTD. Se uma tarefa leva menos de 2 minutos (responder uma mensagem simples, encaminhar um e-mail, arquivar um documento, confirmar uma reunião), faça na hora em vez de anotar para depois. Essas pequenas coisas, quando acumulam, viram uma montanha. Só não use a regra para tarefas que pedem reflexão.","comprovacao":"Traga pelo menos 5 tarefas que resolveu na hora e diga se percebeu sua lista de pendências diminuir."},{"titulo":"Mapear os gargalos de um processo","comoFazer":"Escolha uma atividade que se repete no seu trabalho e escreva todas as etapas, do início ao fim. Depois marque com outra cor os pontos onde o trabalho costuma travar: espera por resposta, aprovação desnecessária, retrabalho, informação faltando. Se algum colega participar do processo e tiver disponibilidade, faça o mapa junto com ele; se não, faça sozinho e use sua observação do dia a dia.","comprovacao":"Traga o fluxo com os gargalos marcados e uma proposta concreta para eliminar pelo menos um deles."},{"titulo":"Fazer o desafio “Primeira versão em 30 minutos”","comoFazer":"Escolha uma entrega que você costuma demorar a começar, como um relatório, uma apresentação ou um e-mail importante. Coloque um cronômetro de 30 minutos e faça uma versão completa, mesmo imperfeita. Não pare para lapidar. Depois, em outro momento, revise e melhore. Muita demora vem da tentativa de acertar tudo de primeira.","comprovacao":"Traga quanto tempo levou a primeira versão, quanto levou a revisão e compare com quanto você costuma levar nesse tipo de entrega."}]},
{"numero":5,"nome":"Aprendizagem Contínua","descricao":"Aprendizagem contínua é ter o hábito de buscar novos conhecimentos, aprender com cada experiência e colocar em prática o que aprendeu. Não depende de curso formal; depende de curiosidade e constância.","tarefas":[{"titulo":"Fazer a primeira semana do curso gratuito “Aprendendo a Aprender”, no Coursera","comoFazer":"É um dos cursos mais populares do mundo, criado pela professora Barbara Oakley. Na primeira semana, ela explica como o cérebro aprende, a diferença entre o modo focado e o modo difuso de pensar e por que a gente procrastina na hora de estudar. Faça as aulas com calma, uma por dia se preferir.","comprovacao":"Traga um print do seu progresso no curso e 3 técnicas que pretende usar para aprender melhor."},{"titulo":"Assistir ao TEDx “As primeiras 20 horas: como aprender qualquer coisa”, de Josh Kaufman","comoFazer":"Nessa palestra, o autor mostra que dá para sair do zero e chegar a um nível razoável em uma nova habilidade com cerca de 20 horas de prática bem direcionada, seguindo 4 passos simples. Assista, anote os passos e pense em uma habilidade que faria diferença no seu trabalho.","comprovacao":"Traga a habilidade que escolheu e um plano de como aplicaria os 4 passos da palestra para aprendê-la."},{"titulo":"Aplicar a Técnica Feynman","comoFazer":"Richard Feynman foi um físico famoso por explicar coisas complexas de um jeito simples. Escolha um tema do seu trabalho que ainda não domina bem e estude. Depois explique em voz alta, como se falasse com alguém leigo, em linguagem simples e em até 10 minutos. Pode ser para um colega ou para a câmera do celular. Os pontos em que você travar, se enrolar ou precisar de termos complicados são exatamente os que ainda não entendeu. Volte, estude de novo e explique outra vez.","comprovacao":"Traga o tema escolhido, onde travou e o que estudou depois para completar o entendimento (se gravou, traga o vídeo)."},{"titulo":"Manter um Diário de Aprendizagem por 5 dias","comoFazer":"No fim de cada dia, reserve 5 minutos e responda em poucas linhas: “O que eu aprendi hoje?”, “Com quem ou com o quê aprendi?” e “Onde posso usar isso de novo?”. Vale tudo: um atalho no sistema, uma forma diferente de falar com um cliente, um erro que ensinou algo. Você vai se surpreender com o quanto aprende sem perceber.","comprovacao":"Traga os 5 registros e destaque o aprendizado que foi mais útil na semana."},{"titulo":"Descobrir quais conhecimentos fariam mais diferença no seu trabalho","comoFazer":"Olhe para as descrições de vagas parecidas com a sua ou um nível acima (LinkedIn, sites de emprego) e anote as habilidades que mais aparecem. Compare com o que você já domina. Se quiser completar, pergunte a 1 ou 2 colegas de confiança: “Que conhecimento você acha que faria diferença no meu trabalho?”.","comprovacao":"Traga a lista de habilidades encontradas, marcando as que você já tem e as que ainda precisa desenvolver, e escolha uma para estudar no próximo mês."},{"titulo":"Criar um Plano de Aprendizagem de 30 dias","comoFazer":"Escolha um tema e defina um objetivo que dê para medir, por exemplo: “fazer uma tabela dinâmica no Excel sem pedir ajuda”. Defina onde vai aprender (vídeo, curso, manual), quanto tempo vai dedicar (sugiro 15 minutos por dia) e como vai testar se aprendeu mesmo. Coloque o plano em um lugar visível.","comprovacao":"Traga o plano e, ao final dos 30 dias, mostre na prática o que você aprendeu."}]},
{"numero":6,"nome":"Arquitetura de Mudanças","descricao":"Arquitetura de mudanças é planejar uma mudança com intenção, como um arquiteto planeja uma obra: pensando nas pessoas, nos impactos, nas resistências e nas etapas, para que a mudança não fique só no papel e realmente se sustente.","tarefas":[{"titulo":"Ler a introdução e o capítulo 1 de “Switch: Como Mudar as Coisas Quando a Mudança é Difícil”, de Chip e Dan Heath","comoFazer":"Os autores explicam a mudança com uma metáfora muito boa: o Condutor (nosso lado racional), o Elefante (nosso lado emocional) e o Caminho (o ambiente). Para uma mudança dar certo, é preciso convencer o Condutor, motivar o Elefante e preparar o Caminho. Leia com atenção e pense em uma mudança que está acontecendo, ou deveria acontecer, na sua área.","comprovacao":"Traga essa mudança descrita em três partes: o que precisa ser feito para o Condutor, para o Elefante e para o Caminho."},{"titulo":"Assistir ao filme “O Homem que Mudou o Jogo”","comoFazer":"O filme conta a história de um gerente de beisebol que decide montar o time usando análise de dados, enquanto todos em volta confiam só na intuição. Ele enfrenta muita resistência. Observe quem resiste, por que resiste e o que ele faz para seguir em frente com a mudança.","comprovacao":"Traga 3 resistências que ele enfrentou, como lidou com cada uma e qual estratégia você usaria no seu trabalho."},{"titulo":"Aplicar o modelo ADKAR a uma mudança real","comoFazer":"O ADKAR diz que, para uma pessoa mudar, ela precisa passar por 5 etapas: Consciência (entende por que mudar?), Desejo (quer mudar?), Conhecimento (sabe como fazer?), Habilidade (consegue fazer na prática?) e Reforço (existe algo que sustenta a mudança?). Escolha uma mudança da empresa ou da sua área e avalie cada etapa. Normalmente uma delas está mais fraca, e é ali que a mudança trava.","comprovacao":"Traga o quadro preenchido, aponte a etapa mais frágil e sugira uma ação para fortalecê-la."},{"titulo":"Construir um Mapa de Impacto","comoFazer":"Escolha uma mudança de processo, sistema ou rotina. Monte uma tabela com 4 colunas: quem é afetado, o que muda para essa pessoa, que dificuldade ela pode ter e que apoio vai precisar. Muitas mudanças fracassam porque ninguém parou para pensar no que ela significa para quem está na ponta.","comprovacao":"Traga o mapa com pelo menos 3 grupos de pessoas afetadas."},{"titulo":"Desenhar um piloto","comoFazer":"Antes de mudar algo para todo mundo, vale testar em pequena escala. Escolha uma melhoria que gostaria de ver na sua área e planeje um teste: o que será testado, com quem ou em que parte do trabalho, por quanto tempo e quais sinais vão mostrar que funcionou. Se não houver espaço para testar com outras pessoas, faça o piloto na sua própria rotina.","comprovacao":"Traga o plano do piloto em uma página e, se ele for aplicado, os resultados."},{"titulo":"Fazer a retrospectiva de uma mudança que você já viveu","comoFazer":"Escolha uma mudança que aconteceu na empresa ou em algum trabalho anterior e responda: O que funcionou? Onde apareceu resistência? O que faltou comunicar? O que deveria ter sido feito antes? Se tiver oportunidade, converse com alguém que conduziu essa mudança para completar sua visão; se não, use o que você viveu e observou.","comprovacao":"Traga suas respostas e transforme-as em 3 recomendações para uma próxima mudança."}]},
{"numero":7,"nome":"Atenção","descricao":"Atenção é conseguir se concentrar no que está fazendo, perceber os detalhes que importam e evitar erros por distração. Em um mundo cheio de notificações e interrupções, é uma competência cada vez mais valiosa.","tarefas":[{"titulo":"Ler a introdução e os 2 primeiros capítulos de “Checklist: Como Fazer as Coisas Bem-Feitas”, de Atul Gawande","comoFazer":"O autor é cirurgião e mostra como listas simples de verificação reduziram drasticamente os erros em hospitais, na aviação e na construção civil. A mensagem principal é que mesmo pessoas muito competentes erram por esquecimento e distração, e que um bom checklist protege contra isso. Leia pensando nas suas próprias entregas.","comprovacao":"Traga 3 aprendizados e uma atividade do seu trabalho em que um checklist evitaria erros."},{"titulo":"Assistir ao filme “Spotlight: Segredos Revelados”","comoFazer":"O filme mostra uma equipe de jornalistas que investiga um grande escândalo. Eles chegam à verdade prestando atenção em detalhes que outras pessoas ignoraram por anos: um nome repetido, uma data, uma lista. Repare no cuidado com que eles checam cada informação antes de concluir qualquer coisa.","comprovacao":"Traga 3 momentos em que um detalhe mudou os rumos da investigação."},{"titulo":"Fazer o teste do “gorila invisível”","comoFazer":"Procure no YouTube por “teste de atenção seletiva gorila”, um experimento famoso dos psicólogos Simons e Chabris. Faça o teste antes de ler qualquer explicação, seguindo exatamente a instrução do vídeo. Só depois pesquise o que ele demonstra: quando estamos muito focados em uma coisa, deixamos de ver algo óbvio.","comprovacao":"Conte se você viu ou não o que devia ver e responda: “Em que situação do meu trabalho posso estar deixando algo importante passar por estar focado demais em outra coisa?”"},{"titulo":"Fazer uma Auditoria de Distrações por 3 dias","comoFazer":"Deixe uma folha ao lado do computador com algumas categorias: celular, e-mail, mensagens, conversas, outra tarefa, pensamento solto. Sempre que interromper o que está fazendo, faça um risquinho na categoria correspondente. No fim dos 3 dias, conte. A maioria das pessoas se surpreende com o resultado.","comprovacao":"Traga a contagem dos 3 dias, as 2 principais causas de distração e o que pretende fazer com elas."},{"titulo":"Criar e usar um checklist de revisão","comoFazer":"Escolha uma entrega que você faz com frequência, como relatório, planilha, proposta ou e-mail para cliente. Liste de 5 a 10 itens que precisam ser conferidos antes de enviar: nomes, datas, valores, anexos, destinatários, ortografia, formatação. Deixe o checklist sempre à mão e use toda vez.","comprovacao":"Traga o checklist e o registro de 3 entregas em que você o usou, dizendo se ele pegou algum erro antes do envio."},{"titulo":"Fazer a revisão “a frio”","comoFazer":"Durante uma semana, nas entregas importantes, não revise logo depois de terminar. Deixe o material descansar pelo menos 1 hora (ou até o dia seguinte, se o prazo permitir) e só então releia, de preferência em voz baixa ou em outro formato (impresso, no celular). Com olhos “descansados”, você enxerga o que não via mais. Se tiver um colega disponível, vocês também podem trocar entregas para revisão cruzada.","comprovacao":"Traga quantos erros ou melhorias você encontrou na revisão “a frio” que tinham passado na primeira leitura."}]},
{"numero":8,"nome":"Autoconfiança","descricao":"Autoconfiança é acreditar na própria capacidade de fazer, de se posicionar e de enfrentar desafios, mesmo quando existe incerteza ou risco de errar. Ela não nasce pronta: é construída com prática e com evidências do que você já fez.","tarefas":[{"titulo":"Ler os 2 primeiros capítulos de “A Coragem de Ser Imperfeito”, de Brené Brown","comoFazer":"A autora pesquisa há anos sobre vergonha e coragem. Ela mostra que muitas vezes deixamos de nos expor, de falar, de propor, de tentar, porque temos medo de não sermos bons o suficiente. Leia com calma e anote os trechos que te tocarem. Depois pense: em que momento do trabalho eu me calei ou me escondi por medo de errar?","comprovacao":"Traga 3 ideias do livro e uma situação real em que você deixou de se expor por medo, dizendo como agiria hoje."},{"titulo":"Assistir ao filme “O Discurso do Rei”","comoFazer":"O filme conta a história real do rei George VI, que tinha gagueira e precisava falar em público em um momento decisivo para o país. Repare em como a confiança dele não aparece de uma hora para outra: ela é construída aos poucos, com treino, apoio e pequenas vitórias.","comprovacao":"Traga 3 atitudes que ajudaram o rei a ganhar confiança e uma delas que você pode usar na sua vida profissional."},{"titulo":"Criar um Inventário de Conquistas","comoFazer":"Quando a insegurança aparece, a gente esquece tudo de bom que já fez. Reserve 30 minutos e liste 10 situações reais em que você resolveu um problema, aprendeu algo difícil, ajudou alguém, recebeu um elogio ou entregou um bom resultado. Pode ser coisa pequena. Depois leia a lista e observe quais habilidades aparecem mais de uma vez. Guarde essa lista para reler nos dias difíceis.","comprovacao":"Traga a lista e as 3 habilidades que mais se repetem nela."},{"titulo":"Reunir evidências dos seus pontos fortes","comoFazer":"Procure elogios, agradecimentos e reconhecimentos que você já recebeu: e-mails, mensagens, avaliações de desempenho, comentários de clientes. Separe pelo menos 5 e anote qual ponto forte cada um revela. Se quiser ir além, pergunte a 1 ou 2 pessoas de confiança: “Qual você acha que é o meu principal ponto forte no trabalho?”, e apenas agradeça, sem diminuir o elogio.","comprovacao":"Traga as evidências reunidas e a lista dos pontos fortes que mais aparecem."},{"titulo":"Fazer uma apresentação de 2 minutos só com tópicos","comoFazer":"Escolha um tema que você domina no seu trabalho. Escreva apenas 3 tópicos em um papel e grave um vídeo no celular explicando o tema em 2 minutos, sem roteiro decorado. Se tiver um colega disponível, pode apresentar para ele. O objetivo é perceber que você sabe mais do que pensa e que não precisa de tudo escrito para se sair bem.","comprovacao":"Traga o vídeo (ou o relato da apresentação), 2 pontos positivos e 1 ponto a melhorar."},{"titulo":"Fazer uma contribuição em reunião","comoFazer":"Antes da próxima reunião, defina um compromisso com você: fazer pelo menos uma pergunta, sugestão ou comentário relevante. Se ajudar, anote antes o que pretende dizer. Na hora, respire e fale. Ninguém espera perfeição, e cada vez que você se posiciona fica mais fácil da próxima.","comprovacao":"Traga o que você disse, como se sentiu antes e depois e como sua contribuição foi recebida."}]},
{"numero":9,"nome":"Autoconhecimento","descricao":"Autoconhecimento é saber quem você é no trabalho: seus valores, suas forças, seus limites, o que te motiva e o que te desgasta. Quanto mais você se conhece, melhores são suas escolhas.","tarefas":[{"titulo":"Fazer o teste gratuito de Forças de Caráter do VIA Institute","comoFazer":"Acesse o site viacharacter.org e faça o teste gratuito. Ele leva uns 15 minutos e é baseado em pesquisas da psicologia positiva. No final, você recebe suas forças de caráter em ordem. Responda com sinceridade, pensando em como você realmente é, e não em como gostaria de ser.","comprovacao":"Traga um print das suas 5 principais forças e um exemplo de como cada uma aparece no seu trabalho."},{"titulo":"Assistir à animação “Soul”","comoFazer":"Pode parecer um filme infantil, mas é uma reflexão profunda sobre propósito, paixão e o que realmente dá sentido à vida. Assista em um momento tranquilo e deixe as perguntas do filme ecoarem em você.","comprovacao":"Responda por escrito: “O que me motiva no trabalho?”, “O que me desgasta?” e “Que tipo de atividade me faz perder a noção do tempo?”"},{"titulo":"Fazer o exercício do Ikigai","comoFazer":"Ikigai é um conceito japonês que significa algo como “razão de ser”. Desenhe 4 círculos que se cruzam no meio e preencha cada um: o que eu amo fazer, no que eu sou bom, do que o mundo precisa e pelo que posso ser pago. Não tenha pressa. Depois observe o que aparece em mais de um círculo: ali estão pistas importantes sobre você.","comprovacao":"Traga o desenho preenchido e uma conclusão de 3 a 5 linhas sobre o que descobriu."},{"titulo":"Fazer a Janela de Johari","comoFazer":"Escolha 5 adjetivos que te descrevem no trabalho. Depois peça a 2 ou 3 pessoas (colegas, amigos ou familiares) que escolham 5 adjetivos sobre você, sem ver sua lista. Compare: o que você e os outros enxergam (área aberta), o que só você enxerga (área oculta) e o que só os outros enxergam (área cega). Se não conseguir respostas, use as avaliações de desempenho e feedbacks que já recebeu como “visão dos outros”.","comprovacao":"Traga o quadro montado e uma percepção externa que te surpreendeu."},{"titulo":"Definir seus 5 valores profissionais","comoFazer":"Valores são aquilo que, quando respeitado, te faz sentir bem no trabalho e, quando desrespeitado, te incomoda profundamente. A partir de uma lista (autonomia, estabilidade, aprendizado, reconhecimento, colaboração, inovação, segurança, propósito, resultados, equilíbrio, justiça, desafio), escolha os 5 mais importantes e coloque em ordem. Escolher é difícil, e é justamente aí que está o exercício.","comprovacao":"Traga os 5 valores em ordem e, para cada um, uma situação em que ele foi atendido ou desrespeitado no trabalho."},{"titulo":"Manter um Diário de Energia por 5 dias","comoFazer":"Depois de cada atividade importante do dia, marque ao lado: ↑ se ela te deu energia, → se foi neutra e ↓ se te cansou. No fim da semana, olhe o padrão. Isso te ajuda a entender o tipo de trabalho em que você brilha e a organizar melhor seu dia, deixando as tarefas mais desgastantes para quando estiver com mais disposição.","comprovacao":"Traga o registro e a lista das atividades que mais te energizam e das que mais te desgastam."}]},
{"numero":10,"nome":"Autonomia","descricao":"Autonomia é conduzir o próprio trabalho com independência, tomando as decisões que cabem a você e buscando ajuda de forma estratégica, e não por insegurança ou dependência.","tarefas":[{"titulo":"Assistir ao TED “O enigma da motivação”, de Dan Pink","comoFazer":"É uma palestra de uns 18 minutos, no site do TED e no YouTube. Dan Pink mostra, com base em pesquisas, que o que mais motiva as pessoas no trabalho não é dinheiro nem prêmio, mas três coisas: autonomia, maestria e propósito. Assista e pense em como a autonomia aparece, ou falta, na sua rotina.","comprovacao":"Traga 3 ideias da palestra e uma área do trabalho em que gostaria de ter mais autonomia, dizendo o que precisaria mostrar para conquistá-la."},{"titulo":"Assistir ao filme “Joy: O Nome do Sucesso”","comoFazer":"O filme conta a história real de uma mulher que cria um produto inovador e enfrenta uma série de obstáculos para colocá-lo no mercado. Repare em como ela toma decisões, resolve problemas e segue em frente sem esperar que alguém faça por ela ou dê permissão.","comprovacao":"Traga 3 atitudes de autonomia da personagem e diga qual delas você mais precisa desenvolver."},{"titulo":"Mapear seus limites de decisão","comoFazer":"Muitas vezes falta autonomia porque não está claro o que podemos decidir sozinhos. Faça um quadro com 3 colunas: “Decido sozinho”, “Decido e aviso depois” e “Preciso de aprovação antes”. Preencha com exemplos reais das suas atividades, com base no que você já sabe e nas situações que viveu. Se tiver abertura, leve o quadro para seu gestor validar em 10 minutos.","comprovacao":"Traga o quadro preenchido (validado ou não) e deixe-o à vista na sua rotina."},{"titulo":"Aplicar a regra “Traga o problema com 2 soluções”","comoFazer":"Durante 2 semanas, antes de levar qualquer dificuldade para alguém, pare e pense em pelo menos 2 alternativas para resolvê-la. Avalie os prós e contras de cada uma e, ao pedir ajuda, diga qual recomenda e por quê. Muitas vezes, nesse processo, você vai perceber que nem precisa pedir ajuda.","comprovacao":"Traga 2 situações em que usou a regra: o problema, as alternativas pensadas e o que foi decidido."},{"titulo":"Planejar e conduzir uma entrega do início ao fim","comoFazer":"Escolha uma tarefa que está sob sua responsabilidade e planeje tudo sozinho: o objetivo, as etapas, o prazo, o que precisa de outras pessoas e o que significa “pronto”. Conduza a entrega envolvendo os outros apenas nos pontos em que realmente é necessário.","comprovacao":"Traga o plano que você fez e o resultado final da entrega."},{"titulo":"Escrever seu “Manual de Funcionamento”","comoFazer":"Em uma página, descreva como você trabalha: como organiza suas tarefas, como acompanha prazos, que decisões toma sozinho, quando pede ajuda e como avisa quando algo vai atrasar. Escrever isso te obriga a olhar para sua própria forma de trabalhar e perceber onde ainda depende demais dos outros.","comprovacao":"Traga o manual e aponte uma rotina que pretende melhorar."}]},
{"numero":11,"nome":"Autopercepção","descricao":"Autopercepção é perceber, no momento em que acontece, o que você está sentindo, como está se comportando e que efeito isso está causando nas pessoas ao seu redor.","tarefas":[{"titulo":"Assistir à animação “Divertida Mente”","comoFazer":"O filme mostra as emoções de uma menina como personagens que comandam suas reações. Preste atenção em como cada emoção muda a forma como ela interpreta a mesma situação. Depois pense: em que momentos do meu trabalho uma emoção “assumiu o comando” e mudou a forma como eu vi as coisas?","comprovacao":"Traga 3 cenas do filme e relacione cada uma a uma situação profissional em que algo parecido aconteceu com você."},{"titulo":"Fazer check-ins emocionais com a Roda das Emoções","comoFazer":"Procure na internet a imagem da “Roda das Emoções de Plutchik” e salve no celular. Durante 5 dias, 3 vezes ao dia (de manhã, depois do almoço e no fim do expediente), pare 1 minuto, olhe para a roda e tente nomear com precisão o que está sentindo. Em vez de “estou mal”, será que é frustração, ansiedade, cansaço, tédio? Nomear bem é o primeiro passo para lidar bem.","comprovacao":"Traga o registro dos 5 dias e o padrão que percebeu, por exemplo em que horário ou tipo de situação certas emoções aparecem mais."},{"titulo":"Trocar o “Por quê?” pelo “O quê?”","comoFazer":"A psicóloga Tasha Eurich, que estuda autoconhecimento, descobriu que perguntar “por que estou me sentindo assim?” costuma levar a ruminação e desculpas, enquanto perguntar “o quê?” leva a respostas mais úteis. Quando algo te incomodar, pergunte: “O que estou sentindo?”, “O que está acontecendo agora?” e “O que eu posso fazer?”. Pratique em 3 situações ao longo da semana.","comprovacao":"Traga as 3 situações e suas respostas às perguntas."},{"titulo":"Gravar-se explicando algo e assistir depois","comoFazer":"Grave com o celular um vídeo de 2 a 3 minutos explicando algo do seu trabalho, como se falasse com um colega. Depois assista com atenção a postura, expressões do rosto, velocidade da fala, tom de voz e vícios de linguagem (“né”, “tipo”, “então”). É desconfortável no começo, mas é um dos exercícios mais reveladores que existem.","comprovacao":"Traga 3 coisas que percebeu sobre si mesmo e que não sabia."},{"titulo":"Fazer o exercício Intenção x Impacto","comoFazer":"Muitas vezes o que a gente quer passar não é o que o outro recebe. Escolha uma conversa ou mensagem recente que não saiu como esperava e responda por escrito: “O que eu queria transmitir?”, “Como pode ter sido recebido pela outra pessoa?” e “Se fosse hoje, o que eu diria ou faria diferente?”.","comprovacao":"Traga a reflexão escrita."},{"titulo":"Comparar sua autoavaliação com evidências externas","comoFazer":"Escolha um comportamento específico, como “como me comunico em reuniões” ou “como reajo sob pressão”, e dê a você mesmo uma nota de 1 a 5. Depois busque evidências de fora: avaliações de desempenho, feedbacks antigos, reações que você percebeu das pessoas. Se tiver abertura, peça também a nota de 1 ou 2 colegas. A diferença entre sua nota e o que as evidências mostram revela seu ponto cego.","comprovacao":"Traga sua nota, as evidências encontradas e o que aprendeu com a diferença."}]},
{"numero":12,"nome":"Autorregulação","descricao":"Autorregulação é conseguir controlar impulsos e reações emocionais, escolhendo como responder em vez de apenas reagir, especialmente nos momentos de tensão.","tarefas":[{"titulo":"Ler os 3 primeiros capítulos de “O Obstáculo é o Caminho”, de Ryan Holiday","comoFazer":"O livro traz ensinamentos do estoicismo, uma filosofia antiga que ensina a separar o que está sob nosso controle do que não está e a escolher como reagir às dificuldades. A leitura é leve, com muitas histórias reais. Anote as ideias que te marcarem.","comprovacao":"Traga 3 ideias do livro e aplique uma delas a uma situação difícil que está vivendo no trabalho, contando o que mudou."},{"titulo":"Assistir à animação “Divertida Mente 2”","comoFazer":"Nesse filme, a personagem entra na adolescência e novas emoções aparecem, especialmente a Ansiedade, que toma conta do comando. Observe o que acontece com as decisões e o comportamento dela quando uma emoção domina tudo, e como ela reencontra o equilíbrio.","comprovacao":"Traga 3 situações do filme e diga qual teria sido a resposta mais equilibrada em cada uma."},{"titulo":"Aplicar a técnica STOP durante uma semana","comoFazer":"Quando perceber que está prestes a reagir no impulso, com irritação, ansiedade ou pressa, faça o STOP: Stop, pare o que está fazendo; Tome uma respiração profunda; Observe o que está pensando e sentindo; Prossiga, agora escolhendo conscientemente como agir. Leva menos de 1 minuto e muda completamente a resposta.","comprovacao":"Traga 3 situações em que usou o STOP e o que mudou na sua forma de responder."},{"titulo":"Praticar a Respiração Quadrada por 5 dias","comoFazer":"Essa técnica é usada até por militares em situações de estresse. Inspire contando até 4, segure o ar contando até 4, solte contando até 4 e fique sem ar contando até 4. Repita por 2 minutos. Faça uma vez por dia, em um momento tranquilo, para treinar, e use também antes de situações tensas, como uma reunião difícil ou uma conversa delicada.","comprovacao":"Traga o registro dos 5 dias e das situações em que usou a técnica, dizendo se percebeu diferença."},{"titulo":"Criar 5 planos “Se… então…”","comoFazer":"Quando a emoção está alta, fica difícil decidir como reagir, por isso vale decidir antes. Pense em 5 situações que costumam te tirar do sério e escreva a resposta que vai dar. Exemplos: “Se receber uma mensagem que me irrite, então vou esperar 10 minutos antes de responder.” ou “Se alguém me interromper numa reunião, então vou dizer com calma que gostaria de terminar meu raciocínio.”","comprovacao":"Traga os 5 planos e conte quando conseguiu aplicar pelo menos um deles."},{"titulo":"Estudar como alguém que você admira mantém a calma","comoFazer":"Pense em uma pessoa que você admira pela capacidade de manter a calma sob pressão: pode ser alguém da empresa, um atleta, um médico, um líder conhecido. Se for alguém próximo e houver abertura, pergunte: “O que você faz para não reagir no impulso?”. Se não, observe essa pessoa em ação ou procure entrevistas dela e anote o que ela faz nos momentos tensos.","comprovacao":"Traga 3 práticas que identificou e escolha uma para testar nas próximas semanas."}]},
{"numero":13,"nome":"Capacidade Analítica","descricao":"Capacidade analítica é olhar para informações, dados e situações de forma estruturada, separando as partes, encontrando causas e padrões e chegando a conclusões bem fundamentadas, em vez de conclusões apressadas.","tarefas":[{"titulo":"Ler a introdução e os 3 primeiros capítulos de “Rápido e Devagar”, de Daniel Kahneman","comoFazer":"O autor ganhou o Prêmio Nobel estudando como tomamos decisões. Ele explica que temos dois sistemas de pensamento: o Sistema 1, rápido, automático e intuitivo, e o Sistema 2, lento, cuidadoso e analítico. O problema é que usamos o Sistema 1 em situações que pediam o Sistema 2. A leitura exige atenção, então vá com calma.","comprovacao":"Traga uma decisão profissional recente que você tomou “no automático” e que merecia mais análise, e diga como faria usando o Sistema 2."},{"titulo":"Assistir ao filme “A Grande Aposta”","comoFazer":"O filme conta a história real de algumas pessoas que analisaram dados do mercado imobiliário americano e perceberam uma crise enorme antes de todo mundo. Enquanto o mercado achava que estava tudo bem, eles foram a fundo nos números. Repare em como verificam as próprias conclusões antes de agir.","comprovacao":"Traga 3 momentos em que a análise dos personagens contrariou a opinião geral e o que fizeram para confirmar que estavam certos."},{"titulo":"Aplicar os 5 Porquês a um problema que se repete","comoFazer":"Essa técnica foi criada na Toyota para chegar à raiz dos problemas. Escolha um problema recorrente e pergunte “Por que isso acontece?”. Pegue a resposta e pergunte de novo “Por quê?”. Faça isso até 5 vezes. A primeira resposta quase sempre é um sintoma; a causa real costuma aparecer lá pela terceira ou quarta pergunta.","comprovacao":"Traga a sequência dos 5 porquês e a causa raiz encontrada, com uma sugestão para resolvê-la."},{"titulo":"Fazer uma Análise de Pareto","comoFazer":"O Princípio de Pareto diz que, em muitos casos, cerca de 80% dos problemas vêm de uns 20% das causas. Pegue uma lista de erros, reclamações, atrasos ou chamados da sua área (ou das suas próprias pendências). Conte quantas vezes cada causa aparece e ordene da mais para a menos frequente. Veja se poucas causas explicam a maior parte do problema.","comprovacao":"Traga a tabela ou gráfico com o resultado e diga quais causas atacaria primeiro e por quê."},{"titulo":"Separar Fatos, Hipóteses e Opiniões","comoFazer":"Escolha uma situação da sua área que está gerando discussão. Faça 3 colunas: Fatos (o que foi comprovado), Hipóteses (o que se supõe, mas não foi confirmado) e Opiniões (percepções pessoais). Coloque cada informação que você tem na coluna certa. Muitas vezes descobrimos que estávamos tratando opinião como fato.","comprovacao":"Traga o quadro preenchido e diga se alguma conclusão sua mudou depois dessa separação."},{"titulo":"Analisar um indicador a fundo","comoFazer":"Escolha um indicador ou relatório da sua área (vendas, atendimentos, prazos, custos). Responda: Qual é o valor atual? Como ele estava há 3 e há 6 meses? Qual é a meta? O que pode explicar a variação? Que outro dado eu precisaria para confirmar minha explicação? Se alguém da empresa trabalha com dados e tiver disponibilidade, peça 15 minutos para te mostrar como ele lê esse indicador.","comprovacao":"Traga sua análise do indicador em até uma página, com a conclusão e a dúvida que ainda ficou."}]},
{"numero":14,"nome":"Colaboração","descricao":"Colaboração é contribuir ativamente com os outros, compartilhando conhecimento, tempo e esforço para alcançar um objetivo comum, entendendo que o resultado do grupo vale mais do que o brilho individual.","tarefas":[{"titulo":"Ler os 2 primeiros capítulos de “Dar e Receber”, de Adam Grant","comoFazer":"O autor divide as pessoas em três tipos: os doadores, que ajudam sem esperar retorno; os tomadores, que buscam tirar o máximo para si; e os compensadores, que ajudam na mesma medida em que são ajudados. E mostra algo surpreendente: os doadores tendem a chegar mais longe, desde que saibam se proteger.","comprovacao":"Traga sua resposta para “Hoje eu me comporto mais como doador, tomador ou compensador?”, com exemplos do seu trabalho."},{"titulo":"Assistir ao filme “Treze Vidas: O Resgate”","comoFazer":"O filme conta a história real do resgate de 12 meninos e seu treinador presos em uma caverna inundada na Tailândia. Pessoas de vários países e especialidades, que nunca tinham trabalhado juntas, precisaram colaborar para dar certo. Repare em como cada um contribui com o que sabe fazer de melhor.","comprovacao":"Traga 3 momentos em que a colaboração foi decisiva e o que aconteceria se alguém tivesse agido sozinho."},{"titulo":"Assistir ao TED “Esqueça a ordem das bicadas no trabalho”, de Margaret Heffernan","comoFazer":"Nessa palestra, no site do TED e no YouTube, a autora conta um experimento com galinhas e mostra que equipes em que as pessoas se ajudam têm resultados muito melhores do que equipes formadas só por “estrelas” que competem entre si.","comprovacao":"Traga 3 aprendizados da palestra e uma atitude colaborativa que você vai praticar."},{"titulo":"Montar uma Matriz RACI","comoFazer":"Quando muita gente participa de uma entrega, é comum ninguém saber direito quem faz o quê. Escolha uma entrega da sua área e, para cada etapa, indique quem é Responsável (executa), quem Aprova, quem precisa ser Consultado e quem só precisa ser Informado. Monte com base no que você observa; se houver oportunidade, valide com as pessoas envolvidas.","comprovacao":"Traga a matriz preenchida e diga se descobriu alguma etapa sem dono ou com dono demais."},{"titulo":"Oferecer uma ajuda concreta","comoFazer":"Fique atento durante a semana e identifique alguém que está com uma dificuldade em que você pode contribuir. Em vez de dizer “se precisar, estou aqui”, ofereça algo específico: “Quer que eu revise isso?”, “Tenho um modelo pronto que pode te ajudar”. Se não surgir oportunidade direta, crie algo que ajude a equipe como um todo: um modelo, um passo a passo ou um atalho documentado.","comprovacao":"Traga que ajuda você ofereceu ou que material criou e qual foi o impacto."},{"titulo":"Fazer uma retrospectiva de um trabalho em grupo","comoFazer":"Pense em um trabalho recente feito em equipe e responda: “O que funcionou bem?”, “O que atrapalhou?” e “O que eu posso fazer diferente da próxima vez?”. Se for possível reunir as pessoas por 15 minutos, façam juntos; se não, faça a sua própria retrospectiva e compartilhe suas conclusões com o grupo, se fizer sentido.","comprovacao":"Traga as respostas e a melhoria que você (ou o grupo) vai adotar."}]},
{"numero":15,"nome":"Comunicação Assertiva","descricao":"Comunicação assertiva é dizer o que você pensa, precisa e sente de forma clara, direta e respeitosa. Nem passivo, engolindo tudo, nem agressivo, passando por cima dos outros.","tarefas":[{"titulo":"Ler os 3 primeiros capítulos de “Comunicação Não Violenta”, de Marshall Rosenberg","comoFazer":"O autor propõe uma forma de se comunicar baseada em 4 passos: observar o fato sem julgar, dizer o sentimento que ele provoca, explicar a necessidade por trás desse sentimento e fazer um pedido claro. Parece simples, mas muda completamente a forma como os outros recebem o que você diz.","comprovacao":"Pense em uma situação real que está te incomodando e escreva o que diria à pessoa usando os 4 passos. Traga essa fala."},{"titulo":"Assistir ao filme “Erin Brockovich: Uma Mulher de Talento”","comoFazer":"O filme conta a história real de uma mulher que luta contra uma grande empresa. Ela é firme e diz o que pensa, mas às vezes passa do ponto e fica agressiva. É um ótimo filme para perceber a linha entre ser assertivo e ser agressivo.","comprovacao":"Traga 3 cenas classificadas como assertiva, agressiva ou passiva e reescreva uma fala agressiva dela de forma assertiva."},{"titulo":"Aplicar a técnica DESC","comoFazer":"A técnica DESC organiza uma conversa difícil em 4 partes: Descrever o fato, sem julgamento; Expressar o impacto que ele causa; Sugerir o que você precisa; e mostrar a Consequência positiva de mudar. Exemplo: “O relatório chegou às 17h. Com isso, não consegui revisar antes da reunião. Preciso recebê-lo até as 15h, assim chegamos preparados.” Escreva antes o que vai dizer e use em uma conversa ou mensagem real.","comprovacao":"Traga a fala que você estruturou e conte como foi recebida."},{"titulo":"Praticar o “Não com alternativa”","comoFazer":"Muita gente tem dificuldade de dizer não e acaba aceitando tudo, ou nega de um jeito seco. Existe um meio-termo. Quando receber um pedido que não consegue atender, responda oferecendo uma alternativa: “Até amanhã não consigo, mas consigo te entregar na quinta” ou “Tudo eu não consigo, mas consigo fazer essa parte”. Pratique pelo menos 2 vezes.","comprovacao":"Traga as 2 situações, o que você respondeu e como a pessoa reagiu."},{"titulo":"Reescrever mensagens passivas e agressivas","comoFazer":"Escreva uma mensagem no estilo passivo, como “Desculpa incomodar, se não for pedir muito, será que talvez…”, e uma no estilo agressivo, como “Você nunca manda as coisas no prazo”. Depois reescreva as duas de forma assertiva: o fato, o pedido claro e o prazo. Se quiser, use mensagens reais que você já enviou.","comprovacao":"Traga as versões antes e depois, lado a lado."},{"titulo":"Identificar seu estilo de comunicação","comoFazer":"Releia as últimas 10 mensagens importantes que você enviou (e-mails, WhatsApp, chat) e classifique cada uma como passiva, assertiva ou agressiva. Observe se o estilo muda conforme a pessoa: talvez você seja assertivo com colegas e passivo com gestores, por exemplo. Se quiser completar, pergunte a alguém de confiança em qual estilo você costuma se encaixar.","comprovacao":"Traga a classificação das 10 mensagens, o padrão que percebeu e uma mudança concreta que vai fazer."}]},
{"numero":16,"nome":"Comunicação Escrita","descricao":"Comunicação escrita é conseguir transmitir ideias, pedidos e informações por escrito de forma clara, objetiva e bem organizada, para que quem lê entenda de primeira e saiba o que fazer.","tarefas":[{"titulo":"Ler os 3 primeiros capítulos de “Como Escrever Bem”, de William Zinsser","comoFazer":"É um clássico sobre escrita de não ficção, usado por jornalistas e profissionais do mundo todo. O autor defende que escrever bem é, antes de tudo, cortar o que sobra: palavras inúteis, frases longas, termos pomposos. Leia com uma caneta na mão e marque os conselhos que você poderia aplicar nos seus e-mails e relatórios.","comprovacao":"Traga 3 conselhos do livro e um e-mail seu reescrito com base neles (antes e depois)."},{"titulo":"Assistir ao filme “Encontrando Forrester”","comoFazer":"O filme conta a história de um adolescente talentoso que é orientado por um escritor recluso. Há cenas em que o mentor ensina que a primeira versão é para escrever com o coração e a revisão é para escrever com a cabeça. Repare nos conselhos de escrita que aparecem ao longo da história.","comprovacao":"Traga 3 lições sobre escrita que o filme passa e como cada uma pode ajudar na sua rotina."},{"titulo":"Usar a técnica “conclusão primeiro” por uma semana","comoFazer":"No mundo corporativo, muita gente chama essa técnica de BLUF (“a conclusão vem primeiro”). Em vez de contar toda a história e deixar o pedido para o final, comece o e-mail ou mensagem pelo que importa: o que você precisa, até quando e por quê. Depois, se necessário, coloque o contexto. Aplique em todos os e-mails importantes durante uma semana.","comprovacao":"Traga 3 e-mails escritos com a técnica e diga se percebeu respostas mais rápidas ou mais certeiras."},{"titulo":"Fazer o desafio “Corte 30%”","comoFazer":"Pegue um texto que você escreveu recentemente (e-mail, relatório, comunicado) e conte as palavras. Seu desafio é reduzir o texto em 30% sem perder nenhuma informação importante. Corte repetições, frases de enrolação (“venho por meio deste”, “gostaria de informar que”), adjetivos desnecessários e explicações que o leitor não precisa.","comprovacao":"Traga a versão original e a versão cortada, com a contagem de palavras de cada uma."},{"titulo":"Revisar mensagens antigas com olhar de leitor","comoFazer":"Separe 5 e-mails ou mensagens importantes que você enviou no último mês. Leia cada um como se fosse o destinatário e se pergunte: está claro o que eu queria? Tem pedido e prazo? Tem informação faltando ou sobrando? A pessoa respondeu o que eu esperava? Anote os erros que se repetem.","comprovacao":"Traga a análise dos 5 textos e os 3 erros de escrita que você mais comete."},{"titulo":"Criar modelos para suas mensagens mais frequentes","comoFazer":"Identifique 3 tipos de mensagem que você escreve com frequência: pedido de informação, cobrança de prazo, atualização de status, resposta a cliente. Para cada um, crie um modelo bem escrito, com estrutura clara (assunto, contexto curto, pedido, prazo, fechamento). Salve em um lugar de fácil acesso e use nas próximas semanas, adaptando quando necessário.","comprovacao":"Traga os 3 modelos e um exemplo de uso real de cada."}]},
{"numero":17,"nome":"Comunicação Interpessoal","descricao":"Comunicação interpessoal é a habilidade de se relacionar e conversar bem com as pessoas no dia a dia: puxar assunto, perceber como o outro está, ajustar o tom e criar conversas que fluem e aproximam.","tarefas":[{"titulo":"Assistir ao TED “10 maneiras de ter uma conversa melhor”, de Celeste Headlee","comoFazer":"A palestrante é uma jornalista de rádio que entrevistou milhares de pessoas. Em cerca de 12 minutos, ela dá 10 regras práticas para conversar melhor, como não fazer várias coisas ao mesmo tempo, não repetir a mesma coisa e fazer perguntas abertas. Assista no site do TED ou no YouTube e anote as 10 regras.","comprovacao":"Traga as 10 regras, marque as 3 que você mais descumpre e diga como vai praticá-las."},{"titulo":"Assistir ao filme “Amor sem Escalas”","comoFazer":"O personagem de George Clooney vive viajando, é ótimo em conversas rápidas e superficiais, mas tem dificuldade em criar conexões reais. Ao longo do filme, ele vai sendo confrontado com isso. Observe a diferença entre as conversas “de protocolo” e as conversas que realmente aproximam as pessoas.","comprovacao":"Traga 2 exemplos de conversa superficial e 2 de conversa com conexão real do filme, e diga qual tipo predomina no seu dia a dia."},{"titulo":"Observar a comunicação não verbal em uma reunião","comoFazer":"Na próxima reunião (presencial ou por vídeo), dedique parte da atenção a observar os sinais não verbais: quem se inclina para frente, quem cruza os braços, quem olha para o celular, quem muda o tom de voz, quem fica em silêncio. Não é para julgar ninguém, e sim para treinar o olhar. Depois, observe também os seus próprios sinais.","comprovacao":"Traga 5 sinais que você percebeu, o que eles poderiam indicar e um sinal seu que gostaria de ajustar."},{"titulo":"Praticar o “puxar assunto” com perguntas abertas","comoFazer":"Durante uma semana, em pelo menos 3 interações do dia a dia (com colegas, atendentes, pessoas de outras áreas, até no elevador), troque perguntas fechadas por perguntas abertas. Em vez de “Tudo bem?”, tente “Como está sendo sua semana?”, “O que você está achando desse projeto?”, “Como foi que você começou nessa área?”. Não precisa ser uma conversa longa: 2 ou 3 minutos já contam.","comprovacao":"Traga as 3 interações, as perguntas que usou e o que descobriu sobre as pessoas."},{"titulo":"Mapear os estilos de comunicação das pessoas com quem mais convive","comoFazer":"Pense nas 5 pessoas com quem você mais conversa no trabalho. Para cada uma, anote: ela prefere conversas diretas ou com mais contexto? Mais rápidas ou mais detalhadas? Mais formais ou descontraídas? Prefere mensagem, ligação ou conversa pessoalmente? Depois pense em como você pode ajustar seu jeito de falar com cada uma.","comprovacao":"Traga o mapa das 5 pessoas e um ajuste que vai fazer com pelo menos 2 delas."},{"titulo":"Manter um Diário de Interações por 5 dias","comoFazer":"Ao final de cada dia, escolha uma interação que foi muito boa e uma que poderia ter sido melhor. Para cada uma, anote em 2 ou 3 linhas: o que aconteceu, o que você fez que ajudou ou atrapalhou e o que faria diferente.","comprovacao":"Traga os registros dos 5 dias e o comportamento que mais apareceu nas interações que deram certo."}]},
{"numero":18,"nome":"Comunicação Verbal","descricao":"Comunicação verbal é a capacidade de falar com clareza, boa dicção, ritmo e segurança, seja em uma conversa, numa reunião ou numa apresentação, fazendo com que as pessoas entendam e prestem atenção.","tarefas":[{"titulo":"Assistir ao TED “Como falar de um jeito que as pessoas queiram ouvir”, de Julian Treasure","comoFazer":"O palestrante é especialista em som e comunicação. Ele fala sobre os “7 pecados capitais da fala” (como fofoca, julgamento, reclamação e exagero) e sobre ferramentas da voz: tom, ritmo, volume e timbre. No final, ele ensina um aquecimento vocal. Assista no site do TED ou no YouTube e faça o aquecimento junto.","comprovacao":"Traga os 7 pecados, diga quais você mais comete e como vai usar pelo menos uma ferramenta da voz na próxima semana."},{"titulo":"Ler os 3 primeiros capítulos de “TED Talks: O Guia Oficial do TED para Falar em Público”, de Chris Anderson","comoFazer":"O autor é o responsável pelas palestras TED e reúne o que aprendeu vendo milhares de apresentações. Ele mostra que uma boa fala não depende de talento, mas de ter uma ideia clara e saber construí-la para quem ouve. Leia anotando as dicas que servem para reuniões e apresentações do seu trabalho.","comprovacao":"Traga 3 dicas do livro e como vai aplicá-las na sua próxima fala importante."},{"titulo":"Assistir ao filme “O Grande Desafio”, com Denzel Washington","comoFazer":"O filme conta a história real de um professor que forma uma equipe de debate em uma faculdade dos anos 1930. Há cenas de treino de dicção, argumentação e postura. Observe como os alunos evoluem na forma de falar e o que o professor exige deles.","comprovacao":"Traga 3 técnicas de fala que aparecem no filme e escolha uma para treinar."},{"titulo":"Contar seus vícios de linguagem","comoFazer":"Grave com o celular um áudio ou vídeo de 3 minutos explicando algo do seu trabalho, sem roteiro. Depois ouça e conte quantas vezes você usou vícios como “né”, “tipo”, “então”, “aí”, “é…”. Escolha o vício mais frequente e, durante uma semana, tente trocá-lo por uma pausa silenciosa. Grave de novo no final da semana e compare.","comprovacao":"Traga a contagem da primeira e da segunda gravação."},{"titulo":"Treinar a “Regra de 3” para explicar qualquer assunto","comoFazer":"Nosso cérebro guarda melhor informações organizadas em 3 partes. Escolha 3 temas do seu trabalho e prepare, para cada um, uma explicação de até 1 minuto dividida em 3 pontos (por exemplo: o que é, por que importa, o que fazer). Treine em voz alta até conseguir falar sem ler.","comprovacao":"Traga os 3 roteiros e uma gravação de pelo menos um deles."},{"titulo":"Ler em voz alta por 5 minutos durante 7 dias","comoFazer":"Escolha um texto qualquer (uma notícia, um capítulo de livro, um artigo) e leia em voz alta por 5 minutos todos os dias, prestando atenção à pronúncia de cada palavra, às pausas nas vírgulas e pontos e à variação do tom de voz. É um exercício simples usado por locutores e atores para melhorar a dicção e a fluência.","comprovacao":"Traga o registro dos 7 dias (o que leu em cada dia) e uma gravação do primeiro e do último dia para comparar."}]},
{"numero":19,"nome":"Criatividade","descricao":"Criatividade é a capacidade de gerar ideias novas, enxergar possibilidades diferentes e combinar coisas de um jeito original para resolver problemas ou melhorar o que já existe.","tarefas":[{"titulo":"Ler o livro “Roube Como um Artista”, de Austin Kleon","comoFazer":"É um livro curto e muito visual, que dá para ler em uma ou duas tardes. O autor mostra que ninguém cria do nada: toda ideia nova vem da combinação de ideias que já existem. Ele dá 10 conselhos práticos para ser mais criativo no dia a dia. Leia marcando os conselhos que mais combinam com você.","comprovacao":"Traga os 3 conselhos que mais fizeram sentido e uma ação concreta para cada um."},{"titulo":"Assistir ao primeiro episódio da série “Abstract: The Art of Design”, na Netflix","comoFazer":"Cada episódio acompanha um designer de uma área diferente (ilustração, arquitetura, calçados, fotografia) e mostra como ele pensa e cria. Assista ao primeiro episódio (ou a outro que chamar sua atenção) observando o processo criativo: de onde vêm as ideias, como a pessoa testa, erra e refaz.","comprovacao":"Traga 3 hábitos ou práticas criativas que você viu no episódio e como poderia adaptá-los ao seu trabalho."},{"titulo":"Assistir ao TED “As escolas matam a criatividade?”, de Ken Robinson","comoFazer":"É uma das palestras mais assistidas da história do TED. Com muito humor, o autor mostra como perdemos a criatividade ao longo da vida por medo de errar. Assista no site do TED ou no YouTube e reflita sobre em que momentos você deixa de propor algo por medo de parecer bobo.","comprovacao":"Traga 3 ideias da palestra e uma situação em que você “matou” uma ideia sua antes de testá-la."},{"titulo":"Aplicar a técnica SCAMPER em um processo ou produto","comoFazer":"SCAMPER é uma lista de 7 perguntas para gerar ideias a partir de algo que já existe: Substituir (o que posso trocar?), Combinar (o que posso juntar?), Adaptar (o que posso copiar de outro lugar?), Modificar (o que posso aumentar ou diminuir?), Propor outro uso, Eliminar (o que posso tirar?) e Reorganizar (o que posso inverter ou mudar de ordem?). Escolha uma atividade do seu trabalho e responda às 7 perguntas.","comprovacao":"Traga as respostas das 7 perguntas e a ideia que você considera mais viável."},{"titulo":"Fazer o desafio dos 30 círculos","comoFazer":"Esse exercício é usado em escolas de design. Desenhe 30 círculos numa folha. Em 3 minutos cronometrados, transforme o máximo de círculos que conseguir em objetos diferentes (uma bola, um relógio, um rosto, uma roda…). Não se preocupe com a qualidade do desenho. Depois repita no dia seguinte e compare. O exercício treina quantidade de ideias e mostra o quanto nos censuramos.","comprovacao":"Traga uma foto das duas folhas e diga quantos círculos você transformou em cada tentativa."},{"titulo":"Manter um Caderno de Ideias por 7 dias","comoFazer":"Durante 7 dias, anote pelo menos 3 ideias por dia sobre qualquer coisa do seu trabalho: um processo que poderia ser melhor, uma forma diferente de atender um cliente, um jeito mais rápido de fazer um relatório. Não filtre, não julgue, apenas escreva. No final da semana, releia tudo e escolha a melhor ideia.","comprovacao":"Traga o caderno com as 21 ideias e diga qual escolheu e por quê."}]},
{"numero":20,"nome":"Curiosidade","descricao":"Curiosidade é o interesse genuíno em entender como as coisas funcionam, fazer perguntas, explorar temas novos e não se contentar com a primeira resposta.","tarefas":[{"titulo":"Ler a introdução e o capítulo 1 de “Uma Breve História de Quase Tudo”, de Bill Bryson","comoFazer":"O autor decidiu, já adulto, entender como o universo funciona e escreveu um livro divertidíssimo sobre ciência para quem não é cientista. É um ótimo exemplo de curiosidade em ação. Leia e anote todas as perguntas que surgirem na sua cabeça durante a leitura.","comprovacao":"Traga a lista de perguntas que surgiram e pesquise a resposta de pelo menos 2 delas."},{"titulo":"Assistir a 2 episódios da série “Explicando”, na Netflix","comoFazer":"Cada episódio tem cerca de 20 minutos e explica um tema diferente: o mercado de ações, o cérebro, a música, os diamantes, a monogamia. Escolha 2 episódios sobre temas que você não conhece nada. O objetivo é sair da sua “bolha” de interesses.","comprovacao":"Traga 3 coisas que você aprendeu em cada episódio e uma pergunta nova que ficou na sua cabeça."},{"titulo":"Ouvir 3 episódios do podcast “Naruhodo!”","comoFazer":"É um podcast brasileiro de divulgação científica que responde perguntas curiosas do dia a dia, como “Por que a gente procrastina?” ou “Multitarefa funciona?”. Os episódios são curtos e leves. Escolha 3 com temas que tenham alguma relação com o trabalho ou com comportamento humano.","comprovacao":"Traga o título dos 3 episódios e o que você aprendeu em cada um."},{"titulo":"Manter um Diário de Perguntas por 5 dias","comoFazer":"Todos os dias, anote pelo menos 5 perguntas que surgirem no trabalho: “Por que esse processo é feito assim?”, “Para onde vai esse relatório depois que eu envio?”, “Como a área X trabalha?”. No fim de cada dia, escolha uma pergunta e vá atrás da resposta: pesquisando, lendo documentos ou perguntando a alguém.","comprovacao":"Traga as 25 perguntas e as 5 respostas que encontrou."},{"titulo":"Investigar uma área diferente da sua","comoFazer":"Escolha uma área da empresa sobre a qual você sabe pouco. Investigue: o que ela faz, quais são seus principais processos, quais indicadores acompanha, como seu trabalho se conecta com ela. Use a intranet, documentos, apresentações institucionais, o site da empresa. Se alguém dessa área tiver disponibilidade, uma conversa de 15 minutos enriquece muito a investigação.","comprovacao":"Traga um resumo de uma página sobre a área e 2 conexões que descobriu entre ela e o seu trabalho."},{"titulo":"Fazer o desafio “Como isso funciona?”","comoFazer":"Escolha algo do seu trabalho que você usa todo dia sem saber exatamente como funciona: um sistema, um indicador, um cálculo, um processo de aprovação. Vá atrás de entender de ponta a ponta: de onde vêm os dados, quem mexe, que regras existem, o que acontece depois. Vá até onde conseguir sozinho.","comprovacao":"Traga uma explicação, em até uma página ou um desenho, de como aquilo funciona."}]},
{"numero":21,"nome":"Decisões Ágeis","descricao":"Decisões ágeis é conseguir decidir com rapidez e segurança suficiente, mesmo sem ter 100% das informações, sabendo diferenciar o que pede cautela do que pode ser decidido na hora.","tarefas":[{"titulo":"Ler a introdução e os 2 primeiros capítulos de “Blink: A Decisão Num Piscar de Olhos”, de Malcolm Gladwell","comoFazer":"O autor mostra que, em muitas situações, decisões tomadas em segundos podem ser tão boas quanto decisões longamente pensadas, desde que a pessoa tenha experiência naquele assunto. Mas também mostra quando a intuição engana. Leia pensando nas decisões que você toma no dia a dia.","comprovacao":"Traga 2 situações do seu trabalho em que decidir rápido faz sentido e 1 em que a intuição pode te enganar."},{"titulo":"Assistir ao filme “Sully: O Herói do Rio Hudson”","comoFazer":"O filme conta a história real do piloto que pousou um avião no rio Hudson, em Nova York, depois que os dois motores pararam. Ele teve 208 segundos para decidir. Depois, a investigação questionou se a decisão foi certa. Observe como ele usou experiência, informação disponível e calma para decidir sob pressão.","comprovacao":"Traga o que permitiu ao piloto decidir tão rápido e bem, e uma lição para as suas decisões do dia a dia."},{"titulo":"Aplicar a “Regra dos 70%”","comoFazer":"Jeff Bezos, fundador da Amazon, defende que a maioria das decisões deve ser tomada quando você tem cerca de 70% das informações que gostaria de ter. Esperar por 90% geralmente significa decidir tarde demais. Durante uma semana, sempre que perceber que está adiando uma decisão, pergunte: “Já tenho uns 70% do que preciso?”. Se sim, decida.","comprovacao":"Traga 3 decisões que tomou com a regra e se algo deu errado por decidir antes."},{"titulo":"Separar decisões “de porta de mão única” e “de porta de mão dupla”","comoFazer":"Outra ideia da Amazon: algumas decisões são como portas de mão única, difíceis ou impossíveis de desfazer (merecem mais cuidado). Outras são portas de mão dupla, fáceis de reverter se der errado (podem ser tomadas rápido). Liste 10 decisões que você costuma enfrentar e classifique cada uma.","comprovacao":"Traga a lista classificada e diga quais decisões de mão dupla você tem demorado demais para tomar."},{"titulo":"Usar o “limite de tempo” para decidir","comoFazer":"Durante uma semana, para decisões pequenas e médias, defina antes quanto tempo vai gastar decidindo: 2 minutos para escolhas simples, 15 minutos para escolhas médias. Coloque um cronômetro. Quando o tempo acabar, escolha a melhor opção que tiver naquele momento. Isso combate a “paralisia por análise”.","comprovacao":"Traga o registro de pelo menos 5 decisões, o tempo definido e se o resultado foi bom."},{"titulo":"Reduzir as opções a no máximo 3","comoFazer":"Muitas opções travam a decisão. Da próxima vez que precisar escolher algo (um fornecedor, um formato de relatório, uma forma de resolver um problema), elimine rapidamente as opções mais fracas até ficar com no máximo 3. Depois compare só essas 3 e decida.","comprovacao":"Traga a decisão, as opções iniciais, as 3 finalistas e o critério que usou para escolher."}]},
{"numero":22,"nome":"Delegação","descricao":"Delegação é saber passar responsabilidades para outras pessoas de forma clara, confiando, dando autonomia e acompanhando na medida certa, para liberar seu tempo para o que só você pode fazer.","tarefas":[{"titulo":"Ler o artigo clássico “Quem está com o macaco?”, de William Oncken e Donald Wass","comoFazer":"É um dos artigos mais famosos da Harvard Business Review sobre gestão do tempo e delegação. O “macaco” é a próxima ação de um problema. Os autores mostram como gestores acabam carregando os macacos da equipe nas costas. Procure pelo título e pelos autores (há vários resumos disponíveis na internet) e leia com atenção.","comprovacao":"Traga 2 “macacos” que você está carregando e que deveriam estar com outra pessoa, e como vai devolvê-los."},{"titulo":"Assistir ao filme “O Diabo Veste Prada”","comoFazer":"A personagem de Meryl Streep é uma chefe que delega o tempo todo, mas de um jeito que gera muita confusão: pedidos vagos, sem contexto, sem prazo claro. Assista observando como ela delega e como a assistente precisa “adivinhar” o que ela quer.","comprovacao":"Traga 3 erros de delegação que aparecem no filme e como cada um poderia ser feito da forma certa."},{"titulo":"Conhecer os 7 níveis de delegação","comoFazer":"Jurgen Appelo criou uma escala com 7 níveis de delegação, do “eu decido e aviso” até o “você decide e nem precisa me contar”. Pesquise por “7 níveis de delegação Appelo” ou “Delegation Poker”. Depois escolha 5 decisões ou tarefas do seu dia a dia e defina em qual nível cada uma poderia ser delegada.","comprovacao":"Traga as 5 tarefas com o nível de delegação escolhido e a justificativa."},{"titulo":"Fazer o inventário “só eu posso fazer?”","comoFazer":"Liste todas as atividades que você fez na última semana. Ao lado de cada uma, responda: “Só eu posso fazer isso?”. Se a resposta for não, anote quem mais poderia fazer, se poderia ser automatizado ou se simplesmente poderia deixar de ser feito.","comprovacao":"Traga o inventário e as 3 atividades com maior potencial de serem delegadas, automatizadas ou eliminadas."},{"titulo":"Criar um “brief de delegação”","comoFazer":"Quando delegamos mal, o trabalho volta errado. Crie um modelo de brief com: o que precisa ser feito, por que isso importa, qual é o resultado esperado, prazo, nível de autonomia, recursos disponíveis e quando vão conversar para acompanhar. Preencha o modelo com uma tarefa real que você poderia passar para alguém.","comprovacao":"Traga o modelo e um exemplo preenchido."},{"titulo":"Delegar (ou compartilhar) uma tarefa real","comoFazer":"Se você tem equipe, escolha uma tarefa do inventário e delegue usando o brief. Combine um ponto de acompanhamento e resista à vontade de refazer do seu jeito. Se você não tem equipe, aplique a mesma lógica com outras formas de “delegar”: automatize uma tarefa com uma ferramenta, crie um modelo que outra pessoa possa usar sozinha ou combine uma troca de tarefas com um colega.","comprovacao":"Traga o que foi delegado ou automatizado, como foi o acompanhamento e qual foi o resultado."}]},
{"numero":23,"nome":"Disciplina","descricao":"Disciplina é fazer o que precisa ser feito, com constância, mesmo quando falta vontade. É criar hábitos e manter compromissos com você mesmo ao longo do tempo.","tarefas":[{"titulo":"Ler os 4 primeiros capítulos de “Hábitos Atômicos”, de James Clear","comoFazer":"É um dos livros mais populares sobre hábitos. O autor mostra que grandes resultados vêm de pequenas melhorias diárias (1% melhor a cada dia) e explica como hábitos são formados: sinal, desejo, resposta e recompensa. Leia com calma e pense em um hábito profissional que gostaria de criar.","comprovacao":"Traga o hábito escolhido e como vai aplicar as ideias do livro para construí-lo."},{"titulo":"Assistir ao filme “Whiplash: Em Busca da Perfeição”","comoFazer":"O filme conta a história de um jovem baterista que treina de forma obsessiva sob um professor extremamente exigente. É um filme intenso sobre disciplina, mas também sobre os limites dela. Assista com olhar crítico: o que é disciplina saudável e o que passa do ponto?","comprovacao":"Traga 2 exemplos de disciplina saudável e 2 de disciplina que passa do ponto, e diga onde você está hoje."},{"titulo":"Aplicar a técnica “Não quebre a corrente” por 21 dias","comoFazer":"Essa técnica é atribuída ao comediante Jerry Seinfeld, que escrevia piadas todos os dias. Escolha um hábito pequeno (ler 10 páginas, planejar o dia, revisar pendências). Imprima um calendário e, cada dia que cumprir o hábito, faça um X grande. Depois de alguns dias, você terá uma “corrente” de X, e seu único objetivo é não quebrá-la.","comprovacao":"Traga uma foto do calendário ao final dos 21 dias."},{"titulo":"Usar o “empilhamento de hábitos”","comoFazer":"Também do livro Hábitos Atômicos: em vez de criar um hábito do nada, “cole” o novo hábito em um que você já tem. A fórmula é: “Depois de [hábito atual], eu vou [novo hábito]”. Exemplo: “Depois de ligar o computador, vou listar as 3 prioridades do dia.” Crie 3 empilhamentos e pratique por 2 semanas.","comprovacao":"Traga os 3 empilhamentos e quantos dias conseguiu cumprir cada um."},{"titulo":"Montar uma rotina de início de expediente","comoFazer":"Crie uma rotina de 10 a 15 minutos para os primeiros momentos do seu dia de trabalho, sempre na mesma ordem. Por exemplo: revisar a agenda, checar pendências, definir 3 prioridades, só então abrir e-mail. Escreva a rotina em um papel e siga por 10 dias úteis, mesmo nos dias corridos.","comprovacao":"Traga a rotina escrita e o registro dos 10 dias, marcando os dias em que conseguiu cumprir."},{"titulo":"Escrever um “contrato” com você mesmo","comoFazer":"Escolha uma meta profissional que depende de disciplina (estudar algo, organizar arquivos, fazer um curso). Escreva um contrato simples: o que vai fazer, com que frequência, por quanto tempo, como vai medir e o que fará se falhar um dia (por exemplo, “nunca falhar dois dias seguidos”). Assine e deixe à vista.","comprovacao":"Traga o contrato e, ao final do período, o resultado alcançado."}]},
{"numero":24,"nome":"Empatia","descricao":"Empatia é a capacidade de compreender perspectivas, sentimentos e necessidades diferentes das suas e considerar essas informações na forma de se comunicar, agir e tomar decisões.","tarefas":[{"titulo":"Ler os 3 primeiros capítulos do livro “O Poder da Empatia”, de Roman Krznaric","comoFazer":"O autor mostra formas práticas de desenvolver a capacidade de se colocar no lugar do outro, com exemplos históricos e do dia a dia. Durante a leitura, anote pelo menos 3 comportamentos ou ideias que possam ser aplicados nas suas relações profissionais.","comprovacao":"Traga os 3 aprendizados e escolha um para responder: “Como posso aplicar isso na minha rotina de trabalho?”"},{"titulo":"Assistir ao filme “Extraordinário”","comoFazer":"O filme conta a história de um menino com uma diferença facial que começa a frequentar a escola. A história é contada pela perspectiva de vários personagens, o que mostra como cada um vive a mesma situação de um jeito diferente. Escolha 3 situações em que a atitude de um personagem poderia ter sido diferente se ele considerasse melhor a perspectiva do outro.","comprovacao":"Traga as 3 situações e explique qual comportamento demonstraria mais empatia em cada uma."},{"titulo":"Assistir ao TED “O poder da vulnerabilidade”, de Brené Brown","comoFazer":"Nessa palestra, no site do TED e no YouTube, a pesquisadora fala sobre conexão humana, pertencimento e sobre como a vulnerabilidade aproxima as pessoas. Preste atenção especial às partes sobre compreender a experiência do outro sem julgar.","comprovacao":"Traga 3 aprendizados da palestra e diga qual deles é mais aplicável às relações profissionais."},{"titulo":"Fazer o desafio das 3 perguntas antes de aconselhar","comoFazer":"Da próxima vez que alguém trouxer uma dificuldade para você, evite oferecer uma solução imediatamente. Primeiro faça 3 perguntas abertas: “O que está sendo mais difícil nessa situação?”, “Como isso está te afetando?” e “O que você acha que ajudaria agora?”. Só depois responda ou sugira algo. Vale para colegas, clientes, amigos ou familiares.","comprovacao":"Traga um registro curto da situação, das respostas que ouviu e se sua percepção inicial mudou depois de ouvir melhor."},{"titulo":"Aplicar o exercício de mudança de perspectiva","comoFazer":"Escolha uma situação recente em que você discordou de alguém (colega, gestor, cliente). Faça duas colunas: “Minha perspectiva” e “Possível perspectiva da outra pessoa”. Na segunda coluna, escreva pelo menos 3 preocupações, pressões ou motivos que poderiam explicar o comportamento dela. Tente escrever como se fosse ela.","comprovacao":"Traga o exercício preenchido e responda: “O que passei a enxergar que não tinha considerado antes?”"},{"titulo":"Conhecer a realidade de uma área diferente da sua","comoFazer":"Escolha uma área com a qual você interage e que às vezes gera atrito. Se tiver oportunidade, converse 15 minutos com alguém de lá e pergunte: “Quais são as maiores dificuldades da sua rotina?” e “O que as outras áreas costumam não perceber sobre o seu trabalho?”. Se não for possível, investigue por conta própria: leia os processos dessa área, observe as demandas que ela recebe e imagine um dia de trabalho de alguém de lá.","comprovacao":"Traga 3 coisas que descobriu sobre a realidade dessa área e uma atitude que vai adotar para facilitar a relação com ela."}]},
{"numero":25,"nome":"Escuta Ativa","descricao":"Escuta ativa é ouvir com atenção total, para entender de verdade o que o outro está dizendo (e sentindo), em vez de apenas esperar a sua vez de falar.","tarefas":[{"titulo":"Assistir ao TED “5 maneiras de escutar melhor”, de Julian Treasure","comoFazer":"Em cerca de 8 minutos, o palestrante mostra que estamos perdendo a capacidade de escutar e ensina 5 exercícios simples para treinar a escuta, como o “silêncio” de 3 minutos por dia e o “saborear” os sons do ambiente. Assista no site do TED ou no YouTube e anote os 5 exercícios.","comprovacao":"Traga os 5 exercícios e pratique pelo menos 2 deles durante uma semana, contando como foi."},{"titulo":"Assistir ao filme “Gênio Indomável”","comoFazer":"O filme conta a história de um jovem brilhante e difícil que só começa a mudar quando encontra um terapeuta que realmente o escuta. Repare nas cenas de terapia: como o terapeuta, interpretado por Robin Williams, escuta, faz silêncio, devolve perguntas e percebe o que não está sendo dito.","comprovacao":"Traga 3 comportamentos de escuta do terapeuta e como pode usá-los nas suas conversas de trabalho."},{"titulo":"Praticar a paráfrase em conversas","comoFazer":"Parafrasear é repetir, com suas palavras, o que a outra pessoa disse, para confirmar que entendeu. Exemplo: “Então, se eu entendi bem, o que está te preocupando é o prazo, e não a qualidade, é isso?”. Durante uma semana, use a paráfrase em pelo menos 3 conversas importantes (com colegas, clientes ou mesmo em casa).","comprovacao":"Traga as 3 situações e diga se a paráfrase revelou algum mal-entendido."},{"titulo":"Aplicar a “regra dos 3 segundos”","comoFazer":"Muitas vezes começamos a responder antes do outro terminar. Durante uma semana, quando alguém terminar de falar, espere mentalmente 3 segundos antes de responder. Esse pequeno silêncio mostra que você está escutando e muitas vezes faz a outra pessoa completar o raciocínio com algo importante.","comprovacao":"Traga 3 situações em que o silêncio trouxe uma informação nova ou mudou o rumo da conversa."},{"titulo":"Treinar a escuta com um podcast de entrevista","comoFazer":"Escolha um episódio de um podcast de entrevista de uns 30 minutos. Ouça sem pausar e sem fazer outra coisa ao mesmo tempo. Depois, sem voltar o áudio, escreva: as 3 principais ideias do entrevistado, uma emoção que ele demonstrou e uma pergunta que você faria a ele. Só então ouça de novo para conferir.","comprovacao":"Traga seu resumo e o que você deixou passar na primeira escuta."},{"titulo":"Contar suas interrupções","comoFazer":"Em 3 reuniões ou conversas ao longo da semana, faça um risquinho discreto no papel toda vez que interromper alguém, completar a frase do outro ou mudar de assunto para falar de você. Não é para se culpar, e sim para tomar consciência. Na semana seguinte, tente reduzir pela metade.","comprovacao":"Traga a contagem da primeira e da segunda semana."}]},
{"numero":26,"nome":"Estratégia de Longo Alcance","descricao":"Estratégia de longo alcance é pensar e agir considerando os próximos anos, e não só as próximas semanas: fazer escolhas hoje que constroem o futuro que se deseja, mesmo quando o resultado demora a aparecer.","tarefas":[{"titulo":"Ler a introdução e o capítulo 1 de “Feitas para Durar”, de Jim Collins e Jerry Porras","comoFazer":"Os autores estudaram empresas que se mantiveram fortes por décadas e compararam com concorrentes que não tiveram o mesmo sucesso. Uma das conclusões é que essas empresas pensam no longo prazo e têm valores claros que não mudam com a moda do momento. Leia pensando na sua empresa e na sua própria carreira.","comprovacao":"Traga 3 características das empresas “feitas para durar” e se você as enxerga na sua empresa."},{"titulo":"Ler a carta de 1997 de Jeff Bezos aos acionistas da Amazon","comoFazer":"Nessa carta, que ficou famosa, o fundador da Amazon explica que a empresa tomaria decisões pensando no longo prazo, mesmo que isso significasse lucros menores nos primeiros anos. Procure por “carta de Jeff Bezos aos acionistas 1997” (há traduções e resumos disponíveis) e leia com atenção.","comprovacao":"Traga 3 princípios de longo prazo da carta e um exemplo de decisão da sua área que seria diferente se seguisse esse pensamento."},{"titulo":"Aplicar o “backcasting” à sua carreira ou área","comoFazer":"Backcasting é planejar de trás para frente. Imagine com detalhes onde você (ou sua área) quer estar daqui a 5 anos. Depois volte: o que precisa ter acontecido em 3 anos para chegar lá? E em 1 ano? E nos próximos 3 meses? No final, você terá passos concretos que conectam o hoje ao futuro desejado.","comprovacao":"Traga o plano de trás para frente, do objetivo de 5 anos até as ações dos próximos 3 meses."},{"titulo":"Usar a regra 10-10-10 em uma decisão","comoFazer":"Essa técnica, criada pela jornalista Suzy Welch, ajuda a sair do imediatismo. Diante de uma decisão, pergunte: “Quais serão as consequências disso daqui a 10 minutos? E daqui a 10 meses? E daqui a 10 anos?”. Muitas decisões que parecem ótimas agora são ruins no longo prazo, e vice-versa. Aplique em uma decisão real, profissional ou pessoal.","comprovacao":"Traga a decisão analisada nos 3 horizontes de tempo e o que decidiu."},{"titulo":"Analisar o relatório anual de uma grande empresa brasileira","comoFazer":"Grandes empresas de capital aberto publicam relatórios anuais e de sustentabilidade no site de Relações com Investidores (RI). Escolha uma empresa que você admira (pode ser a sua) e leia a mensagem do presidente e a parte de estratégia. Identifique quais apostas de longo prazo ela está fazendo.","comprovacao":"Traga um resumo de uma página com as principais apostas de longo prazo da empresa e o que você achou delas."},{"titulo":"Montar um plano de desenvolvimento de 3 anos","comoFazer":"Defina onde quer estar profissionalmente daqui a 3 anos e divida em metas anuais. Para cada ano, liste: que competências precisa desenvolver, que experiências precisa viver, que resultados precisa mostrar. Depois escolha a primeira ação que pode fazer ainda este mês.","comprovacao":"Traga o plano de 3 anos e a primeira ação já realizada."}]},
{"numero":27,"nome":"Ética Profissional","descricao":"Ética profissional é agir com integridade, honestidade e respeito no trabalho, seguindo princípios mesmo quando ninguém está olhando e mesmo quando o caminho errado parece mais fácil ou vantajoso.","tarefas":[{"titulo":"Ler o livro “Ética e Vergonha na Cara!”, de Mario Sergio Cortella e Clóvis de Barros Filho","comoFazer":"É um livro curto, em formato de conversa entre dois dos filósofos mais conhecidos do Brasil. Eles falam sobre ética no dia a dia, no trabalho e na política, com exemplos bem brasileiros, como o famoso “jeitinho”. Leia anotando as ideias que te fizeram refletir.","comprovacao":"Traga 3 ideias do livro e uma situação do seu dia a dia em que ela se aplica."},{"titulo":"Assistir ao filme “O Informante”","comoFazer":"O filme conta a história real de um executivo da indústria do tabaco que decide revelar que as empresas sabiam dos riscos do cigarro. Ele enfrenta pressões enormes e precisa escolher entre a segurança pessoal e o que acredita ser certo. Observe os dilemas de cada personagem.","comprovacao":"Traga os principais dilemas éticos que aparecem no filme e como você agiria no lugar do protagonista."},{"titulo":"Assistir ao episódio sobre a Volkswagen da série documental “Dinheiro Sujo”, na Netflix","comoFazer":"O episódio mostra como a Volkswagen fraudou testes de emissão de poluentes de milhões de carros. É um ótimo estudo de caso sobre como pequenas concessões éticas, somadas, levam a um escândalo enorme. Repare em quem sabia, quem ficou calado e por quê.","comprovacao":"Traga em que momentos alguém poderia ter feito diferente e o que isso ensina sobre “pequenas concessões”."},{"titulo":"Ler o Código de Ética ou Conduta da sua empresa","comoFazer":"Quase toda empresa tem um código de ética ou conduta, geralmente disponível na intranet ou no site. Leia com atenção, não como obrigação, mas procurando entender o que ele exige na prática. Identifique as regras que mais se aplicam ao seu dia a dia e os canais para relatar problemas.","comprovacao":"Traga as 5 regras mais relevantes para sua função e uma situação prática para cada uma."},{"titulo":"Aplicar o “Teste da Primeira Página”","comoFazer":"Antes de uma decisão em que você fica em dúvida se é correta, faça o teste: “Eu ficaria confortável se essa decisão fosse publicada na primeira página de um jornal, com meu nome, para minha família e meus colegas lerem?”. Se a resposta for não, algo está errado. Pense em 3 situações (reais ou possíveis) do seu trabalho e aplique o teste.","comprovacao":"Traga as 3 situações e o resultado do teste em cada uma."},{"titulo":"Resolver 3 dilemas éticos por escrito","comoFazer":"Escreva como agiria em cada situação: 1) Você percebe que um colega registrou horas que não trabalhou. 2) Um fornecedor oferece um presente caro no fim do ano. 3) Seu gestor pede para “ajustar” um número de um relatório para parecer melhor. Para cada uma, responda: o que eu faria, por quê, e o que poderia dificultar agir assim.","comprovacao":"Traga as 3 respostas justificadas."}]},
{"numero":28,"nome":"Flexibilidade","descricao":"Flexibilidade é estar aberto a outras formas de fazer, outras opiniões e outras soluções, conseguindo mudar de posição quando surgem bons argumentos, sem se prender ao “sempre foi assim”.","tarefas":[{"titulo":"Assistir ao TED “Por que você acha que está certo, mesmo quando está errado”, de Julia Galef","comoFazer":"A palestrante mostra a diferença entre a “mentalidade de soldado”, que defende suas ideias a qualquer custo, e a “mentalidade de explorador”, que quer entender a realidade, mesmo que isso signifique mudar de ideia. Assista no site do TED ou no YouTube.","comprovacao":"Traga uma situação em que você agiu como “soldado” e como seria agir como “explorador”."},{"titulo":"Assistir ao filme “O Terminal”","comoFazer":"O filme conta a história de um homem que fica preso no aeroporto de Nova York por meses, sem poder entrar no país nem voltar ao seu. Em vez de se desesperar, ele se adapta com criatividade a cada limitação. Observe como ele encontra soluções flexíveis para problemas que pareciam sem saída.","comprovacao":"Traga 3 exemplos de flexibilidade do personagem e uma situação sua em que você poderia agir parecido."},{"titulo":"Aplicar a técnica “Steelman”","comoFazer":"Ao contrário do “espantalho” (distorcer o argumento do outro para ficar fácil de derrubar), o Steelman é construir a versão mais forte possível do argumento contrário ao seu. Escolha um tema do trabalho sobre o qual você tem opinião forte e escreva o melhor argumento possível do outro lado, como se você acreditasse nele.","comprovacao":"Traga seu argumento original, o Steelman do lado contrário e se algo mudou na sua opinião."},{"titulo":"Contar suas “regras rígidas”","comoFazer":"Durante uma semana, preste atenção quando você disser ou pensar frases como “sempre”, “nunca”, “tem que ser assim”, “isso não funciona”, “já tentamos e não deu”. Anote cada uma. No final, escolha 2 dessas regras e pergunte: “Isso ainda é verdade? Existe alguma exceção?”.","comprovacao":"Traga a lista de frases rígidas e a revisão das 2 escolhidas."},{"titulo":"Testar uma forma de trabalhar diferente da sua","comoFazer":"Escolha uma atividade que você faz sempre do mesmo jeito. Procure uma forma diferente de fazê-la: pode ser o jeito que um colega faz, um método que viu em um vídeo ou uma sugestão que você já recebeu e descartou. Teste por pelo menos 3 vezes, com mente aberta, antes de julgar.","comprovacao":"Traga o método antigo, o novo, o resultado dos testes e se vai manter algo do novo jeito."},{"titulo":"Ler uma opinião contrária à sua","comoFazer":"Escolha um tema em que você tem opinião formada (pode ser do trabalho, do mercado ou da sociedade, evitando temas que te deixam muito tenso). Procure um artigo bem fundamentado de alguém que pensa o contrário e leia até o fim, procurando entender, e não rebater.","comprovacao":"Traga um resumo dos argumentos do artigo e pelo menos um ponto em que o autor tem razão."}]},
{"numero":29,"nome":"Foco","descricao":"Foco é a capacidade de direcionar energia e atenção para o que é mais importante, por tempo suficiente, sem se dispersar com distrações ou com várias coisas ao mesmo tempo.","tarefas":[{"titulo":"Ler a introdução e o capítulo 1 de “Trabalho Focado”, de Cal Newport","comoFazer":"O autor diferencia o “trabalho profundo”, feito com concentração total e que gera muito valor, do “trabalho superficial”, feito com distrações e que qualquer um faria. Ele mostra que a capacidade de se concentrar está ficando rara e, por isso, cada vez mais valiosa. Leia pensando na sua rotina.","comprovacao":"Traga uma estimativa de quanto do seu dia é trabalho profundo e quanto é superficial, e uma ideia para aumentar o profundo."},{"titulo":"Assistir ao filme “O Jogo da Imitação”","comoFazer":"O filme conta a história de Alan Turing, que liderou a equipe que decifrou o código nazista Enigma na Segunda Guerra. Observe como ele mantém o foco em um único objetivo, mesmo com pressões, críticas e distrações ao redor.","comprovacao":"Traga 3 momentos em que o foco foi decisivo e o que você pode aprender com isso."},{"titulo":"Fazer blocos de trabalho profundo","comoFazer":"Durante 5 dias, reserve na agenda um bloco de 60 a 90 minutos para uma tarefa importante que exige concentração. Nesse bloco: celular longe, notificações desligadas, e-mail e chat fechados, só uma aba aberta. Se surgir um pensamento ou lembrete, anote num papel para depois (veja a próxima tarefa) e volte.","comprovacao":"Traga o registro dos 5 blocos: tarefa, duração e quanto conseguiu avançar."},{"titulo":"Usar uma “lista de estacionamento”","comoFazer":"Quando estamos focados, surgem pensamentos do tipo “preciso responder aquele e-mail” ou “não posso esquecer de ligar para fulano”. Em vez de interromper o que está fazendo, “estacione” esses pensamentos numa folha ao lado. Só olhe a lista quando terminar o bloco de foco. Use durante uma semana.","comprovacao":"Traga a lista da semana e diga quantas interrupções você evitou."},{"titulo":"Fazer uma semana de notificações desligadas","comoFazer":"Durante 5 dias úteis, desligue todas as notificações que não são essenciais no celular e no computador: redes sociais, grupos, e-mail, aplicativos. Defina 3 ou 4 horários fixos por dia para checar mensagens. Se sua função exige atenção a algum canal, mantenha só ele ligado.","comprovacao":"Traga o que você desligou, os horários que definiu e como foi sua concentração em comparação às semanas anteriores."},{"titulo":"Usar o aplicativo Forest por 7 dias","comoFazer":"O Forest é um aplicativo em que você planta uma árvore virtual quando quer se concentrar. Se sair do aplicativo para mexer no celular antes do tempo acabar, a árvore morre. Parece bobo, mas funciona muito bem para quem pega o celular sem perceber. Use nos seus momentos de concentração durante 7 dias.","comprovacao":"Traga um print da sua “floresta” ao final dos 7 dias e quantas árvores morreram pelo caminho."}]},
{"numero":30,"nome":"Foco em Resultados","descricao":"Foco em resultados é direcionar o esforço para o que realmente gera impacto, medindo o sucesso pelo que foi entregue, e não pelo quanto se trabalhou ou pela quantidade de tarefas feitas.","tarefas":[{"titulo":"Ler os 3 primeiros capítulos de “Avalie o que Importa”, de John Doerr","comoFazer":"O autor apresenta os OKRs (Objetivos e Resultados-Chave), método usado por empresas como Google e Intel para manter todo mundo focado no que importa. Ele conta como os OKRs funcionam com histórias reais. Leia pensando em como definir metas claras e mensuráveis para o seu trabalho.","comprovacao":"Traga 3 aprendizados do livro e a diferença, com suas palavras, entre uma tarefa e um resultado."},{"titulo":"Assistir ao documentário “Senna”","comoFazer":"O documentário conta a trajetória de Ayrton Senna a partir de imagens reais da época. Repare na obsessão dele por resultado: a preparação, a análise de cada volta, a exigência com a equipe e consigo mesmo.","comprovacao":"Traga 3 atitudes de Senna ligadas ao foco em resultado e uma que você pode trazer para o seu trabalho."},{"titulo":"Criar um OKR pessoal para o próximo trimestre","comoFazer":"Defina 1 objetivo inspirador para o seu trabalho nos próximos 3 meses (ex.: “Ser referência em atendimento na minha área”) e 2 ou 3 resultados-chave que mostrem, com números, que o objetivo foi alcançado (ex.: “Reduzir o tempo médio de resposta de 48h para 24h”). Acompanhe uma vez por semana.","comprovacao":"Traga o OKR escrito e, ao final do trimestre, o quanto de cada resultado-chave foi alcançado."},{"titulo":"Transformar sua lista de tarefas em lista de resultados","comoFazer":"Pegue sua lista de tarefas da semana e reescreva cada item como resultado. Em vez de “fazer relatório de vendas”, escreva “entregar relatório que mostre à diretoria por que as vendas caíram em março”. Em vez de “ligar para clientes”, escreva “reativar 5 clientes inativos”. Veja como isso muda o jeito de trabalhar.","comprovacao":"Traga a lista antes e depois e diga se alguma tarefa perdeu o sentido quando pensou no resultado."},{"titulo":"Definir o “como vou saber que ficou bom” antes de começar","comoFazer":"Durante uma semana, antes de iniciar qualquer entrega importante, escreva em 2 ou 3 linhas: qual é o resultado esperado, para quem é, e como vou saber que ficou bom (critérios de sucesso). Ao terminar, confira se atendeu aos critérios.","comprovacao":"Traga pelo menos 3 entregas com os critérios definidos antes e a avaliação depois."},{"titulo":"Fazer um relatório semanal de resultados","comoFazer":"Durante 4 semanas, toda sexta-feira, escreva em até 5 linhas: quais resultados entreguei esta semana (não tarefas, resultados), qual foi o impacto de cada um e o que ficou pendente. Se fizer sentido, compartilhe com seu gestor.","comprovacao":"Traga os 4 relatórios semanais."}]},
{"numero":31,"nome":"Gestão da Comunicação","descricao":"Gestão da comunicação é organizar o fluxo de informações: garantir que as pessoas certas recebam a mensagem certa, no momento certo, pelo canal mais adequado, evitando ruídos, excesso de mensagens e informações perdidas.","tarefas":[{"titulo":"Assistir ao filme “Mera Coincidência”","comoFazer":"Na história, um assessor e um produtor de Hollywood criam uma guerra falsa na mídia para desviar a atenção de um escândalo presidencial. É uma sátira exagerada, mas mostra com clareza como a forma, o momento e o canal de uma comunicação mudam completamente a percepção das pessoas. Assista com olhar crítico, também sobre os limites éticos.","comprovacao":"Traga 3 estratégias de comunicação usadas no filme e reflita sobre quais são legítimas e quais são manipulação."},{"titulo":"Criar um Plano de Comunicação para um projeto ou rotina","comoFazer":"Escolha um projeto ou uma atividade que envolva várias pessoas. Monte uma tabela com: quem precisa ser informado, o que precisa saber, com que frequência, por qual canal (e-mail, reunião, mensagem, relatório) e quem é responsável por comunicar. Isso evita que alguém fique sem saber de algo importante.","comprovacao":"Traga o plano de comunicação preenchido."},{"titulo":"Criar uma Matriz de Canais","comoFazer":"Muita confusão acontece porque usamos o canal errado: assunto sério por mensagem rápida, informação simples em reunião de 1 hora. Defina, para o seu contexto, quando usar cada canal: conversa pessoal, ligação, reunião, e-mail, chat, documento compartilhado. Considere urgência, complexidade e necessidade de registro.","comprovacao":"Traga a matriz e 2 situações recentes em que o canal usado não foi o ideal."},{"titulo":"Padronizar o registro de reuniões","comoFazer":"Crie um modelo simples de ata com 4 partes: assuntos tratados, decisões tomadas, próximos passos (com responsável e prazo) e pendências. Use em todas as reuniões de que participar por 2 semanas, mesmo que só para você. Se for possível, envie aos participantes.","comprovacao":"Traga o modelo e pelo menos 3 atas preenchidas."},{"titulo":"Fazer uma auditoria das suas comunicações","comoFazer":"Durante uma semana, observe as comunicações que você envia e recebe. Anote: quantas mensagens precisaram de esclarecimento depois? Quantas foram enviadas para mais gente do que precisava? Quantas informações importantes chegaram tarde? Identifique os principais ruídos.","comprovacao":"Traga os números da auditoria e 3 melhorias que vai aplicar."},{"titulo":"Criar um resumo semanal para quem depende de você","comoFazer":"Pense em quem precisa acompanhar o seu trabalho: gestor, cliente, equipe. Durante 4 semanas, envie (ou prepare, se não houver abertura para enviar) um resumo curto no fim da semana com: o que foi feito, o que está em andamento, o que precisa de atenção e próximos passos. Isso reduz perguntas e cobranças.","comprovacao":"Traga os 4 resumos e, se enviou, a reação de quem recebeu."}]},
{"numero":32,"nome":"Gestão de Conflitos","descricao":"Gestão de conflitos é lidar com desacordos e tensões de forma construtiva, sem fugir nem partir para o ataque, buscando entender os interesses envolvidos e chegar a soluções que preservem o resultado e as relações.","tarefas":[{"titulo":"Ler os 2 primeiros capítulos de “Conversas Difíceis”, de Douglas Stone, Bruce Patton e Sheila Heen","comoFazer":"Os autores são do Projeto de Negociação de Harvard. Eles mostram que toda conversa difícil tem, na verdade, 3 conversas acontecendo ao mesmo tempo: a do “o que aconteceu”, a dos sentimentos e a da identidade (o que isso diz sobre mim). Leia pensando em um conflito que você está vivendo ou viveu.","comprovacao":"Traga esse conflito analisado nas 3 conversas."},{"titulo":"Assistir ao filme “12 Homens e uma Sentença”","comoFazer":"É um clássico de 1957. Doze jurados precisam decidir o destino de um jovem acusado de assassinato. Onze votam “culpado” de cara; um tem dúvidas. O filme inteiro se passa numa sala, e é uma aula sobre conflito, argumentação e como lidar com pessoas muito diferentes.","comprovacao":"Traga 3 formas diferentes de lidar com o conflito que aparecem no filme e qual delas funcionou melhor."},{"titulo":"Identificar seu estilo de conflito (Modelo Thomas-Kilmann)","comoFazer":"Esse modelo mostra 5 formas de lidar com conflitos: competir (eu ganho, você perde), acomodar (eu cedo), evitar (fujo do assunto), fazer concessões (cada um cede um pouco) e colaborar (buscamos juntos uma solução que atenda os dois). Pesquise sobre o modelo e pense nos últimos 5 conflitos que você viveu: qual estilo usou em cada um?","comprovacao":"Traga os 5 conflitos com o estilo usado, seu estilo predominante e quando ele funciona ou não."},{"titulo":"Separar posições de interesses","comoFazer":"Posição é o que a pessoa diz que quer (“quero a sala às 14h”). Interesse é o porquê (“preciso de silêncio para uma ligação importante”). Quando descobrimos os interesses, aparecem soluções que antes não víamos. Escolha um conflito recente e escreva a posição e o possível interesse de cada lado.","comprovacao":"Traga a análise e pelo menos uma solução que atenderia os interesses dos dois lados."},{"titulo":"Escrever uma “carta não enviada”","comoFazer":"Pense em um conflito que ainda te incomoda. Escreva uma carta para a pessoa dizendo tudo o que sente, sem filtro. Deixe descansar por um dia. Depois releia e reescreva como se fosse realmente enviar: com respeito, focada nos fatos e no que você precisa. Você não precisa enviar nenhuma das duas; o exercício é organizar o que sente e o que quer.","comprovacao":"Traga a segunda versão da carta (a primeira pode ficar só com você) e o que percebeu ao escrever."},{"titulo":"Preparar uma conversa difícil","comoFazer":"Escolha uma conversa que você está adiando. Prepare por escrito: qual é o fato (sem julgamento), qual o impacto para você ou para o trabalho, o que você acha que a outra pessoa pensa, o que você quer como resultado e como vai abrir a conversa. Se tiver segurança e for o momento, tenha a conversa; se ainda não, a preparação já é o exercício.","comprovacao":"Traga o roteiro da conversa e, se ela aconteceu, como foi."}]},
{"numero":33,"nome":"Gestão de Mudanças","descricao":"Gestão de mudanças é conduzir pessoas e processos durante uma transição, cuidando da comunicação, das resistências e do acompanhamento para que a mudança seja adotada de verdade e não apenas anunciada.","tarefas":[{"titulo":"Ler os 3 primeiros capítulos de “Liderando Mudança”, de John Kotter","comoFazer":"O autor é professor de Harvard e um dos maiores especialistas no tema. Ele apresenta os 8 passos para conduzir uma mudança com sucesso, começando por criar senso de urgência e terminando por fixar a mudança na cultura. Nos primeiros capítulos, ele explica os 8 erros mais comuns. Leia pensando nas mudanças que você já viu dar errado.","comprovacao":"Traga os erros que você já viu acontecer e em qual mudança."},{"titulo":"Assistir ao filme “Estrelas Além do Tempo”","comoFazer":"O filme conta a história real de matemáticas negras da NASA nos anos 1960. Preste atenção especial na personagem Dorothy Vaughan: quando percebe que os computadores da IBM vão substituir o trabalho da sua equipe, ela se antecipa, aprende a programar e prepara as colegas para a mudança.","comprovacao":"Traga o que Dorothy fez para gerenciar essa mudança e o que você pode aprender com ela."},{"titulo":"Aplicar os 8 passos de Kotter a uma mudança da sua área","comoFazer":"Os 8 passos são: 1) criar senso de urgência, 2) formar uma coalizão, 3) criar uma visão, 4) comunicar a visão, 5) remover obstáculos, 6) gerar vitórias rápidas, 7) consolidar ganhos e 8) fixar a mudança na cultura. Escolha uma mudança real (em andamento ou que você gostaria de propor) e escreva o que precisaria ser feito em cada passo.","comprovacao":"Traga o plano com os 8 passos preenchidos."},{"titulo":"Mapear a Curva da Mudança","comoFazer":"A Curva da Mudança (baseada nos estudos de Elisabeth Kübler-Ross) mostra que as pessoas passam por fases emocionais diante de uma mudança: choque, negação, frustração, depressão, experimentação, decisão e integração. Pesquise sobre a curva e pense em uma mudança que você viveu: em que fase você ficou mais tempo? E as pessoas ao seu redor?","comprovacao":"Traga um desenho da curva com os momentos que você viveu em cada fase."},{"titulo":"Escrever um comunicado de mudança","comoFazer":"Imagine que você precisa anunciar uma mudança na sua área (pode ser real ou hipotética). Escreva o comunicado respondendo: o que vai mudar, por que está mudando, quando, o que muda para cada pessoa, que apoio terão e onde tirar dúvidas. Evite linguagem vaga e seja honesto sobre as dificuldades.","comprovacao":"Traga o comunicado escrito."},{"titulo":"Preparar respostas para as resistências","comoFazer":"Pense em uma mudança e liste as 5 resistências ou objeções mais prováveis das pessoas (“vai dar mais trabalho”, “o jeito antigo funcionava”, “ninguém nos perguntou”). Para cada uma, escreva uma resposta honesta e uma ação que ajudaria a reduzir a resistência.","comprovacao":"Traga a lista de resistências com as respostas e ações."}]},
{"numero":34,"nome":"Gestão de Prioridades","descricao":"Gestão de prioridades é decidir, todos os dias, onde colocar tempo e energia, separando o que é realmente importante do que só parece urgente, e ajustando as escolhas quando o cenário muda.","tarefas":[{"titulo":"Ler os 3 primeiros capítulos de “Essencialismo”, de Greg McKeown","comoFazer":"O autor defende que fazer menos, mas melhor, é o caminho para resultados significativos. Ele mostra como dizemos “sim” para tudo e acabamos dispersos. Leia pensando em quantos compromissos você tem hoje e quantos realmente importam.","comprovacao":"Traga 3 ideias do livro e 2 coisas que você poderia deixar de fazer para focar no essencial."},{"titulo":"Aplicar a Matriz de Eisenhower por 5 dias","comoFazer":"No início de cada dia, liste suas atividades e classifique em 4 quadrantes: urgente e importante (fazer já), importante mas não urgente (agendar), urgente mas não importante (delegar ou resolver rápido) e nem urgente nem importante (eliminar). No fim do dia, veja em qual quadrante você passou mais tempo.","comprovacao":"Traga a matriz dos 5 dias e em qual quadrante passou mais tempo."},{"titulo":"Criar uma lista do “não fazer”","comoFazer":"Tão importante quanto saber o que fazer é saber o que não fazer. Liste atividades, reuniões, hábitos ou pedidos que tomam seu tempo e trazem pouco resultado. Escolha pelo menos 3 para cortar, reduzir ou fazer de forma diferente nas próximas 2 semanas.","comprovacao":"Traga a lista e o que aconteceu quando parou de fazer esses itens."},{"titulo":"Aplicar a Regra 1-3-5 por uma semana","comoFazer":"Todo dia, planeje: 1 tarefa grande, 3 tarefas médias e 5 pequenas. Nada além disso. Se surgir algo novo, algo da lista precisa sair. Essa regra obriga a escolher e evita listas impossíveis de cumprir.","comprovacao":"Traga as listas dos 5 dias e quantas tarefas cumpriu em cada."},{"titulo":"Alinhar suas prioridades com as expectativas da área","comoFazer":"Escreva as 5 prioridades que você acredita ter hoje no trabalho, em ordem. Depois compare com os objetivos da sua área e da empresa (metas, planejamento, o que o gestor mais cobra). Se tiver abertura, mostre a lista ao seu gestor e pergunte se ele concorda com a ordem; se não, faça a comparação com base nos documentos e cobranças que você recebe.","comprovacao":"Traga suas 5 prioridades, a comparação feita e os ajustes que decidiu fazer."},{"titulo":"Fazer uma revisão semanal de prioridades","comoFazer":"Durante 4 semanas, reserve 20 minutos na sexta-feira ou na segunda de manhã para responder: o que foi concluído? O que ficou pendente e por quê? O que mudou de prioridade? Quais são as 3 prioridades da próxima semana?","comprovacao":"Traga as 4 revisões."}]},
{"numero":35,"nome":"Gestão de Stakeholders","descricao":"Gestão de stakeholders é identificar as pessoas e grupos que influenciam ou são impactados pelo seu trabalho e cuidar dessas relações de forma intencional: entender o que cada um espera, manter todos informados e construir apoio.","tarefas":[{"titulo":"Assistir ao filme “Lincoln”, de Steven Spielberg","comoFazer":"O filme mostra os meses em que o presidente Abraham Lincoln precisou convencer deputados de diferentes partidos e interesses a aprovar a abolição da escravidão. É uma aula de gestão de stakeholders: mapear quem apoia, quem é contra, quem está indeciso e o que cada um precisa para mudar de posição.","comprovacao":"Traga 3 estratégias que Lincoln e sua equipe usaram com diferentes grupos."},{"titulo":"Mapear seus stakeholders","comoFazer":"Escolha um projeto ou uma área do seu trabalho. Liste todas as pessoas ou grupos que influenciam ou são impactados por ele: gestor, colegas, outras áreas, clientes, fornecedores, diretoria. Para cada um, anote: o que espera de você, o que o preocupa e como está a relação hoje.","comprovacao":"Traga o mapa com pelo menos 6 stakeholders."},{"titulo":"Aplicar a Matriz Poder x Interesse","comoFazer":"Pegue o mapa anterior e posicione cada stakeholder em uma matriz de 2 eixos: poder (quanto ele pode influenciar) e interesse (quanto ele se importa com o assunto). Isso gera 4 grupos: gerenciar de perto (alto poder e alto interesse), manter satisfeito (alto poder, baixo interesse), manter informado (baixo poder, alto interesse) e monitorar (baixo e baixo).","comprovacao":"Traga a matriz preenchida e a estratégia para cada grupo."},{"titulo":"Criar um plano de engajamento","comoFazer":"Para os 3 stakeholders mais importantes da matriz, defina: o que quero dele (apoio, informação, aprovação), o que ele quer de mim, com que frequência devo me comunicar, por qual canal e que tipo de informação ele valoriza.","comprovacao":"Traga o plano de engajamento para os 3 stakeholders."},{"titulo":"Fazer atualizações proativas","comoFazer":"Durante 3 semanas, escolha 1 ou 2 stakeholders importantes e mande atualizações antes que eles perguntem: um e-mail curto de status, uma mensagem avisando que algo deu certo ou que um prazo vai mudar. Atualizar antes de ser cobrado gera confiança.","comprovacao":"Traga as atualizações enviadas e a reação dos stakeholders."},{"titulo":"Analisar um projeto que sofreu por falta de alinhamento","comoFazer":"Pense em um projeto (seu, da empresa ou que você acompanhou) que teve problemas porque alguém importante não foi envolvido, não foi informado ou teve expectativas diferentes. Responda: quem ficou de fora? Em que momento? Qual foi o impacto? O que deveria ter sido feito?","comprovacao":"Traga a análise e 3 lições para seus próximos projetos."}]},
{"numero":36,"nome":"Gestão do Tempo","descricao":"Gestão do tempo é saber para onde o seu tempo está indo e organizá-lo de forma intencional, reservando espaço para o que é importante e reduzindo desperdícios, atrasos e correria.","tarefas":[{"titulo":"Ler os 3 primeiros capítulos de “A Tríade do Tempo”, de Christian Barbosa","comoFazer":"O autor, brasileiro e especialista em produtividade, divide o tempo em três esferas: importante, urgente e circunstancial. Ele mostra que a maioria das pessoas vive apagando incêndios e que é possível mudar isso. No site do autor há um teste gratuito para descobrir como está sua tríade. Leia e, se possível, faça o teste.","comprovacao":"Traga o resultado do teste (ou sua estimativa) de quanto do seu tempo está em cada esfera e o que pretende mudar."},{"titulo":"Fazer um registro do tempo por 3 dias","comoFazer":"O pensador Peter Drucker dizia que a gestão do tempo começa por saber para onde ele vai. Durante 3 dias, anote a cada 30 minutos o que você fez. Seja honesto, inclusive com as pausas no celular. No final, agrupe as atividades e some o tempo de cada grupo.","comprovacao":"Traga o registro dos 3 dias e as 3 maiores surpresas sobre onde seu tempo está indo."},{"titulo":"Aplicar a Técnica Pomodoro por 5 dias","comoFazer":"Criada por Francesco Cirillo, a técnica funciona assim: escolha uma tarefa, trabalhe 25 minutos sem interrupção, faça uma pausa de 5 minutos. A cada 4 “pomodoros”, faça uma pausa maior, de 15 a 30 minutos. Use um cronômetro ou um aplicativo de Pomodoro. O ritmo ajuda a começar e a manter o foco.","comprovacao":"Traga quantos pomodoros fez por dia e em que tipo de tarefa a técnica funcionou melhor."},{"titulo":"Usar blocos de tempo na agenda","comoFazer":"Em vez de trabalhar com uma lista solta de tarefas, coloque as tarefas importantes direto na agenda, com horário de início e fim, como se fossem reuniões com você mesmo. Deixe espaço livre entre os blocos para imprevistos. Faça isso durante uma semana.","comprovacao":"Traga um print da agenda da semana e o quanto do planejado foi cumprido."},{"titulo":"Assistir ao filme “Click”","comoFazer":"Na comédia com Adam Sandler, um homem ganha um controle remoto que permite “pular” partes da vida. No começo parece ótimo, mas ele percebe que está perdendo o que realmente importa. Por trás do humor, é uma reflexão sobre como usamos o tempo.","comprovacao":"Traga uma reflexão sobre quais momentos do seu dia você costuma “pular” e o que gostaria de fazer de diferente."},{"titulo":"Agrupar tarefas parecidas","comoFazer":"Muito tempo se perde trocando de uma coisa para outra. Durante uma semana, agrupe tarefas semelhantes em blocos: responda e-mails só em 3 horários do dia, faça todas as ligações juntas, resolva as pendências administrativas em um único momento.","comprovacao":"Traga como organizou os agrupamentos e se sentiu diferença no rendimento."}]},
{"numero":37,"nome":"Influência","descricao":"Influência é a capacidade de mobilizar pessoas, ideias e decisões sem depender de cargo ou autoridade formal, conquistando confiança e engajamento por meio de argumentos, exemplo e relacionamento.","tarefas":[{"titulo":"Ler a Parte 1 e a Parte 3 de “Como Fazer Amigos e Influenciar Pessoas”, de Dale Carnegie","comoFazer":"É um dos livros mais vendidos da história sobre relações humanas. A Parte 1 traz as técnicas fundamentais para lidar com pessoas, e a Parte 3 fala sobre como conquistar as pessoas para o seu modo de pensar. Os princípios são simples, mas poderosos. Leia marcando os que você menos pratica.","comprovacao":"Traga os 3 princípios que você menos pratica e como vai aplicar cada um."},{"titulo":"Assistir ao filme “Selma: Uma Luta pela Igualdade”","comoFazer":"O filme retrata a campanha de Martin Luther King para garantir o direito de voto aos negros nos Estados Unidos. Observe como ele mobiliza pessoas, negocia com o presidente, escolhe o momento certo para agir e usa a opinião pública a favor da causa, sem ter nenhum cargo oficial.","comprovacao":"Traga 3 estratégias de influência que aparecem no filme."},{"titulo":"Assistir ao TED “Como grandes líderes inspiram ação”, de Simon Sinek","comoFazer":"Nessa palestra, uma das mais vistas do TED, o autor apresenta o “Círculo Dourado”: as pessoas não compram o que você faz, compram o porquê você faz. Ele mostra que quem influencia começa pelo “por quê”, depois o “como” e por último o “o quê”. Assista no site do TED ou no YouTube.","comprovacao":"Pegue uma ideia ou proposta sua e reescreva o jeito de apresentá-la começando pelo “por quê”."},{"titulo":"Descobrir o que importa para o outro","comoFazer":"Antes de tentar influenciar alguém, pense: o que essa pessoa ganha com isso? Escolha uma proposta que você quer levar a alguém (gestor, colega, cliente). Escreva: quais são os objetivos dessa pessoa, o que a preocupa, como sua proposta ajuda nisso. Depois monte seu argumento a partir do ponto de vista dela.","comprovacao":"Traga a análise e o argumento que construiu."},{"titulo":"Propor uma pequena melhoria","comoFazer":"Escolha uma melhoria simples no seu trabalho que dependa de aprovação ou adesão de outros. Prepare uma proposta curta: o problema, a solução, o benefício para quem vai aprovar e o primeiro passo. Apresente a quem decide. Se ainda não houver espaço, prepare a proposta mesmo assim e guarde para o momento certo.","comprovacao":"Traga a proposta e, se apresentou, o resultado."},{"titulo":"Estudar alguém influente","comoFazer":"Escolha uma pessoa que você considera influente (da empresa ou uma figura pública) e observe durante algumas semanas, ou por meio de entrevistas e palestras: como ela fala, como se relaciona, como convence, como reage quando discordam dela.","comprovacao":"Traga 5 comportamentos de influência que identificou e 1 que vai começar a praticar."}]},
{"numero":38,"nome":"Iniciativa","descricao":"Iniciativa é agir sem precisar ser mandado: perceber uma oportunidade ou um problema e dar o primeiro passo, em vez de esperar que alguém resolva.","tarefas":[{"titulo":"Assistir ao filme “O Menino que Descobriu o Vento”","comoFazer":"O filme, disponível na Netflix, conta a história real de um menino do Malaui que, durante uma seca que ameaçava sua vila, aprende sozinho numa biblioteca a construir um moinho de vento para gerar energia e bombear água. Ele não espera ninguém resolver: ele age.","comprovacao":"Traga 3 atitudes de iniciativa do personagem e um problema do seu trabalho que você poderia resolver com essa postura."},{"titulo":"Ler o livro “O Poder dos 5 Segundos”, de Mel Robbins","comoFazer":"A autora criou uma técnica simples: quando tiver o impulso de fazer algo que sabe que deveria fazer, conte 5-4-3-2-1 e aja antes que o cérebro invente desculpas. Leia os primeiros capítulos e comece a testar a técnica.","comprovacao":"Traga 3 situações em que usou a contagem regressiva para tomar uma iniciativa."},{"titulo":"Fazer a lista “Isso me incomoda e ninguém resolve”","comoFazer":"Durante uma semana, anote tudo no trabalho que te incomoda e que ninguém resolve: um arquivo desorganizado, um processo confuso, uma informação difícil de achar, um erro que sempre se repete. No fim da semana, escolha um item que esteja ao seu alcance e resolva.","comprovacao":"Traga a lista completa e o que fez para resolver o item escolhido."},{"titulo":"Aplicar a regra do “primeiro passo em 24 horas”","comoFazer":"Durante 2 semanas, sempre que tiver uma ideia, perceber uma oportunidade ou se comprometer com algo, dê o primeiro passo em até 24 horas, por menor que seja: mandar uma mensagem, pesquisar algo, rascunhar uma proposta. Ideias que não ganham um primeiro passo rápido tendem a morrer.","comprovacao":"Traga as ideias ou oportunidades que surgiram e o primeiro passo dado em cada uma."},{"titulo":"Oferecer-se para algo novo","comoFazer":"Fique atento a oportunidades de se oferecer: um projeto que precisa de ajuda, uma tarefa que ninguém quer assumir, uma apresentação, a organização de algo. Ofereça-se para pelo menos uma. Se não aparecer nada, crie a oportunidade: proponha algo que você mesmo poderia conduzir.","comprovacao":"Traga para o que se ofereceu (ou o que propôs) e o resultado."},{"titulo":"Criar algo útil sem que ninguém peça","comoFazer":"Identifique algo que facilitaria a sua vida ou a de outras pessoas: um modelo de documento, um passo a passo de um processo, uma planilha de controle, uma lista de contatos úteis. Crie e compartilhe (ou comece a usar).","comprovacao":"Traga o material criado e como ele está sendo usado."}]},
{"numero":39,"nome":"Inovação","descricao":"Inovação é transformar ideias em algo novo que gere valor na prática: um produto, um processo, um serviço ou uma forma diferente de trabalhar, testando, aprendendo e melhorando.","tarefas":[{"titulo":"Ler os 3 primeiros capítulos de “A Startup Enxuta”, de Eric Ries","comoFazer":"O autor mostra que inovar não é ter uma grande ideia e executá-la de uma vez, mas testar pequenas versões, aprender com os resultados e ajustar rapidamente. Ele chama isso de ciclo “construir, medir, aprender”. Os conceitos servem para qualquer empresa, não só startups.","comprovacao":"Traga o ciclo “construir, medir, aprender” aplicado a uma ideia do seu trabalho."},{"titulo":"Assistir ao filme “Flamin’ Hot: O Sabor que Mudou a História”","comoFazer":"O filme conta a história de Richard Montañez, um funcionário da limpeza de uma fábrica que teve a ideia de um salgadinho apimentado e lutou para que a empresa a testasse. Observe como a inovação veio de quem estava na ponta e conhecia o cliente de perto.","comprovacao":"Traga 3 lições sobre inovação do filme e uma ideia que você, pela posição que ocupa, tem condições de propor."},{"titulo":"Testar uma ideia em pequena escala","comoFazer":"Escolha uma ideia simples de melhoria. Em vez de planejar tudo, crie a menor versão possível para testar (o que Eric Ries chama de MVP, “produto mínimo viável”): um rascunho, um protótipo em papel, um teste com uma única tarefa. Defina antes o que quer descobrir e teste.","comprovacao":"Traga a ideia, o MVP criado, o que testou e o que aprendeu."},{"titulo":"Usar perguntas “Como poderíamos…?”","comoFazer":"Essa técnica transforma problemas em oportunidades. Pegue 3 problemas do seu trabalho e reescreva cada um como uma pergunta começando com “Como poderíamos…?”. Exemplo: “Os clientes reclamam da demora” vira “Como poderíamos fazer o cliente receber a resposta no mesmo dia?”. Para cada pergunta, gere pelo menos 5 ideias.","comprovacao":"Traga as 3 perguntas e as ideias geradas para cada uma."},{"titulo":"Buscar inspiração em outro setor","comoFazer":"Muitas inovações vêm de copiar soluções de outras áreas. Escolha um problema do seu trabalho e pesquise como outro setor resolve algo parecido. Exemplo: como os aplicativos de delivery avisam o cliente sobre o status do pedido? Isso poderia inspirar o atendimento da sua área?","comprovacao":"Traga o problema, a solução encontrada em outro setor e como ela poderia ser adaptada."},{"titulo":"Criar um Banco de Ideias com filtro Impacto x Esforço","comoFazer":"Crie uma planilha ou caderno para registrar ideias de melhoria durante 2 semanas. Depois avalie cada uma com notas de 1 a 5 para impacto e esforço. As ideias de alto impacto e baixo esforço são as primeiras a testar.","comprovacao":"Traga o banco de ideias avaliado e a ideia escolhida para testar primeiro."}]},
{"numero":40,"nome":"Inteligência Emocional","descricao":"Inteligência emocional é reconhecer e gerenciar as próprias emoções, perceber as emoções dos outros e usar essa percepção para se relacionar e agir melhor.","tarefas":[{"titulo":"Ler os 3 primeiros capítulos de “Inteligência Emocional”, de Daniel Goleman","comoFazer":"É o livro que popularizou o conceito no mundo todo. O autor explica como as emoções funcionam no cérebro e por que pessoas com alta inteligência emocional muitas vezes se saem melhor do que pessoas com QI alto. Leia anotando os conceitos que fizeram sentido para você.","comprovacao":"Traga 3 conceitos do livro e um exemplo de como cada um aparece no seu trabalho."},{"titulo":"Assistir aos 3 primeiros episódios da série “Ted Lasso”, na Apple TV+","comoFazer":"A série conta a história de um treinador de futebol americano contratado para treinar um time de futebol inglês, sem entender nada do esporte. O que ele tem de sobra é inteligência emocional: sabe ler as pessoas, lidar com conflitos e conquistar até quem torce contra ele.","comprovacao":"Traga 3 atitudes de inteligência emocional do personagem e uma que você gostaria de desenvolver."},{"titulo":"Fazer uma autoavaliação nos 5 pilares de Goleman","comoFazer":"Goleman divide a inteligência emocional em 5 pilares: autoconsciência, autorregulação, automotivação, empatia e habilidades sociais. Dê a você mesmo uma nota de 1 a 10 em cada um, com um exemplo que justifique a nota. Seja honesto.","comprovacao":"Traga as notas com os exemplos e escolha o pilar que vai desenvolver primeiro."},{"titulo":"Aplicar a técnica RAIN","comoFazer":"RAIN é uma técnica de atenção plena para lidar com emoções difíceis: Reconhecer o que está sentindo, Aceitar que a emoção está ali (sem brigar com ela), Investigar com curiosidade (onde sinto isso no corpo? o que provocou?) e Nutrir, ou seja, se tratar com gentileza. Use em pelo menos 3 momentos de emoção forte durante 2 semanas.","comprovacao":"Traga as 3 situações e como a técnica te ajudou."},{"titulo":"Fazer o diário ABC","comoFazer":"Criado pelo psicólogo Albert Ellis, o modelo ABC mostra que não é o acontecimento que gera a emoção, mas o que pensamos sobre ele. Registre 5 situações: A (acontecimento), B (o que eu pensei, minha crença) e C (consequência: o que senti e como agi). Depois pergunte: “Existe outra forma de interpretar isso?”.","comprovacao":"Traga os 5 registros com a interpretação alternativa."},{"titulo":"Treinar a leitura de emoções sem som","comoFazer":"Escolha uma cena de filme ou série que você não conhece, com personagens conversando. Assista 5 minutos sem som e anote as emoções que percebe em cada personagem, só pelas expressões e gestos. Depois assista de novo com som e confira.","comprovacao":"Traga suas anotações e quantas emoções você identificou corretamente."}]},
{"numero":41,"nome":"Inteligência Emocional Tática","descricao":"Inteligência emocional tática é usar a percepção das emoções, suas e dos outros, de forma estratégica no momento em que as coisas acontecem: numa negociação, numa reunião tensa, numa conversa decisiva.","tarefas":[{"titulo":"Ler os capítulos 1 a 3 de “Negocie Como se Sua Vida Dependesse Disso”, de Chris Voss","comoFazer":"O autor foi o principal negociador de sequestros do FBI. Ele apresenta a “empatia tática”: entender e nomear as emoções do outro para influenciar o rumo da conversa. Técnicas como o espelhamento e a rotulagem são simples e muito eficazes. Leia anotando as técnicas.","comprovacao":"Traga as técnicas que aprendeu e em que situação do seu trabalho cada uma poderia ser usada."},{"titulo":"Assistir ao filme “Invictus”","comoFazer":"O filme mostra como Nelson Mandela, recém-eleito presidente da África do Sul, usa a seleção de rúgbi para unir um país dividido. Ele lê as emoções de negros e brancos e age estrategicamente sobre elas, inclusive contrariando seus próprios apoiadores. Observe cada decisão dele.","comprovacao":"Traga 3 momentos em que Mandela usou as emoções de forma estratégica."},{"titulo":"Praticar a rotulagem emocional","comoFazer":"Rotular é nomear em voz alta a emoção que você percebe no outro, começando com “Parece que…” ou “Tenho a impressão de que…”. Exemplo: “Parece que você está preocupado com o prazo.” Isso faz a pessoa se sentir compreendida e diminui a tensão. Use pelo menos 3 vezes em conversas reais (trabalho, casa, atendimento).","comprovacao":"Traga as 3 situações, o rótulo que usou e a reação da pessoa."},{"titulo":"Preparar seu estado emocional antes de um momento importante","comoFazer":"Antes de uma reunião difícil, apresentação ou conversa delicada, reserve 5 minutos e responda por escrito: “Como estou me sentindo agora?”, “Como quero estar durante a conversa?”, “O que pode me tirar do eixo?” e “O que vou fazer se isso acontecer?”. Depois do momento, avalie se o plano funcionou.","comprovacao":"Traga a preparação e a avaliação de pelo menos 2 momentos."},{"titulo":"Fazer a “leitura da sala”","comoFazer":"Nas próximas 3 reuniões ou encontros em grupo, dedique os primeiros minutos a observar o clima: as pessoas estão tensas, cansadas, animadas, dispersas? Quem está mais fechado? Com base nisso, ajuste algo na sua forma de participar (tom de voz, momento de falar, jeito de apresentar uma ideia).","comprovacao":"Traga a leitura que fez em cada situação e o ajuste que aplicou."},{"titulo":"Revisar um momento tenso depois que ele passou","comoFazer":"Escolha uma situação tensa recente e responda: qual emoção dominou em mim? E no outro? Que emoção eu poderia ter usado a meu favor (calma, curiosidade, firmeza, humor)? O que eu diria diferente? Faça isso com 2 situações.","comprovacao":"Traga a análise das 2 situações."}]},
{"numero":42,"nome":"Leitura de Cenário","descricao":"Leitura de cenário é entender o contexto em que você e a empresa estão inseridos: o mercado, a economia, os concorrentes, os clientes e o momento interno, para agir de forma mais acertada.","tarefas":[{"titulo":"Ler a introdução e os 2 primeiros capítulos de “O Sinal e o Ruído”, de Nate Silver","comoFazer":"O autor ficou famoso por prever resultados de eleições com precisão. No livro, ele mostra como separar a informação que importa (o sinal) do excesso de informação irrelevante (o ruído). Leia pensando na quantidade de informação que chega até você todos os dias.","comprovacao":"Traga 3 “sinais” e 3 “ruídos” do seu contexto de trabalho atual."},{"titulo":"Assistir ao filme “Margin Call: O Dia Antes do Fim”","comoFazer":"O filme se passa em 24 horas dentro de um banco de investimentos, pouco antes da crise de 2008. Um analista percebe um risco enorme nos números e os executivos precisam ler o cenário e decidir rápido. Observe como cada um interpreta a situação de um jeito diferente.","comprovacao":"Traga como os diferentes personagens leram o mesmo cenário e quem, na sua opinião, leu melhor."},{"titulo":"Fazer uma análise PESTEL da sua empresa ou setor","comoFazer":"PESTEL é uma ferramenta para analisar o ambiente externo em 6 dimensões: Política, Economia, Social, Tecnologia, Ecologia (meio ambiente) e Legal. Para cada uma, liste de 2 a 3 fatores que influenciam hoje a sua empresa ou o seu setor.","comprovacao":"Traga a análise PESTEL preenchida e o fator que considera mais importante."},{"titulo":"Criar uma rotina de 15 minutos de informação sobre o seu setor","comoFazer":"Durante 4 semanas, reserve 15 minutos por dia para acompanhar notícias do seu setor e da economia: jornais como Valor Econômico, revistas de negócios, newsletters do segmento, perfis de especialistas no LinkedIn. Anote uma notícia relevante por dia.","comprovacao":"Traga as anotações e as 3 notícias que mais podem impactar o seu trabalho."},{"titulo":"Fazer uma análise SWOT da sua área","comoFazer":"A SWOT analisa Forças e Fraquezas (fatores internos) e Oportunidades e Ameaças (fatores externos). Faça a análise da sua área ou equipe, com pelo menos 3 itens em cada quadrante. Depois cruze: como usar as forças para aproveitar as oportunidades?","comprovacao":"Traga a SWOT preenchida e 2 ações que surgem do cruzamento."},{"titulo":"Acompanhar os resultados da sua empresa","comoFazer":"Se a empresa divulga resultados (trimestrais, anuais, comunicados internos, reuniões de resultado), leia o último e responda: a empresa está crescendo ou encolhendo? Qual é o maior desafio do momento? Como minha área contribui? Se não houver resultados públicos, use comunicados internos, apresentações e notícias sobre a empresa.","comprovacao":"Traga um resumo de meia página sobre o momento da empresa."}]},
{"numero":43,"nome":"Liderança","descricao":"Liderança é inspirar, orientar e desenvolver pessoas em direção a um objetivo comum, construindo confiança e assumindo a responsabilidade pelo resultado do grupo, com ou sem cargo formal.","tarefas":[{"titulo":"Ler o livro “O Monge e o Executivo”, de James C. Hunter","comoFazer":"É um dos livros mais lidos sobre liderança no Brasil. Em formato de história, um executivo em crise passa uma semana num mosteiro e aprende o conceito de liderança servidora: liderar é servir, e a autoridade vem do respeito conquistado, não do cargo. A leitura é leve e rápida.","comprovacao":"Traga 3 conceitos do livro e como cada um se aplicaria no seu dia a dia."},{"titulo":"Assistir ao filme “Duelo de Titãs”","comoFazer":"O filme conta a história real de um treinador que assume um time de futebol americano recém-integrado, com jogadores brancos e negros, em plena época de tensão racial nos Estados Unidos. Observe como ele transforma pessoas divididas em uma equipe.","comprovacao":"Traga 3 atitudes de liderança do treinador e qual delas você gostaria de desenvolver."},{"titulo":"Assistir ao TED “Por que bons líderes fazem você se sentir seguro”, de Simon Sinek","comoFazer":"Nessa palestra, no site do TED e no YouTube, o autor mostra que os grandes líderes criam um ambiente em que as pessoas se sentem seguras, e é essa segurança que faz todos darem o seu melhor.","comprovacao":"Traga 3 ideias da palestra e o que você pode fazer para que as pessoas ao seu redor se sintam mais seguras."},{"titulo":"Aplicar a Liderança Situacional","comoFazer":"O modelo de Hersey e Blanchard diz que não existe um único estilo de liderança certo: depende da maturidade da pessoa para aquela tarefa. Os 4 estilos são: direcionar (dizer o que e como), orientar (explicar e envolver), apoiar (incentivar) e delegar. Pense em 3 pessoas com quem você trabalha e em que estilo cada uma precisaria em uma tarefa específica.","comprovacao":"Traga a análise das 3 pessoas com o estilo mais adequado para cada uma."},{"titulo":"Escrever seu “Manifesto de Liderança”","comoFazer":"Em uma página, escreva que tipo de líder você é ou quer ser: seus valores, como quer tratar as pessoas, o que nunca faria, como quer ser lembrado. Pode pensar em líderes que admirou (e nos que não admirou) para inspirar.","comprovacao":"Traga o manifesto escrito."},{"titulo":"Liderar algo, mesmo pequeno","comoFazer":"Assuma a liderança de algo nas próximas semanas: conduzir uma reunião, organizar uma iniciativa, coordenar uma entrega em grupo, receber um novo colega. Se não houver espaço no trabalho, pode ser em outro contexto (um grupo de estudo, um evento, um projeto voluntário). Depois avalie como foi.","comprovacao":"Traga o que liderou, o que funcionou, o que foi difícil e o que faria diferente."}]},
{"numero":44,"nome":"Mediação de Conflitos","descricao":"Mediação de conflitos é ajudar outras pessoas a resolver um desacordo entre elas, de forma neutra, criando espaço para que cada lado seja ouvido e para que encontrem juntas uma solução.","tarefas":[{"titulo":"Assistir ao TED “O caminho do ‘não’ para o ‘sim’”, de William Ury","comoFazer":"O palestrante é um dos maiores especialistas em negociação do mundo e já mediou conflitos entre países. Ele conta uma história sobre camelos e herança para mostrar como uma terceira pessoa pode ajudar os lados a enxergar uma saída. Assista no site do TED ou no YouTube.","comprovacao":"Traga o conceito de “terceiro lado” apresentado na palestra e um exemplo de como ele se aplicaria no seu trabalho."},{"titulo":"Assistir ao filme “Deus da Carnificina”","comoFazer":"Dois casais se encontram para resolver civilizadamente uma briga entre seus filhos. O que começa educado vai descambando para acusações, alianças e explosões. É um ótimo exemplo do que acontece quando não há mediação. Observe os momentos em que a conversa poderia ter sido salva.","comprovacao":"Traga 3 momentos em que uma boa mediação poderia ter mudado o rumo e o que você faria como mediador."},{"titulo":"Treinar a reformulação neutra","comoFazer":"Um bom mediador pega falas carregadas de emoção e acusação e as reformula de forma neutra, focando na necessidade. Exemplo: “Ele nunca me passa as informações!” vira “Você precisa receber as informações a tempo para fazer seu trabalho.” Escreva 5 falas acusatórias comuns no trabalho e reformule cada uma.","comprovacao":"Traga as 5 falas originais e as reformulações."},{"titulo":"Montar o Mapa do Conflito","comoFazer":"Escolha um conflito entre outras pessoas que você presenciou (no trabalho, na família, até em uma série). Monte um mapa: quem são as partes, o que cada uma diz querer (posição), o que realmente precisa (interesse), quais são seus medos e o que as duas têm em comum.","comprovacao":"Traga o mapa preenchido e uma possível solução que atenderia as duas partes."},{"titulo":"Criar um roteiro de mediação","comoFazer":"Escreva um roteiro simples que você poderia usar para mediar uma conversa: abertura (explicar seu papel e as regras, como não interromper), cada lado conta sua visão, você resume o que ouviu, identificam juntos os interesses em comum, geram opções e combinam os próximos passos.","comprovacao":"Traga o roteiro e simule por escrito como o usaria no conflito do exercício anterior."},{"titulo":"Refletir sobre um conflito que você presenciou","comoFazer":"Pense em um conflito entre outras pessoas que você viu acontecer. Responda: alguém tentou mediar? Como? O que funcionou e o que piorou a situação? Se você tivesse sido o mediador, o que teria feito?","comprovacao":"Traga a reflexão escrita."}]},
{"numero":45,"nome":"Memória","descricao":"Memória, no contexto profissional, é a capacidade de reter e recuperar informações importantes (nomes, combinados, procedimentos, dados), usando técnicas e sistemas que evitam esquecimentos.","tarefas":[{"titulo":"Ler os 3 primeiros capítulos de “A Arte e a Ciência de Memorizar Tudo”, de Joshua Foer","comoFazer":"O autor era um jornalista com memória comum que, em um ano de treino, venceu o campeonato de memória dos Estados Unidos. No livro, ele conta como fez e mostra que memória é uma habilidade treinável. Leia anotando as técnicas apresentadas.","comprovacao":"Traga as técnicas de memória que conheceu e qual pretende testar primeiro."},{"titulo":"Assistir ao TED “Façanhas de memória que qualquer um pode fazer”, de Joshua Foer","comoFazer":"Nessa palestra, no site do TED e no YouTube, o mesmo autor resume sua experiência e explica a técnica do Palácio da Memória de forma simples e divertida.","comprovacao":"Traga uma explicação, com suas palavras, de como funciona o Palácio da Memória."},{"titulo":"Usar a técnica do Palácio da Memória","comoFazer":"Escolha um lugar que você conhece muito bem, como a sua casa. Defina um percurso com 10 pontos (porta, sofá, mesa…). Para memorizar uma lista de 10 itens (tarefas, tópicos de uma apresentação), “coloque” cada item em um ponto do percurso, criando imagens exageradas e engraçadas. Depois percorra mentalmente o caminho para lembrar.","comprovacao":"Traga a lista que memorizou, o percurso usado e quantos itens lembrou depois de 24 horas."},{"titulo":"Usar a repetição espaçada com o aplicativo Anki","comoFazer":"O Anki é um aplicativo gratuito de flashcards que mostra cada cartão no momento em que você está prestes a esquecê-lo. Crie pelo menos 20 cartões com informações que precisa memorizar no trabalho (códigos, procedimentos, termos técnicos, nomes de clientes) e estude 10 minutos por dia durante 2 semanas.","comprovacao":"Traga um print das estatísticas do aplicativo ao final das 2 semanas."},{"titulo":"Revisar suas anotações em até 24 horas","comoFazer":"Segundo a Curva do Esquecimento, de Hermann Ebbinghaus, esquecemos boa parte do que aprendemos em poucas horas se não revisarmos. Durante 2 semanas, depois de cada reunião, treinamento ou leitura importante, reserve 5 minutos em até 24 horas para reler e resumir suas anotações em 3 pontos.","comprovacao":"Traga os resumos de pelo menos 5 reuniões ou treinamentos."},{"titulo":"Montar seu “segundo cérebro”","comoFazer":"Em vez de confiar só na memória, crie um sistema externo para guardar o que importa: um caderno organizado, um aplicativo de notas (Notion, OneNote, Google Keep) com pastas por tema, uma lista de combinados e prazos. Organize e use durante um mês.","comprovacao":"Traga um print ou foto do sistema criado e diga quantas vezes ele te salvou de um esquecimento."}]},
{"numero":46,"nome":"Mentalidade de Crescimento","descricao":"Mentalidade de crescimento é acreditar que habilidades e inteligência podem ser desenvolvidas com esforço, estratégia e aprendizado, encarando erros e desafios como parte do caminho, e não como prova de incapacidade.","tarefas":[{"titulo":"Ler os 2 primeiros capítulos de “Mindset: A Nova Psicologia do Sucesso”, de Carol Dweck","comoFazer":"A autora, professora de Stanford, pesquisou por décadas por que algumas pessoas crescem diante das dificuldades e outras desistem. Ela descobriu dois tipos de mentalidade: a fixa, que acredita que talento é algo que se tem ou não se tem, e a de crescimento, que acredita que tudo pode ser desenvolvido. Leia identificando exemplos seus de cada uma.","comprovacao":"Traga 2 situações em que você agiu com mentalidade fixa e como agiria com mentalidade de crescimento."},{"titulo":"Assistir ao TED “O poder de acreditar que você pode melhorar”, de Carol Dweck","comoFazer":"Nessa palestra curta, no site do TED e no YouTube, a autora apresenta o conceito do “ainda”: em vez de “não sei fazer isso”, “ainda não sei fazer isso”. Parece pouco, mas muda a forma como encaramos desafios.","comprovacao":"Traga 3 frases que você costuma dizer sobre si mesmo e reescreva cada uma usando o “ainda”."},{"titulo":"Assistir ao filme “Billy Elliot”","comoFazer":"O filme conta a história de um menino de uma cidade mineira na Inglaterra que descobre o balé e decide aprender, mesmo sem nenhum apoio inicial, com todo mundo dizendo que aquilo não era para ele. Observe como ele evolui com esforço, erros e persistência.","comprovacao":"Traga 3 momentos que mostram mentalidade de crescimento e uma área em que você se sente como o Billy no começo do filme."},{"titulo":"Manter um Diário de Erros e Aprendizados por 2 semanas","comoFazer":"Sempre que errar ou algo não sair como esperado, anote: o que aconteceu, o que aprendi com isso e o que farei diferente. O objetivo é treinar o cérebro a ver o erro como informação, e não como fracasso.","comprovacao":"Traga o diário e o aprendizado mais valioso das 2 semanas."},{"titulo":"Praticar algo em que você é ruim","comoFazer":"Escolha uma habilidade em que você se considera fraco (fazer planilhas, falar em público, desenhar, um idioma). Pratique 15 minutos por dia durante 2 semanas e registre a evolução no primeiro e no último dia (pode ser uma foto, uma gravação, um teste).","comprovacao":"Traga o registro do primeiro e do último dia e o que percebeu sobre sua capacidade de melhorar."},{"titulo":"Transformar uma crítica em plano de desenvolvimento","comoFazer":"Lembre de uma crítica ou feedback negativo que você recebeu e que te incomodou. Em vez de se defender, responda: o que há de verdade nisso? O que eu posso aprender? Que ação concreta posso tomar para melhorar esse ponto?","comprovacao":"Traga a crítica, a reflexão e o plano de ação."}]},
{"numero":47,"nome":"Mentalidade Sistêmica","descricao":"Mentalidade sistêmica é o hábito de enxergar as situações como parte de um todo, percebendo que tudo está conectado e que uma ação em um ponto gera efeitos em outros, muitas vezes distantes ou demorados.","tarefas":[{"titulo":"Ler os 2 primeiros capítulos de “A Quinta Disciplina”, de Peter Senge","comoFazer":"É o livro mais conhecido sobre pensamento sistêmico nas organizações. O autor mostra que muitos problemas nas empresas vêm de enxergarmos só as partes e não o todo. No capítulo 2, ele lista “as dificuldades de aprendizagem” das organizações, como “eu sou o meu cargo” e “o inimigo está lá fora”. Leia identificando quais você reconhece.","comprovacao":"Traga as dificuldades de aprendizagem que reconheceu no seu ambiente de trabalho, com exemplos."},{"titulo":"Assistir ao vídeo “Como os lobos mudam rios”","comoFazer":"É um vídeo curto (cerca de 4 minutos), disponível no YouTube, que mostra como a reintrodução de lobos no Parque Yellowstone, nos Estados Unidos, mudou a vegetação, os animais e até o curso dos rios. É uma forma bonita de entender como tudo está conectado.","comprovacao":"Traga a cadeia de efeitos mostrada no vídeo e um exemplo de cadeia parecida no seu trabalho."},{"titulo":"Desenhar um diagrama de laços causais","comoFazer":"Escolha um problema recorrente no seu trabalho. Desenhe os fatores envolvidos e ligue-os com setas, indicando o que causa o quê. Exemplo: mais atrasos → mais pressão → mais erros → mais retrabalho → mais atrasos. Procure os “ciclos viciosos” que fazem o problema se repetir.","comprovacao":"Traga o diagrama e indique onde seria possível quebrar o ciclo."},{"titulo":"Aplicar o Modelo do Iceberg","comoFazer":"O Modelo do Iceberg divide um problema em 4 níveis: eventos (o que aconteceu), padrões (isso se repete?), estruturas (o que no processo, nas regras ou nos incentivos provoca isso?) e modelos mentais (que crenças mantêm essas estruturas?). Escolha um problema e analise nos 4 níveis.","comprovacao":"Traga a análise nos 4 níveis e em qual nível a solução seria mais efetiva."},{"titulo":"Pensar nos efeitos de segunda e terceira ordem","comoFazer":"Toda decisão tem efeitos imediatos (primeira ordem) e efeitos que vêm depois (segunda e terceira ordem). Escolha uma decisão recente da sua área e responda: qual foi o efeito imediato? E o que isso provocou depois? E depois disso?","comprovacao":"Traga a análise dos 3 níveis de efeito."},{"titulo":"Mapear quem recebe e quem entrega o seu trabalho","comoFazer":"Desenhe a “cadeia” do seu trabalho: de quem você recebe informações ou materiais (fornecedores internos) e para quem você entrega (clientes internos ou externos). Para cada um, anote o que acontece com eles se você atrasar ou errar.","comprovacao":"Traga o mapa e o impacto de um atraso seu em toda a cadeia."}]},
{"numero":48,"nome":"Mindset Visionário","descricao":"Mindset visionário é enxergar possibilidades que ainda não existem, imaginar como as coisas poderiam ser muito melhores e ter coragem de apontar essa direção, inspirando outras pessoas.","tarefas":[{"titulo":"Ler os 3 primeiros capítulos de “De Zero a Um”, de Peter Thiel","comoFazer":"O autor, cofundador do PayPal, diferencia o progresso “de 1 a n” (copiar o que já existe) do progresso “de 0 a 1” (criar algo realmente novo). Ele propõe uma pergunta provocadora: “Que verdade importante pouquíssimas pessoas concordam com você?”. Leia e tente responder.","comprovacao":"Traga sua resposta à pergunta do autor, aplicada ao seu trabalho ou setor."},{"titulo":"Assistir ao filme “Piratas do Vale do Silício”","comoFazer":"O filme conta o início da Apple e da Microsoft, com Steve Jobs e Bill Gates. Os dois enxergaram, muito antes dos outros, que o computador pessoal mudaria o mundo. Observe como cada um construiu e comunicou sua visão, e também os erros que cometeram.","comprovacao":"Traga o que Jobs e Gates enxergaram que os outros não viam e uma lição sobre visão para o seu trabalho."},{"titulo":"Assistir ao discurso “Nós escolhemos ir à Lua”, de John F. Kennedy","comoFazer":"Em 1962, o presidente americano anunciou que o país levaria o homem à Lua antes do fim da década, quando isso ainda parecia impossível. O discurso, disponível no YouTube, é um exemplo clássico de como comunicar uma visão ousada. Observe a estrutura: o desafio, o porquê e o prazo.","comprovacao":"Traga os elementos que tornam o discurso inspirador e escreva uma “visão ousada” de 5 linhas para sua área."},{"titulo":"Escrever uma “carta do futuro”","comoFazer":"Imagine que se passaram 3 anos e tudo deu muito certo no seu trabalho. Escreva uma carta para você mesmo, datada daqui a 3 anos, contando com detalhes o que foi alcançado, como é o seu dia a dia, do que você se orgulha. Escreva no passado, como se já tivesse acontecido.","comprovacao":"Traga a carta e as 3 primeiras ações que te aproximam dessa visão."},{"titulo":"Fazer o exercício “10 vezes melhor”","comoFazer":"A maioria das melhorias busca 10% a mais. Pensar em 10 vezes mais obriga a reinventar. Escolha um processo, serviço ou entrega do seu trabalho e pergunte: “Como isso poderia ser 10 vezes melhor, mais rápido ou mais barato?”. Não se limite ao que parece possível hoje.","comprovacao":"Traga as ideias geradas e uma que poderia ser o primeiro passo."},{"titulo":"Montar um quadro de visão profissional","comoFazer":"Em um papel grande ou em uma ferramenta digital (Canva, Pinterest), reúna imagens, palavras e frases que representem onde você quer chegar profissionalmente: tipo de trabalho, impacto, estilo de vida, competências. Deixe o quadro visível.","comprovacao":"Traga uma foto ou print do quadro e explique os 3 elementos mais importantes."}]},
{"numero":49,"nome":"Negociação","descricao":"Negociação é a capacidade de chegar a acordos que atendam aos interesses das partes envolvidas, preparando-se bem, entendendo o que o outro precisa e buscando soluções em que os dois lados saiam satisfeitos.","tarefas":[{"titulo":"Ler os 3 primeiros capítulos de “Como Chegar ao Sim”, de Roger Fisher, William Ury e Bruce Patton","comoFazer":"É o livro mais famoso do mundo sobre negociação, escrito por professores de Harvard. Os autores propõem 4 princípios: separar as pessoas do problema, focar em interesses e não em posições, criar opções de ganho mútuo e usar critérios objetivos. Leia pensando em negociações que você já fez.","comprovacao":"Traga os 4 princípios aplicados a uma negociação real que você viveu ou vai viver."},{"titulo":"Assistir ao filme “Ponte dos Espiões”","comoFazer":"O filme conta a história real de um advogado americano enviado para negociar a troca de um espião soviético por um piloto americano durante a Guerra Fria. Observe como ele se prepara, identifica o que cada lado realmente quer e usa isso a seu favor.","comprovacao":"Traga 3 técnicas de negociação que o personagem usou."},{"titulo":"Definir sua MAANA antes de negociar","comoFazer":"MAANA significa “Melhor Alternativa à Negociação de um Acordo”: o que você faz se não houver acordo. Quanto melhor sua alternativa, mais força você tem. Escolha uma negociação futura (salário, prazo, compra, divisão de tarefas) e escreva: qual é minha MAANA? E qual deve ser a do outro lado?","comprovacao":"Traga a análise da MAANA dos dois lados."},{"titulo":"Montar uma planilha de preparação","comoFazer":"Antes de uma negociação, prepare uma página com: meu objetivo ideal, o mínimo que aceito, os interesses por trás, os possíveis interesses do outro lado, 3 opções criativas que poderiam atender os dois, critérios objetivos para sustentar sua proposta (preços de mercado, prazos padrão) e as concessões que pode fazer.","comprovacao":"Traga a planilha preenchida para uma negociação real."},{"titulo":"Planejar suas concessões","comoFazer":"Uma armadilha comum é ceder rápido demais ou sem receber nada em troca. Para a próxima negociação, planeje antes: o que posso ceder, em que ordem e o que peço em troca de cada concessão. Use a fórmula “Se você…, então eu…”.","comprovacao":"Traga o plano de concessões e, se a negociação aconteceu, como ele funcionou."},{"titulo":"Negociar algo no seu dia a dia","comoFazer":"Pratique em situações de baixo risco: negociar um desconto na renovação de um plano de celular ou internet, pedir condições melhores em uma compra, combinar a divisão de tarefas em casa. Prepare-se antes usando o que aprendeu (interesses, MAANA, opções).","comprovacao":"Traga o que negociou, como se preparou e qual foi o resultado."}]},
{"numero":50,"nome":"Networking","descricao":"Networking é construir e manter uma rede de relacionamentos profissionais baseada em troca genuína, ajudando e sendo ajudado, e não apenas procurando as pessoas quando se precisa de algo.","tarefas":[{"titulo":"Ler os 3 primeiros capítulos de “Nunca Almoce Sozinho”, de Keith Ferrazzi","comoFazer":"O autor mostra que o segredo de uma boa rede de contatos é a generosidade: ajudar as pessoas antes de precisar delas. Ele desmonta a ideia de networking como algo interesseiro e ensina a construir relações de verdade. Leia anotando as práticas que você pode adotar.","comprovacao":"Traga 3 práticas do livro e como vai aplicar cada uma nas próximas semanas."},{"titulo":"Atualizar seu perfil no LinkedIn","comoFazer":"Revise seu perfil com atenção: foto profissional, título que diga o que você faz e o valor que gera (não só o cargo), resumo contando sua trajetória e seus interesses, experiências com resultados concretos e competências. Peça para alguém de confiança dar uma olhada, se possível.","comprovacao":"Traga um print do perfil antes e depois."},{"titulo":"Mapear sua rede atual","comoFazer":"Desenhe 3 círculos: no centro, as pessoas com quem você tem uma relação próxima; no meio, as que conhece bem mas com quem fala pouco; e fora, as que conhece de vista ou já trabalharam com você. Coloque nomes em cada círculo. Depois identifique áreas ou tipos de pessoa que estão faltando na sua rede.","comprovacao":"Traga o mapa e as lacunas identificadas."},{"titulo":"Participar de um evento ou comunidade do seu setor","comoFazer":"Procure um evento, palestra, webinar, meetup ou grupo on-line ligado à sua área (Sympla e Meetup são bons lugares para encontrar). Participe e, se for presencial, converse com pelo menos 2 pessoas novas; se for on-line, participe do chat ou faça uma pergunta. Depois, conecte-se no LinkedIn com quem conheceu.","comprovacao":"Traga qual evento participou, quem conheceu e o que aprendeu."},{"titulo":"Reconectar-se com 3 pessoas do passado","comoFazer":"Escolha 3 pessoas com quem trabalhou ou estudou e com quem perdeu contato. Mande uma mensagem sincera, sem pedir nada: pergunte como estão, comente algo que viram delas ou lembre de algo bom que viveram juntos.","comprovacao":"Traga as mensagens enviadas e as respostas recebidas."},{"titulo":"Oferecer valor para sua rede","comoFazer":"Durante um mês, ofereça algo útil para sua rede toda semana: compartilhar um artigo interessante com alguém que se beneficiaria, comentar com qualidade a publicação de um contato, indicar alguém para uma oportunidade, apresentar duas pessoas que poderiam se ajudar.","comprovacao":"Traga o registro das 4 ações realizadas."}]},
{"numero":51,"nome":"Orientação ao Cliente","descricao":"Orientação ao cliente é colocar as necessidades de quem recebe o seu trabalho (cliente externo ou interno) no centro das suas decisões, buscando entender o que ele realmente precisa e entregar uma boa experiência.","tarefas":[{"titulo":"Ler os 3 primeiros capítulos de “Nos Bastidores da Disney”, de Tom Connellan","comoFazer":"Em formato de história, o livro mostra os segredos que fazem da Disney uma referência em atendimento: atenção aos detalhes, cada funcionário como parte do “espetáculo” e a obsessão pela experiência do cliente. É uma leitura leve e cheia de exemplos práticos.","comprovacao":"Traga 3 práticas da Disney e como poderiam ser adaptadas ao seu trabalho."},{"titulo":"Assistir ao filme “Milagre na Rua 34” (versão de 1994 ou original de 1947)","comoFazer":"Um senhor que diz ser o Papai Noel começa a trabalhar em uma loja de departamentos e, para surpresa de todos, passa a indicar aos clientes a loja concorrente quando ela tem o brinquedo mais barato. Em vez de perder, a loja ganha a confiança e a fidelidade dos clientes. Observe essa virada.","comprovacao":"Traga a lição sobre orientação ao cliente que o filme passa e um exemplo de como aplicá-la no seu contexto."},{"titulo":"Mapear a Jornada do Cliente","comoFazer":"Escolha um cliente (externo ou interno) e desenhe todas as etapas pelas quais ele passa ao interagir com você ou com sua área: desde o primeiro contato até a entrega final. Em cada etapa, anote o que ele sente (satisfeito, confuso, frustrado) e onde estão os pontos de dor.","comprovacao":"Traga o mapa da jornada com os pontos de dor marcados e uma melhoria para o principal."},{"titulo":"Ler 20 avaliações de clientes","comoFazer":"Leia 20 avaliações, reclamações ou comentários de clientes sobre a sua empresa ou um concorrente, em sites como o Reclame Aqui, Google, redes sociais ou lojas de aplicativos. Classifique os problemas mais citados e os elogios mais frequentes.","comprovacao":"Traga a classificação e os 3 problemas mais citados."},{"titulo":"Fazer o papel de “cliente oculto”","comoFazer":"Experimente o seu próprio serviço como se fosse um cliente: ligue para o atendimento, acesse o site, faça uma compra, preencha um formulário, envie uma dúvida pelo canal oficial. Observe tudo: facilidade, tempo de resposta, clareza, cordialidade. Se não for possível usar o serviço da sua empresa, faça o mesmo com um concorrente.","comprovacao":"Traga um relato da experiência com pontos positivos e pontos a melhorar."},{"titulo":"Identificar seus clientes internos e o que eles esperam","comoFazer":"Liste as pessoas ou áreas que recebem o seu trabalho. Para cada uma, escreva o que você acha que ela mais valoriza: rapidez, precisão, comunicação, flexibilidade. Se tiver oportunidade, confirme com uma pergunta simples: “O que eu poderia fazer para facilitar o seu trabalho?”. Se não, observe os pedidos e reclamações que chegam até você.","comprovacao":"Traga a lista de clientes internos, o que cada um valoriza e uma melhoria para o principal."}]},
{"numero":52,"nome":"Orientação para Soluções","descricao":"Orientação para soluções é, diante de um problema, direcionar a energia para o que pode ser feito, em vez de ficar preso a reclamações, culpados ou justificativas.","tarefas":[{"titulo":"Ler os 3 primeiros capítulos de “Pense Como um Freak”, de Steven Levitt e Stephen Dubner","comoFazer":"Os autores de “Freakonomics” mostram formas criativas e pouco convencionais de enxergar e resolver problemas: fazer perguntas diferentes, admitir que não sabe, pensar como uma criança. Leia pensando em um problema que está te desafiando.","comprovacao":"Traga 3 formas de pensar do livro e como aplicaria cada uma ao seu problema."},{"titulo":"Assistir ao filme “Perdido em Marte”","comoFazer":"Um astronauta é dado como morto e deixado sozinho em Marte. Em vez de se desesperar, ele decide “resolver um problema de cada vez”: como produzir comida, água, energia, como se comunicar. É uma aula de orientação para soluções, com muito humor.","comprovacao":"Traga 3 problemas que o personagem resolveu e a lógica que ele usou, e aplique essa lógica a um problema seu."},{"titulo":"Aplicar a regra “Problema + 3 soluções”","comoFazer":"Durante 2 semanas, sempre que identificar um problema, antes de reclamar ou comunicar a alguém, escreva pelo menos 3 soluções possíveis, mesmo que imperfeitas. Depois escolha a melhor e aja ou proponha.","comprovacao":"Traga pelo menos 3 problemas com as soluções pensadas e o que foi feito."},{"titulo":"Trocar o “não dá porque” pelo “dá se”","comoFazer":"Durante uma semana, preste atenção quando você pensar ou disser “não dá porque…”. Tente reformular como “dá se…”. Exemplo: “Não dá para entregar sexta porque falta informação” vira “Dá para entregar sexta se eu receber os dados até quarta”. Anote as reformulações.","comprovacao":"Traga pelo menos 5 reformulações."},{"titulo":"Fazer um brainstorm reverso","comoFazer":"Às vezes é mais fácil pensar em como piorar um problema. Escolha um problema e pergunte: “O que eu poderia fazer para piorar isso ao máximo?”. Liste 10 ideias. Depois inverta cada uma: o contrário de cada ideia vira uma possível solução.","comprovacao":"Traga as 10 formas de piorar e as soluções que surgiram da inversão."},{"titulo":"Manter um Diário de Soluções","comoFazer":"Durante 3 semanas, registre os problemas que você resolveu (grandes e pequenos): qual era o problema, o que fez e qual foi o resultado. Isso ajuda a perceber sua capacidade de resolver e a reaproveitar soluções no futuro.","comprovacao":"Traga o diário e a solução da qual mais se orgulha."}]},
{"numero":53,"nome":"Pensamento Crítico","descricao":"Pensamento crítico é avaliar informações, argumentos e crenças com cuidado antes de aceitar algo como verdade: questionar evidências, identificar vieses e chegar a conclusões bem fundamentadas.","tarefas":[{"titulo":"Ler o capítulo “A arte refinada de detectar mentiras”, do livro “O Mundo Assombrado pelos Demônios”, de Carl Sagan","comoFazer":"Nesse capítulo, o astrônomo Carl Sagan apresenta o “kit de detecção de mentiras”: ferramentas para avaliar se uma afirmação faz sentido, como buscar confirmação independente, desconfiar de argumentos de autoridade e considerar explicações alternativas. Leia anotando as ferramentas do kit.","comprovacao":"Traga o kit com suas palavras e aplique 3 ferramentas a uma informação que você recebeu recentemente."},{"titulo":"Assistir ao documentário “A Terra é Plana”, na Netflix","comoFazer":"O documentário acompanha pessoas que acreditam que a Terra é plana. Mais do que rir delas, o filme mostra como qualquer pessoa pode cair em armadilhas de raciocínio: buscar só o que confirma o que já acredita, desconfiar de quem pensa diferente, se apegar a uma comunidade. Assista com olhar para si mesmo.","comprovacao":"Traga 3 armadilhas de raciocínio que o documentário mostra e onde elas podem aparecer no seu trabalho."},{"titulo":"Checar uma notícia antes de acreditar","comoFazer":"Durante uma semana, escolha 3 informações que chegaram até você (por WhatsApp, redes sociais, conversas) e verifique antes de acreditar ou repassar. Use agências de checagem como Aos Fatos e Agência Lupa, procure a fonte original e veja se outros veículos confiáveis confirmam.","comprovacao":"Traga as 3 informações checadas e o resultado de cada verificação."},{"titulo":"Identificar vieses cognitivos nas suas decisões","comoFazer":"Pesquise sobre estes vieses: viés de confirmação (buscar só o que confirma o que já pensamos), ancoragem (se prender à primeira informação), efeito manada (seguir a maioria) e excesso de confiança. Depois pense em decisões recentes e identifique em quais esses vieses podem ter aparecido.","comprovacao":"Traga 3 decisões e o viés que pode ter influenciado cada uma."},{"titulo":"Ser advogado do diabo da sua própria ideia","comoFazer":"Escolha uma ideia ou proposta que você defende no trabalho. Escreva os 5 argumentos mais fortes contra ela, como se fosse alguém que discorda totalmente. Depois avalie: algum desses argumentos muda sua proposta?","comprovacao":"Traga os 5 argumentos contrários e o que ajustaria na sua ideia."},{"titulo":"Usar as perguntas socráticas","comoFazer":"Sócrates ensinava fazendo perguntas que obrigavam as pessoas a examinar suas crenças. Escolha uma afirmação comum no seu trabalho (“o cliente só quer preço baixo”, “essa área nunca entrega no prazo”) e responda: O que exatamente isso significa? Como sei que é verdade? Quais evidências existem? Existe outra explicação? Quais são as consequências se estiver errado?","comprovacao":"Traga a afirmação analisada com as respostas às perguntas."}]},
{"numero":54,"nome":"Pensamento Estratégico","descricao":"Pensamento estratégico é enxergar o quadro geral e pensar à frente: entender onde se quer chegar, antecipar movimentos e consequências e escolher caminhos que aumentem as chances de sucesso.","tarefas":[{"titulo":"Ler os 3 primeiros capítulos de “A Arte da Guerra”, de Sun Tzu","comoFazer":"É um tratado chinês com mais de 2.500 anos, hoje usado em escolas de negócios do mundo todo. São capítulos curtos, com frases sobre planejamento, conhecimento do cenário, de si mesmo e do adversário. Leia devagar, pensando em como cada ideia se aplicaria hoje.","comprovacao":"Traga 5 ensinamentos do livro traduzidos para situações do mundo profissional."},{"titulo":"Assistir à série “O Gambito da Rainha”, na Netflix","comoFazer":"A série conta a história de uma jovem prodígio do xadrez. Repare em como ela estuda os adversários, visualiza jogadas à frente, aprende com as derrotas e muda de estratégia. O xadrez é uma das melhores metáforas para o pensamento estratégico.","comprovacao":"Traga 3 comportamentos estratégicos da protagonista e como aplicá-los ao seu trabalho."},{"titulo":"Jogar xadrez com análise","comoFazer":"Crie uma conta gratuita no Lichess ou no Chess.com e jogue pelo menos 5 partidas de ritmo mais lento (15 minutos ou mais). Depois de cada partida, use a ferramenta de análise do próprio site para ver onde errou. O objetivo não é ganhar, mas treinar o hábito de pensar antes de agir e prever a resposta do outro.","comprovacao":"Traga um print do seu histórico e uma lição estratégica que aprendeu nas análises."},{"titulo":"Pensar “três jogadas à frente”","comoFazer":"Escolha uma decisão ou proposta que você vai apresentar. Pense em como as pessoas envolvidas vão reagir (primeira jogada), o que você fará em resposta (segunda) e o que pode acontecer depois (terceira). Prepare-se para as reações mais prováveis.","comprovacao":"Traga o mapa das 3 jogadas e as respostas preparadas."},{"titulo":"Conectar o seu trabalho à estratégia da empresa","comoFazer":"Procure a missão, a visão, os valores e os objetivos estratégicos da empresa (site, intranet, apresentações internas). Depois liste suas principais atividades e ligue cada uma a um objetivo estratégico. Se alguma atividade não se conecta a nada, reflita se ela deveria continuar.","comprovacao":"Traga a ligação entre suas atividades e os objetivos da empresa."},{"titulo":"Responder às 5 perguntas da estratégia","comoFazer":"A.G. Lafley, ex-presidente da Procter & Gamble, propôs 5 perguntas para pensar estrategicamente: Qual é a nossa aspiração vencedora? Onde vamos jogar? Como vamos vencer? Que capacidades precisamos ter? Que sistemas de gestão precisamos? Responda às 5 perguntas pensando na sua área ou na sua carreira.","comprovacao":"Traga as respostas às 5 perguntas."}]},
{"numero":55,"nome":"Pensamento Sistêmico","descricao":"Pensamento sistêmico é analisar um problema ou uma situação considerando as relações, os ciclos e as interdependências entre as partes, para encontrar soluções que funcionem no sistema inteiro, e não só em um pedaço dele.","tarefas":[{"titulo":"Ler a introdução e o capítulo 1 de “Pensando em Sistemas”, de Donella Meadows","comoFazer":"A autora foi uma das maiores pesquisadoras de sistemas do mundo e explica, de forma acessível, conceitos como estoques, fluxos e ciclos de retroalimentação, usando exemplos do dia a dia, como uma banheira enchendo e esvaziando. Leia com calma.","comprovacao":"Traga os conceitos aprendidos aplicados a um processo do seu trabalho (o que é o “estoque”, o que entra e o que sai)."},{"titulo":"Assistir à minissérie “Chernobyl”, na HBO Max","comoFazer":"A série reconstitui o maior acidente nuclear da história. Mais do que um erro individual, o desastre foi resultado de um sistema: falhas de projeto, pressão por resultados, medo de dar más notícias, cultura de esconder problemas. Assista aos 2 primeiros episódios observando as causas sistêmicas.","comprovacao":"Traga as causas sistêmicas do acidente que identificou, separando falhas individuais de falhas do sistema."},{"titulo":"Conhecer os arquétipos sistêmicos","comoFazer":"Arquétipos sistêmicos são padrões que se repetem em vários tipos de sistema. Pesquise sobre 3 deles: “Soluções que falham” (a solução rápida piora o problema depois), “Transferência de responsabilidade” (resolver o sintoma e nunca a causa) e “Tragédia dos comuns” (todos usam um recurso compartilhado até ele acabar). Procure um exemplo de cada no seu trabalho.","comprovacao":"Traga os 3 arquétipos com um exemplo real de cada."},{"titulo":"Estudar o “Efeito Cobra”","comoFazer":"Conta-se que, na Índia colonial, o governo pagava por cada cobra morta para reduzir a população de cobras. Resultado: as pessoas começaram a criar cobras para ganhar a recompensa. Pesquise sobre o “Efeito Cobra” e outros exemplos de incentivos que geraram o efeito contrário.","comprovacao":"Traga 2 exemplos pesquisados e um caso no seu trabalho em que uma meta ou incentivo pode gerar um efeito indesejado."},{"titulo":"Identificar o ponto de alavancagem de um problema","comoFazer":"Donella Meadows chamava de “ponto de alavancagem” o lugar do sistema onde uma pequena mudança gera um grande efeito. Escolha um problema recorrente, liste todas as causas e efeitos que conseguir e identifique onde uma ação pequena resolveria mais coisas ao mesmo tempo.","comprovacao":"Traga o mapa de causas e efeitos e o ponto de alavancagem identificado."},{"titulo":"Analisar uma decisão do ponto de vista de todas as partes","comoFazer":"Escolha uma decisão recente da empresa ou da sua área. Liste todas as partes afetadas (áreas, clientes, fornecedores, comunidade) e, para cada uma, responda: como essa decisão a afeta? Quais efeitos podem demorar a aparecer?","comprovacao":"Traga a análise com todas as partes e os efeitos de curto e longo prazo."}]},
{"numero":56,"nome":"Perseverança","descricao":"Perseverança é continuar firme em direção a um objetivo mesmo diante de obstáculos, frustrações e resultados que demoram a aparecer, ajustando a rota sem desistir do destino.","tarefas":[{"titulo":"Ler os 3 primeiros capítulos de “Garra: O Poder da Paixão e da Perseverança”, de Angela Duckworth","comoFazer":"A autora, psicóloga e pesquisadora, descobriu que o que mais explica o sucesso não é talento, mas “garra”: a combinação de paixão e perseverança por objetivos de longo prazo. No livro há uma escala para medir a própria garra. Leia e responda à escala.","comprovacao":"Traga seu resultado na escala de garra e 3 aprendizados do livro."},{"titulo":"Assistir ao filme “À Procura da Felicidade”","comoFazer":"O filme conta a história real de Chris Gardner, um pai que, sem dinheiro e sem casa, cuidando sozinho do filho, disputa uma vaga de estágio não remunerado numa corretora. A perseverança dele diante de cada obstáculo é impressionante.","comprovacao":"Traga 3 momentos em que ele poderia ter desistido e o que o fez continuar."},{"titulo":"Assistir ao documentário “14 Picos: Nada é Impossível”, na Netflix","comoFazer":"O documentário acompanha o alpinista nepalês Nirmal Purja no desafio de escalar as 14 montanhas mais altas do mundo em 7 meses, algo que antes levava anos. Ele enfrenta falta de dinheiro, descrença e riscos enormes. Observe como ele lida com os obstáculos.","comprovacao":"Traga 3 atitudes de perseverança de Nirmal e como elas se aplicam ao seu trabalho."},{"titulo":"Trocar metas de resultado por metas de processo","comoFazer":"Metas de resultado (“ser promovido”, “bater a meta”) dependem de fatores fora do nosso controle e frustram quando demoram. Metas de processo (“estudar 20 minutos por dia”, “fazer 10 ligações por dia”) dependem só de você. Escolha um objetivo seu e transforme-o em 3 metas de processo. Cumpra por 3 semanas.","comprovacao":"Traga as metas de processo e o registro de cumprimento das 3 semanas."},{"titulo":"Fazer sua “lista de persistência”","comoFazer":"Liste 5 situações da sua vida (profissional ou pessoal) em que você persistiu e conseguiu algo difícil. Para cada uma, anote: o que quase te fez desistir e o que te fez continuar. Essa lista é um lembrete de que você já superou dificuldades antes.","comprovacao":"Traga a lista e o que ela mostra sobre o que te mantém firme."},{"titulo":"Fazer um desafio de 30 dias","comoFazer":"Escolha algo que exija esforço contínuo e que você venha adiando: aprender uma ferramenta, fazer exercícios, estudar um tema, ler um livro técnico. Comprometa-se a fazer um pouco todos os dias durante 30 dias. Registre cada dia e, nos dias difíceis, anote o que te ajudou a não desistir.","comprovacao":"Traga o registro dos 30 dias."}]},
{"numero":57,"nome":"Planejamento e Organização","descricao":"Planejamento e organização é definir objetivos, etapas, prazos e recursos antes de agir, e manter informações, tarefas e materiais estruturados de forma que o trabalho flua sem correria e sem perdas.","tarefas":[{"titulo":"Ler os 2 primeiros capítulos de “A Arte de Fazer Acontecer”, de David Allen","comoFazer":"O autor criou o método GTD (Getting Things Done), um dos mais usados do mundo para organização pessoal. A ideia principal é tirar tudo da cabeça e colocar num sistema confiável, com 5 etapas: capturar, esclarecer, organizar, refletir e engajar. Leia e comece aplicando a primeira etapa.","comprovacao":"Traga a lista de tudo que você “capturou” (pendências, ideias, compromissos) e como organizou."},{"titulo":"Assistir ao filme “Onze Homens e um Segredo”","comoFazer":"No filme, um grupo planeja o roubo simultâneo de três cassinos em Las Vegas. É entretenimento, mas é também uma aula de planejamento: cada detalhe é pensado, cada pessoa tem um papel, há planos para os imprevistos. Observe como o plano é construído.","comprovacao":"Traga os elementos de um bom planejamento que aparecem no filme."},{"titulo":"Usar o 5W2H para planejar uma entrega","comoFazer":"O 5W2H é uma ferramenta simples e muito usada no Brasil. Para planejar qualquer ação, responda 7 perguntas: O quê? Por quê? Onde? Quando? Quem? Como? Quanto custa? Escolha uma entrega ou projeto e monte o plano com essa estrutura.","comprovacao":"Traga o 5W2H preenchido."},{"titulo":"Quebrar um projeto em partes (EAP)","comoFazer":"A Estrutura Analítica do Projeto (EAP) é dividir uma entrega grande em partes menores, até chegar a tarefas simples que você sabe como fazer. Escolha um projeto ou entrega grande e desenhe essa “árvore”: o projeto no topo, as grandes etapas abaixo e as tarefas de cada etapa.","comprovacao":"Traga a EAP desenhada."},{"titulo":"Organizar seu ambiente digital","comoFazer":"Reserve 2 horas para organizar seus arquivos e e-mails: crie uma estrutura de pastas lógica, nomeie arquivos com um padrão (ex.: data_assunto_versão), apague o que não serve, arquive e-mails antigos e crie regras para organizar os novos automaticamente.","comprovacao":"Traga um print da estrutura antes e depois e o padrão de nomes que definiu."},{"titulo":"Montar um quadro de acompanhamento de projeto","comoFazer":"Use uma ferramenta gratuita como Trello, Notion ou até uma planilha para montar um quadro de um projeto ou das suas demandas: tarefas, responsáveis, prazos e status. Atualize diariamente por 2 semanas.","comprovacao":"Traga um print do quadro no início e no final das 2 semanas."}]},
{"numero":58,"nome":"Presença Executiva","descricao":"Presença executiva é a forma como você se apresenta e é percebido: postura, voz, clareza, segurança e capacidade de transmitir credibilidade, especialmente em momentos importantes e diante de pessoas em posições mais altas.","tarefas":[{"titulo":"Assistir ao TED “Sua linguagem corporal molda quem você é”, de Amy Cuddy","comoFazer":"A palestrante fala sobre como a postura corporal influencia a forma como os outros nos veem e também como nós mesmos nos sentimos. Parte da pesquisa foi questionada depois, mas a mensagem sobre a importância da postura e da presença continua valiosa. Assista no site do TED ou no YouTube.","comprovacao":"Traga 3 aprendizados e como vai usar a postura a seu favor em uma situação importante."},{"titulo":"Ler os 3 primeiros capítulos de “O Corpo Fala”, de Pierre Weil e Roland Tompakow","comoFazer":"É um clássico brasileiro sobre linguagem corporal, cheio de ilustrações. Os autores mostram como gestos, posturas e expressões comunicam tanto quanto as palavras. Leia observando seus próprios gestos no dia a dia.","comprovacao":"Traga 3 sinais corporais que você costuma fazer e o que eles podem comunicar."},{"titulo":"Assistir ao filme “A Dama de Ferro”","comoFazer":"O filme conta a trajetória de Margaret Thatcher, primeira-ministra do Reino Unido. Há cenas em que ela treina a voz, a postura e a forma de se vestir para ser levada a sério num ambiente dominado por homens. Independentemente da opinião política, observe como ela constrói sua presença.","comprovacao":"Traga 3 elementos de presença executiva que aparecem no filme."},{"titulo":"Gravar-se em uma situação de apresentação","comoFazer":"Grave um vídeo de 3 minutos apresentando um tema de trabalho, em pé, como se estivesse numa reunião importante. Assista observando: postura, contato visual com a câmera, gestos, ritmo da fala, pausas, tom de voz. Faça ajustes e grave uma segunda versão.","comprovacao":"Traga as duas gravações e as melhorias que aplicou."},{"titulo":"Preparar uma abertura de 30 segundos","comoFazer":"Muitas vezes a impressão se forma nos primeiros segundos. Prepare uma abertura de 30 segundos para situações comuns: apresentar-se numa reunião com pessoas novas, iniciar uma apresentação, começar uma conversa com a liderança. Treine em voz alta até sair natural.","comprovacao":"Traga as aberturas escritas e uma gravação de pelo menos uma delas."},{"titulo":"Praticar o “resumo executivo em 3 frases”","comoFazer":"Pessoas em cargos altos têm pouco tempo. Durante 2 semanas, antes de falar sobre qualquer assunto importante (ou enviar um e-mail para a liderança), resuma em 3 frases: qual é a situação, qual é a sua recomendação e o que você precisa. Use isso como abertura e só depois dê detalhes, se pedirem.","comprovacao":"Traga pelo menos 3 resumos que usou e a reação de quem ouviu ou leu."}]},
{"numero":59,"nome":"Priorização","descricao":"Priorização é escolher, entre muitas coisas possíveis, as poucas que geram mais valor, e ter coragem de colocar as demais em segundo plano.","tarefas":[{"titulo":"Ler os 3 primeiros capítulos de “A Única Coisa”, de Gary Keller e Jay Papasan","comoFazer":"Os autores defendem que o sucesso vem de identificar a única coisa mais importante e colocar toda a energia nela. Eles propõem uma pergunta-guia: “Qual é a única coisa que, se eu fizer, tornará todo o resto mais fácil ou desnecessário?”. Leia e aplique a pergunta ao seu trabalho.","comprovacao":"Traga sua resposta à pergunta-guia e como ela muda sua semana."},{"titulo":"Aplicar o Método ABCDE","comoFazer":"Esse método, do livro “Engula Aquele Sapo!”, de Brian Tracy, classifica as tarefas assim: A (muito importante, consequências sérias se não fizer), B (importante, consequências leves), C (seria bom fazer, sem consequência), D (delegar) e E (eliminar). Só passe para uma tarefa B quando todas as A estiverem feitas. Use durante uma semana.","comprovacao":"Traga as listas classificadas dos 5 dias."},{"titulo":"Usar o método MoSCoW em um projeto","comoFazer":"MoSCoW é usado para priorizar requisitos e entregas: Must have (obrigatório), Should have (importante, mas não essencial), Could have (desejável se sobrar tempo) e Won’t have (não será feito agora). Escolha um projeto ou entrega e classifique todos os itens.","comprovacao":"Traga a classificação e o que mudou no escopo depois dela."},{"titulo":"Montar uma Matriz Impacto x Esforço","comoFazer":"Liste todas as suas demandas e ideias pendentes. Dê uma nota de 1 a 5 para o impacto (quanto valor gera) e para o esforço (quanto trabalho exige). Posicione numa matriz de 4 quadrantes: ganhos rápidos (alto impacto, baixo esforço), grandes projetos, tarefas de preenchimento e armadilhas (baixo impacto, alto esforço).","comprovacao":"Traga a matriz preenchida e o que vai atacar primeiro."},{"titulo":"Encontrar os 20% que geram 80%","comoFazer":"Olhe para todas as atividades que fez no último mês. Quais poucas geraram a maior parte dos resultados? Quais tomaram muito tempo e geraram pouco? Aplique o Princípio de Pareto à sua própria rotina.","comprovacao":"Traga a lista das atividades de alto e baixo retorno e uma decisão que tomou a partir disso."},{"titulo":"Fazer o exercício “Se eu só pudesse fazer 1 coisa hoje”","comoFazer":"Durante 10 dias úteis, antes de abrir e-mail ou mensagens, escreva num post-it: “Se hoje eu só pudesse fazer uma coisa, seria…”. Faça essa coisa primeiro, antes de qualquer outra.","comprovacao":"Traga o registro dos 10 dias e quantos dias conseguiu cumprir a tarefa principal."}]},
{"numero":60,"nome":"Proatividade","descricao":"Proatividade é antecipar-se: prever problemas e necessidades antes que aconteçam e agir sobre o que está ao seu alcance, em vez de apenas reagir ao que chega.","tarefas":[{"titulo":"Ler o capítulo “Hábito 1: Seja Proativo”, de “Os 7 Hábitos das Pessoas Altamente Eficazes”, de Stephen Covey","comoFazer":"É um dos livros mais influentes sobre desenvolvimento pessoal. No primeiro hábito, o autor mostra que entre o que nos acontece e a nossa resposta existe um espaço, e nesse espaço está a nossa liberdade de escolha. Pessoas proativas escolhem suas respostas; pessoas reativas deixam as circunstâncias escolherem por elas.","comprovacao":"Traga 3 ideias do capítulo e uma situação em que você foi reativo e como seria ser proativo."},{"titulo":"Contar suas frases reativas","comoFazer":"Covey mostra que a linguagem revela a postura: frases reativas são “não posso”, “tenho que”, “ele me irrita”, “não tem jeito”; frases proativas são “vou escolher”, “prefiro”, “posso tentar”, “vamos ver as alternativas”. Durante uma semana, anote as frases reativas que você diz ou pensa e reescreva cada uma na versão proativa.","comprovacao":"Traga a lista de frases reativas com as versões proativas."},{"titulo":"Mapear seu Círculo de Influência","comoFazer":"Desenhe dois círculos, um dentro do outro. No maior (Círculo de Preocupação), liste tudo que te preocupa no trabalho. No menor (Círculo de Influência), coloque só aquilo sobre o que você pode agir diretamente. Pessoas proativas concentram energia no círculo menor, e com isso ele cresce.","comprovacao":"Traga os círculos preenchidos e 3 ações dentro do seu Círculo de Influência."},{"titulo":"Fazer um “pré-mortem” da sua semana","comoFazer":"Toda segunda-feira, durante 4 semanas, imagine que a semana deu errado e pergunte: “O que pode ter causado isso?”. Liste os riscos (um prazo apertado, uma informação que depende de alguém, uma reunião difícil) e defina uma ação preventiva para os 2 principais.","comprovacao":"Traga os 4 pré-mortems e se as ações preventivas evitaram algum problema."},{"titulo":"Antecipar-se às perguntas","comoFazer":"Durante 2 semanas, antes que alguém pergunte “como está aquilo?”, mande você a atualização. Antes de uma reunião, envie o material para os participantes. Antes de um prazo, avise se algo pode atrasar. O objetivo é nunca ser pego de surpresa e nunca precisar ser cobrado.","comprovacao":"Traga os exemplos de antecipação que fez e a reação das pessoas."},{"titulo":"Prever uma necessidade de alguém","comoFazer":"Pense em quem recebe o seu trabalho (gestor, cliente, colega) e no que ele vai precisar nas próximas semanas: um relatório, uma informação, um material para uma reunião. Prepare antes de ele pedir.","comprovacao":"Traga o que você previu, o que preparou e a reação da pessoa."}]},
{"numero":61,"nome":"Protagonismo","descricao":"Protagonismo é assumir o papel principal na própria carreira e no próprio desenvolvimento: fazer escolhas conscientes, buscar oportunidades e ser autor da sua história, em vez de esperar que a empresa ou as circunstâncias decidam por você.","tarefas":[{"titulo":"Ler o livro “Qual é a Tua Obra?”, de Mario Sergio Cortella","comoFazer":"O filósofo brasileiro reflete sobre trabalho, liderança, ética e propósito. Ele provoca o leitor a pensar no que está construindo com a própria vida profissional: qual é a sua obra? O livro é curto e cheio de reflexões para levar para o dia a dia.","comprovacao":"Traga 3 reflexões do livro e sua resposta para a pergunta do título."},{"titulo":"Assistir ao filme “O Show de Truman”","comoFazer":"Truman vive, sem saber, dentro de um programa de televisão: tudo na vida dele é controlado por outras pessoas. Aos poucos, ele percebe e decide assumir o controle da própria história, mesmo com medo. É uma metáfora poderosa sobre protagonismo.","comprovacao":"Traga em quais áreas da sua vida profissional você age como Truman antes de perceber a verdade, e o que faria para “sair do cenário”."},{"titulo":"Montar seu próprio Plano de Desenvolvimento Individual (PDI)","comoFazer":"Não espere a empresa fazer por você. Escolha 2 competências que quer desenvolver nos próximos 6 meses. Para cada uma, defina: por que ela é importante, onde está hoje (nota de 1 a 10), onde quer chegar e 3 ações concretas com prazo. Revise a cada mês.","comprovacao":"Traga o PDI preenchido."},{"titulo":"Fazer a Roda da Vida Profissional","comoFazer":"Desenhe um círculo dividido em 8 fatias: realização, aprendizado, relacionamentos no trabalho, reconhecimento, remuneração, equilíbrio, propósito e perspectiva de futuro. Dê uma nota de 0 a 10 para cada uma e pinte as fatias de acordo. Veja onde a roda está “murcha”.","comprovacao":"Traga a roda preenchida e uma ação que depende só de você para melhorar a área com menor nota."},{"titulo":"Escrever o próximo capítulo da sua carreira","comoFazer":"Desenhe uma linha do tempo da sua trajetória profissional até hoje, com os momentos marcantes (conquistas, viradas, dificuldades). Depois escreva, em meia página, como você quer que seja o próximo capítulo, como se fosse o roteiro de um filme em que você é o protagonista.","comprovacao":"Traga a linha do tempo e o texto do próximo capítulo."},{"titulo":"Propor e conduzir um pequeno projeto seu","comoFazer":"Identifique algo que você gostaria de melhorar, criar ou aprender no trabalho e transforme em um pequeno projeto com início, meio e fim: um guia, uma melhoria de processo, um estudo, uma iniciativa para a equipe. Se não houver espaço formal, conduza no seu próprio escopo.","comprovacao":"Traga o projeto, o que foi feito e o resultado."}]},
{"numero":62,"nome":"Raciocínio Lógico e Espacial","descricao":"Raciocínio lógico e espacial é a capacidade de organizar informações, identificar padrões, seguir sequências de causa e efeito e visualizar relações entre elementos, inclusive no espaço.","tarefas":[{"titulo":"Ler os 5 primeiros capítulos de “O Homem que Calculava”, de Malba Tahan","comoFazer":"É um clássico brasileiro, escrito por um professor de matemática sob pseudônimo. Um calculista persa resolve problemas e enigmas usando a lógica, de forma leve e encantadora. Tente resolver cada problema antes de ler a solução.","comprovacao":"Traga 2 problemas do livro, a sua tentativa de solução e a solução do personagem."},{"titulo":"Assistir ao filme “Uma Mente Brilhante”","comoFazer":"O filme conta a história do matemático John Nash, ganhador do Nobel de Economia. Observe as cenas em que ele encontra padrões onde ninguém mais vê e como transforma situações do cotidiano em problemas lógicos.","comprovacao":"Traga 2 cenas que mostram o raciocínio lógico do personagem e o que elas ensinam."},{"titulo":"Resolver um Sudoku por dia durante 10 dias","comoFazer":"O Sudoku treina lógica, dedução e atenção. Use um aplicativo gratuito ou jornal e comece no nível fácil, subindo de nível quando se sentir confortável. Anote quanto tempo levou em cada um.","comprovacao":"Traga o registro dos 10 dias com o nível e o tempo de cada Sudoku."},{"titulo":"Resolver Tangram e quebra-cabeças espaciais","comoFazer":"O Tangram é um quebra-cabeça chinês de 7 peças que formam centenas de figuras. Há versões gratuitas em aplicativos e sites. Resolva pelo menos 15 figuras ao longo de uma semana. Isso treina a capacidade de visualizar formas e relações no espaço.","comprovacao":"Traga prints ou fotos das figuras resolvidas."},{"titulo":"Desenhar o fluxograma de um processo","comoFazer":"Escolha um processo do seu trabalho que tenha decisões no meio (“se o cliente tiver cadastro, faz X; se não, faz Y”). Desenhe o fluxograma com os símbolos básicos: início e fim, ações (retângulos) e decisões (losangos). Use papel ou uma ferramenta gratuita como o draw.io.","comprovacao":"Traga o fluxograma desenhado."},{"titulo":"Resolver problemas do banco de questões da OBMEP","comoFazer":"A Olimpíada Brasileira de Matemática das Escolas Públicas disponibiliza gratuitamente provas e questões antigas com soluções no site oficial. Muitas questões do nível 1 e 2 são de lógica pura e não exigem matemática avançada. Resolva 10 questões ao longo de 2 semanas.","comprovacao":"Traga as 10 questões com suas resoluções e quantas acertou."}]},
{"numero":63,"nome":"Radar de Cenários","descricao":"Radar de cenários é manter a atenção ligada para perceber sinais de mudança no ambiente (tendências, riscos, oportunidades) antes que se tornem óbvios, e pensar em como responder a diferentes futuros possíveis.","tarefas":[{"titulo":"Ler os 2 primeiros capítulos de “Superprevisões”, de Philip Tetlock e Dan Gardner","comoFazer":"Os autores estudaram pessoas comuns que conseguiam prever acontecimentos com mais precisão do que especialistas. Eles descobriram que essas pessoas pensam em probabilidades, atualizam suas opiniões com novas informações e não se prendem a uma única explicação. Leia anotando os hábitos dos “superprevisores”.","comprovacao":"Traga os hábitos identificados e qual deles você pode aplicar ao seu trabalho."},{"titulo":"Assistir ao TED “A próxima epidemia? Não estamos preparados”, de Bill Gates","comoFazer":"Em 2015, cinco anos antes da pandemia de Covid-19, Bill Gates alertou que o mundo não estava preparado para uma epidemia. A palestra, no site do TED e no YouTube, é um exemplo impressionante de leitura de sinais e antecipação de cenários.","comprovacao":"Traga que sinais Gates enxergou e um risco do seu setor que, na sua opinião, está sendo ignorado."},{"titulo":"Criar alertas sobre o seu setor","comoFazer":"Configure o Google Alertas (google.com/alerts) com 5 palavras-chave ligadas ao seu setor, seus concorrentes e tendências da sua área. Durante 3 semanas, leia os alertas e anote o que parecer relevante.","comprovacao":"Traga as palavras-chave configuradas e as 5 notícias mais relevantes das 3 semanas."},{"titulo":"Manter um Diário de Sinais Fracos","comoFazer":"Sinais fracos são pequenos indícios de mudança que ainda não viraram tendência: um concorrente testando algo novo, uma reclamação diferente de clientes, uma tecnologia começando a aparecer. Durante um mês, anote todo sinal fraco que perceber, no trabalho e fora dele.","comprovacao":"Traga o diário e os 3 sinais que considera mais importantes."},{"titulo":"Construir 4 cenários para o futuro da sua área","comoFazer":"Esse método foi popularizado pela Shell. Escolha duas grandes incertezas para os próximos 3 anos (ex.: “a economia vai crescer ou encolher?” e “a tecnologia vai substituir parte do trabalho ou não?”). Cruze as duas em uma matriz de 4 quadrantes e descreva brevemente cada cenário.","comprovacao":"Traga a matriz com os 4 cenários descritos e o que você faria para se preparar em cada um."},{"titulo":"Montar uma Matriz Probabilidade x Impacto de tendências","comoFazer":"Liste 8 tendências ou mudanças que podem afetar sua área (tecnológicas, econômicas, sociais, regulatórias). Dê notas de 1 a 5 para a probabilidade de acontecer e para o impacto se acontecer. As de alta probabilidade e alto impacto merecem atenção imediata.","comprovacao":"Traga a matriz preenchida e um plano de ação para a tendência mais crítica."}]},
{"numero":64,"nome":"Relacionamentos Conectivos","descricao":"Relacionamentos conectivos são vínculos profissionais genuínos, baseados em confiança, interesse real pelo outro e reciprocidade, que conectam pessoas e fazem o trabalho fluir melhor.","tarefas":[{"titulo":"Ler os 3 primeiros capítulos de “As 5 Linguagens da Valorização Pessoal no Ambiente de Trabalho”, de Gary Chapman e Paul White","comoFazer":"Os autores mostram que as pessoas se sentem valorizadas de formas diferentes: palavras de afirmação, tempo de qualidade, atos de serviço, presentes e toque físico adequado (como um aperto de mão). Entender a “linguagem” de cada um fortalece as relações. Leia e identifique a sua linguagem principal.","comprovacao":"Traga sua linguagem principal e a que você imagina ser a de 3 pessoas com quem trabalha."},{"titulo":"Assistir ao TED “O que torna uma vida boa?”, de Robert Waldinger","comoFazer":"O palestrante dirige o estudo mais longo já feito sobre felicidade, que acompanhou pessoas por mais de 75 anos. A conclusão: o que mais faz diferença na vida são relacionamentos de qualidade. Assista no site do TED ou no YouTube.","comprovacao":"Traga 3 aprendizados e o que isso muda na forma como você cuida dos seus relacionamentos no trabalho."},{"titulo":"Assistir ao filme “Green Book: O Guia”","comoFazer":"Baseado em uma história real, o filme mostra a relação entre um pianista negro e erudito e seu motorista branco, cheio de preconceitos, durante uma turnê pelo sul dos Estados Unidos nos anos 1960. A partir de muitas diferenças, nasce uma conexão real. Observe como ela é construída.","comprovacao":"Traga os momentos que fizeram a relação avançar e o que você pode aprender com eles."},{"titulo":"Enviar mensagens de reconhecimento","comoFazer":"Durante 2 semanas, envie uma mensagem de reconhecimento sincero e específico para uma pessoa diferente a cada 2 ou 3 dias. Em vez de “bom trabalho”, diga exatamente o que ela fez e o impacto disso: “Obrigado por ter revisado aquele relatório com tanto cuidado; evitou um erro que teria custado caro.”","comprovacao":"Traga as mensagens enviadas e as reações recebidas."},{"titulo":"Avaliar sua “conta bancária emocional”","comoFazer":"Stephen Covey compara relacionamentos a contas bancárias: cumprir promessas, ser gentil e ouvir são “depósitos”; atrasar, criticar e esquecer são “saques”. Liste as 5 pessoas mais importantes no seu trabalho e avalie como está o saldo com cada uma. Planeje um depósito para cada.","comprovacao":"Traga a lista com o saldo estimado e os depósitos planejados e realizados."},{"titulo":"Registrar o que importa para as pessoas","comoFazer":"Crie uma nota simples com as pessoas com quem você convive no trabalho e, ao longo das conversas, anote detalhes importantes: aniversário, nome dos filhos, hobbies, projetos que as deixam animadas, preocupações que compartilharam. Use essas informações para demonstrar interesse genuíno.","comprovacao":"Traga um exemplo de como usou uma dessas informações para se conectar com alguém (sem expor detalhes pessoais)."}]},
{"numero":65,"nome":"Resiliência","descricao":"Resiliência é a capacidade de enfrentar adversidades, pressões e frustrações, se recuperar e seguir em frente, muitas vezes saindo mais forte e mais experiente da situação.","tarefas":[{"titulo":"Ler a primeira parte de “Em Busca de Sentido”, de Viktor Frankl","comoFazer":"O autor foi um psiquiatra que sobreviveu aos campos de concentração nazistas. Ele conta o que viveu e mostra que, mesmo nas piores situações, temos a liberdade de escolher como reagir, e que encontrar um sentido nos ajuda a suportar quase tudo. É uma leitura forte e transformadora.","comprovacao":"Traga 3 reflexões do livro e como elas se aplicam a um momento difícil que você viveu ou está vivendo."},{"titulo":"Assistir ao filme “Um Sonho de Liberdade”","comoFazer":"Um homem é condenado injustamente e passa décadas na prisão. Em vez de se entregar, ele mantém a esperança, cria pequenos projetos, ajuda outras pessoas e nunca desiste de sair. É considerado um dos melhores filmes de todos os tempos.","comprovacao":"Traga 3 atitudes de resiliência do personagem e qual delas você mais admira."},{"titulo":"Assistir ao TED “Os três segredos das pessoas resilientes”, de Lucy Hone","comoFazer":"A palestrante é pesquisadora de resiliência e perdeu a filha em um acidente. Ela compartilha as 3 estratégias que a ajudaram e que pesquisas mostram que pessoas resilientes usam. Assista no site do TED ou no YouTube.","comprovacao":"Traga as 3 estratégias e como aplicaria cada uma em uma dificuldade do trabalho."},{"titulo":"Analisar seus pensamentos com os “3 Ps” de Seligman","comoFazer":"O psicólogo Martin Seligman mostrou que as pessoas que se recuperam mais rápido não interpretam as dificuldades como Permanentes (“vai ser sempre assim”), Pessoais (“é tudo culpa minha”) e Penetrantes (“estraga tudo na minha vida”). Escolha uma dificuldade recente e reescreva seus pensamentos sem os 3 Ps.","comprovacao":"Traga os pensamentos originais e as versões reescritas."},{"titulo":"Montar sua linha do tempo de superações","comoFazer":"Desenhe uma linha do tempo da sua vida e marque 5 momentos difíceis que você superou. Para cada um, anote: o que aconteceu, o que te ajudou a passar por ele e o que aprendeu. Você vai perceber que já tem mais recursos do que imagina.","comprovacao":"Traga a linha do tempo e os recursos que mais se repetiram."},{"titulo":"Praticar as “3 Coisas Boas” por 7 dias","comoFazer":"Esse exercício, também de Martin Seligman, é um dos mais estudados da psicologia positiva. Todas as noites, durante 7 dias, escreva 3 coisas boas que aconteceram no dia e por que elas aconteceram. Pode ser algo pequeno. O hábito treina o cérebro a perceber o que dá certo, e não só o que dá errado.","comprovacao":"Traga os 7 dias de registro e como se sentiu ao final da semana."}]},
{"numero":66,"nome":"Resolução de Problemas","descricao":"Resolução de problemas é identificar corretamente um problema, entender suas causas, gerar alternativas e colocar em prática uma solução, acompanhando se ela realmente funcionou.","tarefas":[{"titulo":"Definir bem o problema antes de resolver","comoFazer":"Muitos problemas são mal resolvidos porque foram mal definidos. Escolha um problema do seu trabalho e escreva uma “declaração do problema” respondendo: O que está acontecendo? Onde? Desde quando? Com que frequência? Qual é o impacto (em tempo, dinheiro, clientes)? O que não é o problema? Só depois pense em soluções.","comprovacao":"Traga a declaração do problema completa."},{"titulo":"Usar o Diagrama de Ishikawa","comoFazer":"Também chamado de espinha de peixe, esse diagrama organiza as possíveis causas de um problema em 6 categorias: Método, Máquina (equipamentos e sistemas), Material, Mão de obra, Meio ambiente e Medida. Desenhe a espinha com o problema na cabeça e liste as causas em cada categoria.","comprovacao":"Traga o diagrama preenchido e as 2 causas mais prováveis."},{"titulo":"Aplicar o ciclo PDCA a uma melhoria","comoFazer":"O PDCA é um dos métodos mais usados no mundo para resolver problemas: Planejar (definir o problema, a causa e a solução), Fazer (executar em pequena escala), Checar (verificar se funcionou) e Agir (padronizar se deu certo ou recomeçar se não deu). Aplique a um problema real ao longo de 3 a 4 semanas.","comprovacao":"Traga o registro das 4 etapas e o resultado."},{"titulo":"Assistir a um episódio de “Mayday: Desastres Aéreos”","comoFazer":"A série documental reconstrói acidentes aéreos e mostra como os investigadores descobrem as causas, peça por peça, sem conclusões apressadas. Muitas vezes a causa real é bem diferente da primeira suspeita. Escolha um episódio (há vários no YouTube e em serviços de streaming).","comprovacao":"Traga o problema do episódio, a primeira hipótese, a causa real e o método usado pelos investigadores."},{"titulo":"Fazer um Relatório A3","comoFazer":"A Toyota resolve problemas usando uma única folha tamanho A3 com: contexto, situação atual, meta, análise de causas, contramedidas, plano de ação e acompanhamento. Escolha um problema e resuma toda a análise em uma única página seguindo essa estrutura. A limitação de espaço obriga a ser objetivo.","comprovacao":"Traga o A3 preenchido."},{"titulo":"Criar um registro de lições aprendidas","comoFazer":"Crie um documento em que, a cada problema resolvido, você registra: qual era o problema, a causa, a solução e o que aprendeu. Comece com 3 problemas que já resolveu no passado e continue alimentando por um mês.","comprovacao":"Traga o registro com pelo menos 5 lições."}]},
{"numero":67,"nome":"Responsabilidade","descricao":"Responsabilidade é cumprir com cuidado as obrigações do seu papel, honrar compromissos, prazos e combinados e zelar pelas consequências das suas ações para as pessoas e para a empresa.","tarefas":[{"titulo":"Assistir ao filme “Capitão Phillips”","comoFazer":"O filme conta a história real de um comandante de navio cargueiro sequestrado por piratas somalis. Ele assume a responsabilidade pela segurança da tripulação, mesmo colocando a própria vida em risco. Observe as decisões dele e como ele encara o seu papel.","comprovacao":"Traga 3 atitudes de responsabilidade do capitão e o que representam no seu contexto de trabalho."},{"titulo":"Mapear as responsabilidades do seu cargo","comoFazer":"Escreva tudo o que faz parte das suas responsabilidades: atividades, entregas, prazos, decisões, pessoas que dependem de você. Se existir uma descrição formal do cargo, compare. Depois dê uma nota de 1 a 5 para o quanto você cumpre bem cada responsabilidade.","comprovacao":"Traga o mapa com as notas e as 2 responsabilidades que precisa fortalecer."},{"titulo":"Criar uma agenda de compromissos e follow-ups","comoFazer":"Muita irresponsabilidade é, na verdade, esquecimento. Crie um sistema único (agenda, aplicativo ou planilha) em que tudo o que você promete a alguém é registrado na hora, com prazo. Revise todo dia de manhã. Use durante 3 semanas.","comprovacao":"Traga o sistema e quantos compromissos cumpriu no prazo no período."},{"titulo":"Acompanhar seu cumprimento de prazos por 2 semanas","comoFazer":"Durante 2 semanas, anote cada prazo que tiver (entregas, respostas, reuniões) e se cumpriu, cumpriu com atraso ou renegociou antes. Ao final, calcule o seu percentual de cumprimento.","comprovacao":"Traga o registro e o percentual, com o principal motivo dos atrasos."},{"titulo":"Identificar o que está “caindo entre as cadeiras”","comoFazer":"Em toda equipe há tarefas que ninguém assume porque parecem ser de todo mundo (e acabam não sendo de ninguém). Observe durante uma semana e liste essas tarefas no seu contexto. Escolha uma que faça sentido para você e assuma a responsabilidade por ela.","comprovacao":"Traga a lista e o que fez com a tarefa que assumiu."},{"titulo":"Refletir sobre o impacto das suas ações","comoFazer":"Escolha 3 atividades rotineiras suas e responda para cada uma: quem é afetado se eu fizer malfeito ou atrasar? Qual seria o impacto para essa pessoa? Qual seria o impacto para a empresa? Essa reflexão ajuda a enxergar a dimensão real do seu papel.","comprovacao":"Traga a análise das 3 atividades."}]},
{"numero":68,"nome":"Responsabilidade Social","descricao":"Responsabilidade social é considerar o impacto das suas ações e das ações da empresa na sociedade e no meio ambiente, e contribuir de forma ativa para um mundo mais justo e sustentável.","tarefas":[{"titulo":"Assistir ao curta “Ilha das Flores”, de Jorge Furtado","comoFazer":"É um curta-metragem brasileiro de 1989, com cerca de 13 minutos, disponível gratuitamente no YouTube. Com humor ácido, ele acompanha o caminho de um tomate, da plantação até o lixão, e escancara a desigualdade social. É considerado um dos melhores curtas brasileiros de todos os tempos.","comprovacao":"Traga uma reflexão sobre o que o filme mostra e como isso se relaciona com o papel das empresas e das pessoas."},{"titulo":"Ler os 3 primeiros capítulos de “Capitalismo Consciente”, de John Mackey e Raj Sisodia","comoFazer":"O cofundador da rede Whole Foods defende que as empresas podem gerar lucro e, ao mesmo tempo, criar valor para clientes, funcionários, fornecedores, comunidade e meio ambiente. Leia pensando no seu próprio trabalho.","comprovacao":"Traga os princípios do capitalismo consciente e como sua empresa se posiciona em relação a eles."},{"titulo":"Conhecer os 17 Objetivos de Desenvolvimento Sustentável (ODS) da ONU","comoFazer":"Os ODS são 17 metas globais para acabar com a pobreza, proteger o planeta e garantir paz e prosperidade até 2030. Acesse o site das Nações Unidas no Brasil e leia sobre os 17 objetivos. Escolha 3 que têm relação com o trabalho da sua empresa ou área.","comprovacao":"Traga os 3 ODS escolhidos e como sua empresa ou área contribui (ou poderia contribuir) para cada um."},{"titulo":"Estudar as ações sociais e ambientais da sua empresa","comoFazer":"Procure no site, na intranet ou no relatório de sustentabilidade da empresa as ações de responsabilidade social e ambiental (ESG). Se sua empresa não tiver, pesquise uma empresa do mesmo setor que tenha.","comprovacao":"Traga um resumo das ações encontradas e uma sugestão de melhoria ou nova ação."},{"titulo":"Participar de uma ação voluntária","comoFazer":"Escolha uma causa com a qual se identifica e participe de pelo menos uma ação voluntária: pode ser presencial ou a distância. A plataforma Atados (atados.com.br) reúne milhares de oportunidades de voluntariado no Brasil, inclusive pontuais e on-line. Se sua empresa tiver programa de voluntariado, participe por ele.","comprovacao":"Traga o que fez, onde fez e o que aprendeu com a experiência."},{"titulo":"Calcular sua pegada ecológica","comoFazer":"Use a calculadora gratuita de pegada ecológica do WWF-Brasil para descobrir quanto dos recursos do planeta seu estilo de vida consome. Depois, pense também no seu trabalho: impressões, deslocamentos, energia, descarte. Defina 3 mudanças que pode fazer.","comprovacao":"Traga o resultado da calculadora e as 3 mudanças definidas."}]},
{"numero":69,"nome":"Senso de Dono","descricao":"Senso de dono é tratar o trabalho, os recursos e os resultados da empresa como se fossem seus: cuidar, questionar desperdícios, resolver problemas sem esperar ordem e se importar genuinamente com o resultado.","tarefas":[{"titulo":"Ler os 3 primeiros capítulos de “Sonho Grande”, de Cristiane Correa","comoFazer":"O livro conta a história de Jorge Paulo Lemann, Marcel Telles e Beto Sicupira, os empresários por trás de Ambev, Burger King, Americanas e outras empresas. Um dos pilares da cultura que criaram é justamente o senso de dono: cada funcionário agir como se fosse sócio. Leia observando como isso funciona na prática.","comprovacao":"Traga 3 comportamentos de “dono” descritos no livro e como aplicar cada um no seu trabalho."},{"titulo":"Assistir ao filme “Chef”","comoFazer":"Um chef de cozinha talentoso larga o emprego num restaurante e abre o próprio food truck. Observe como a postura dele muda quando o negócio é dele: o cuidado com cada detalhe, com cada cliente, com cada centavo e com a qualidade do que entrega.","comprovacao":"Traga as mudanças de comportamento do chef quando se torna dono e quais você poderia trazer para o seu trabalho."},{"titulo":"Fazer o exercício “Se a empresa fosse minha”","comoFazer":"Imagine que você é dono da empresa, ou pelo menos da sua área. Liste 5 coisas que você mudaria, cortaria ou faria diferente: gastos desnecessários, processos que não fazem sentido, oportunidades desperdiçadas. Depois marque quais delas estão ao seu alcance hoje.","comprovacao":"Traga a lista e uma ação que já colocou em prática."},{"titulo":"Fazer uma auditoria de desperdícios","comoFazer":"Durante uma semana, observe os desperdícios na sua rotina e na sua área: material, energia, tempo em reuniões improdutivas, retrabalho, impressões desnecessárias, assinaturas de ferramentas que ninguém usa. Estime quanto isso custa por mês.","comprovacao":"Traga a lista de desperdícios com a estimativa de custo e uma proposta para reduzir o maior deles."},{"titulo":"Conhecer os números que você impacta","comoFazer":"Todo trabalho afeta algum número da empresa: receita, custo, prazo, satisfação do cliente, qualidade. Descubra quais indicadores o seu trabalho influencia, qual é o valor atual deles e qual é a meta. Acompanhe esses números por um mês.","comprovacao":"Traga os indicadores identificados e sua evolução no mês."},{"titulo":"Resolver um problema que “não é seu”","comoFazer":"Identifique um problema que você percebe, mas que não está formalmente sob sua responsabilidade: um cliente sem resposta, uma informação errada no site, um processo quebrado entre áreas. Em vez de ignorar ou só reclamar, faça o que estiver ao seu alcance: resolva, encaminhe a quem pode resolver ou acompanhe até ser solucionado.","comprovacao":"Traga o problema, o que fez e o resultado."}]},
{"numero":70,"nome":"Senso de Urgência","descricao":"Senso de urgência é identificar o que precisa de atenção imediata, priorizar as demandas relevantes e agir no tempo adequado, sem confundir rapidez com precipitação.","tarefas":[{"titulo":"Assistir à primeira temporada da série “O Urso”, no Disney+","comoFazer":"A série se passa na cozinha caótica de um restaurante em Chicago, onde tudo precisa ser feito rápido, com qualidade e sob pressão. Observe como os personagens organizam o trabalho, como se comunicam na urgência (“Sim, chef!”) e como a falta de organização gera caos.","comprovacao":"Traga 3 comportamentos que mostram senso de urgência saudável e 2 que mostram urgência desorganizada."},{"titulo":"Fazer um registro de demandas urgentes por uma semana","comoFazer":"Durante 5 dias úteis, registre as situações que exigiram resposta rápida. Para cada uma, anote: qual era a demanda, por que era urgente, quando foi recebida, qual ação tomou e quanto tempo levou para começar a resolver.","comprovacao":"Traga o registro da semana e destaque 2 situações em que conseguiu responder com mais agilidade."},{"titulo":"Aplicar a Lei de Parkinson a seu favor","comoFazer":"A Lei de Parkinson diz que o trabalho se expande até ocupar todo o tempo disponível: se você tem uma semana para algo que levaria um dia, vai levar uma semana. Durante 2 semanas, defina para você prazos menores do que os oficiais (por exemplo, terminar na quarta algo que é para sexta).","comprovacao":"Traga as entregas com o prazo oficial, o prazo que você definiu e quando realmente terminou."},{"titulo":"Definir seus próprios tempos de resposta","comoFazer":"Crie um “acordo de nível de serviço” pessoal: em quanto tempo você responde a cada tipo de demanda. Exemplo: cliente, em até 2 horas; e-mail interno, até o fim do dia; pedido do gestor, em até 1 hora. Siga por 2 semanas e registre se conseguiu.","comprovacao":"Traga os tempos definidos e o percentual de cumprimento."},{"titulo":"Criar uma rotina de revisão diária das prioridades","comoFazer":"Durante uma semana, reserve 10 minutos no início do expediente para definir as 3 prioridades do dia e 5 minutos no final para verificar o que foi concluído, o que ficou pendente e por quê.","comprovacao":"Traga o registro dos 5 dias com as 3 prioridades e o status de cada uma (concluída, reprogramada ou pendente)."},{"titulo":"Entender o que é urgente para a sua área","comoFazer":"Liste os tipos de demanda que você recebe e classifique quais devem ser tratados na hora, quais podem esperar algumas horas e quais podem ficar para outro dia. Use sua experiência e as consequências que já viu quando algo atrasou. Se tiver abertura, valide a lista em uma conversa rápida com seu gestor.","comprovacao":"Traga a classificação e uma ação que vai incorporar à rotina."}]},
{"numero":71,"nome":"Tomada de Decisão","descricao":"Tomada de decisão é escolher o melhor caminho entre alternativas, avaliando informações, riscos e consequências, e assumir a escolha feita, aprendendo com os resultados.","tarefas":[{"titulo":"Ler a introdução e o capítulo 1 de “Algoritmos para Viver”, de Brian Christian e Tom Griffiths","comoFazer":"Os autores mostram como técnicas da ciência da computação podem ajudar em decisões do dia a dia. O primeiro capítulo trata da “regra dos 37%”: quando parar de procurar e decidir (por exemplo, ao escolher um apartamento ou um candidato). É uma leitura divertida e surpreendente.","comprovacao":"Traga a regra explicada com suas palavras e uma decisão do seu trabalho em que ela poderia ser aplicada."},{"titulo":"Assistir ao filme “Treze Dias que Abalaram o Mundo”","comoFazer":"O filme retrata a Crise dos Mísseis de Cuba, em 1962, quando o mundo esteve à beira de uma guerra nuclear. Acompanhe como o presidente Kennedy e sua equipe avaliam opções, ouvem opiniões diferentes, resistem à pressão por uma decisão precipitada e escolhem o caminho.","comprovacao":"Traga o processo de decisão usado no filme e o que você pode aprender com ele."},{"titulo":"Usar a Matriz de Decisão Ponderada","comoFazer":"Escolha uma decisão real com pelo menos 3 alternativas. Liste os critérios importantes (custo, prazo, qualidade, risco, esforço) e dê um peso para cada um conforme a importância. Depois dê notas de 1 a 5 para cada alternativa em cada critério e multiplique pelo peso. A soma mostra a alternativa mais equilibrada.","comprovacao":"Traga a matriz preenchida e se o resultado confirmou ou mudou sua intuição."},{"titulo":"Fazer um “pré-mortem” antes de decidir","comoFazer":"Criada pelo psicólogo Gary Klein, a técnica funciona assim: antes de tomar uma decisão importante, imagine que já se passaram 6 meses e a decisão foi um fracasso. Escreva todos os motivos que podem ter levado a isso. Depois ajuste a decisão para reduzir esses riscos.","comprovacao":"Traga a decisão, a lista de motivos do fracasso imaginário e os ajustes feitos."},{"titulo":"Manter um Diário de Decisões","comoFazer":"Durante um mês, registre as decisões importantes que tomar: o que decidiu, quais alternativas havia, que informações tinha, o que esperava que acontecesse e como estava se sentindo. Depois de algumas semanas, volte e anote o que realmente aconteceu. Isso ajuda a separar decisões ruins de azar.","comprovacao":"Traga o diário com pelo menos 5 decisões e as lições que tirou delas."},{"titulo":"Buscar ativamente uma visão contrária","comoFazer":"Antes de uma decisão importante, procure de forma intencional argumentos contra a opção que você prefere: artigos, dados, experiências de outras empresas. Se tiver alguém de confiança, pergunte: “O que você faria diferente?”. O objetivo é evitar decidir só com informações que confirmam o que você já pensa.","comprovacao":"Traga a decisão, os argumentos contrários encontrados e se eles mudaram algo."}]},
{"numero":72,"nome":"Trabalho em Equipe","descricao":"Trabalho em equipe é contribuir para que um grupo funcione bem: cumprir sua parte, apoiar os outros, se comunicar com clareza, lidar bem com diferenças e colocar o objetivo comum acima de interesses individuais.","tarefas":[{"titulo":"Ler a primeira parte de “Os 5 Desafios das Equipes”, de Patrick Lencioni","comoFazer":"Em formato de história, o autor mostra os 5 problemas que destroem equipes: falta de confiança, medo de conflitos, falta de comprometimento, fuga da responsabilidade e falta de atenção aos resultados. A leitura é leve e muito prática.","comprovacao":"Traga os 5 desafios e em qual deles sua equipe está mais forte e mais fraca."},{"titulo":"Assistir aos 2 primeiros episódios de “Arremesso Final”, na Netflix","comoFazer":"A série documental conta a história do Chicago Bulls dos anos 1990, com Michael Jordan. Mesmo com o melhor jogador do mundo, o time só venceu quando todos aprenderam a jogar juntos. Observe como o técnico Phil Jackson construiu o espírito de equipe.","comprovacao":"Traga 3 lições sobre trabalho em equipe da série."},{"titulo":"Estudar o Projeto Aristóteles do Google","comoFazer":"O Google estudou centenas de equipes para descobrir o que fazia algumas terem mais sucesso. A principal conclusão foi a importância da segurança psicológica: a sensação de que é possível errar, perguntar e discordar sem ser punido. Pesquise “Projeto Aristóteles Google” e leia sobre os 5 fatores encontrados.","comprovacao":"Traga os 5 fatores e uma atitude sua que pode aumentar a segurança psicológica da equipe."},{"titulo":"Descobrir seu papel na equipe (Papéis de Belbin)","comoFazer":"Meredith Belbin identificou 9 papéis que as pessoas costumam assumir em equipes, como coordenador, implementador, criativo, finalizador e investigador de recursos. Pesquise sobre os 9 papéis e identifique os 2 que mais combinam com você.","comprovacao":"Traga seus 2 papéis principais, como eles aparecem no dia a dia e que papel costuma faltar na sua equipe."},{"titulo":"Propor acordos de convivência","comoFazer":"Pense no que faria sua equipe funcionar melhor e escreva uma proposta de 5 a 8 acordos simples: horário de responder mensagens, como avisar atrasos, como dar feedback, como conduzir reuniões. Se houver abertura, apresente e construa junto com a equipe; se não, pratique você mesmo esses acordos por um mês.","comprovacao":"Traga os acordos escritos e o que aconteceu ao colocá-los em prática."},{"titulo":"Reconhecer publicamente a contribuição de alguém","comoFazer":"Durante 3 semanas, sempre que alguém da equipe fizer algo que ajudou o resultado, reconheça de forma específica: numa reunião, no grupo da equipe ou num e-mail com cópia para o gestor. Reconhecimento fortalece o espírito de equipe.","comprovacao":"Traga os reconhecimentos feitos e o efeito que percebeu."}]},
{"numero":73,"nome":"Visão Estratégica","descricao":"Visão estratégica é enxergar para onde a empresa e o mercado estão indo, entender como as peças se encaixam e alinhar as ações do dia a dia a essa direção de longo prazo.","tarefas":[{"titulo":"Ler os 2 primeiros capítulos de “A Estratégia do Oceano Azul”, de W. Chan Kim e Renée Mauborgne","comoFazer":"Os autores mostram que, em vez de competir em mercados saturados (oceanos vermelhos), as empresas mais bem-sucedidas criam espaços novos, sem concorrência (oceanos azuis). O exemplo do Cirque du Soleil é o mais famoso. Leia pensando no seu setor.","comprovacao":"Traga a diferença entre oceano vermelho e azul e um exemplo de cada no seu setor."},{"titulo":"Assistir ao filme “BlackBerry”","comoFazer":"O filme conta a ascensão e a queda da empresa que criou o primeiro smartphone de sucesso. Eles dominaram o mercado, mas não enxergaram a mudança que o iPhone traria. É um estudo de caso sobre o que acontece quando falta visão estratégica.","comprovacao":"Traga os momentos em que a empresa errou na leitura estratégica e o que deveria ter feito."},{"titulo":"Aplicar a matriz Eliminar-Reduzir-Elevar-Criar","comoFazer":"Ferramenta do Oceano Azul. Pense em um produto, serviço ou processo da sua área e responda: o que o mercado considera essencial, mas poderia ser eliminado? O que poderia ser reduzido abaixo do padrão? O que deveria ser elevado acima do padrão? O que nunca foi oferecido e poderia ser criado?","comprovacao":"Traga a matriz preenchida."},{"titulo":"Conectar suas tarefas aos objetivos estratégicos","comoFazer":"Pegue os objetivos estratégicos da empresa ou da sua área (se não estiverem escritos em algum lugar, deduza pelo que é mais cobrado e comunicado). Depois desenhe um mapa ligando cada uma das suas principais atividades ao objetivo que ela apoia.","comprovacao":"Traga o mapa e as atividades que não se ligam a nenhum objetivo."},{"titulo":"Analisar 3 concorrentes","comoFazer":"Escolha 3 concorrentes da sua empresa. Pesquise em sites, redes sociais, notícias e avaliações de clientes: o que oferecem, para quem, com que diferencial, como se comunicam e o que os clientes elogiam e reclamam. Compare com a sua empresa.","comprovacao":"Traga a análise comparativa e uma oportunidade que ela revela."},{"titulo":"Estudar o caso Kodak","comoFazer":"A Kodak inventou a câmera digital em 1975, mas engavetou a ideia para proteger seu negócio de filmes fotográficos, e acabou pedindo falência em 2012. Pesquise sobre o caso e responda: por que uma empresa tão grande não enxergou (ou não quis enxergar) o futuro?","comprovacao":"Traga o resumo do caso e o que ele ensina para a sua empresa ou área."}]},
{"numero":74,"nome":"Visão de Negócio","descricao":"Visão de negócio é entender como a empresa ganha dinheiro, quem são seus clientes, quais são seus custos e riscos, e como o seu trabalho contribui para o resultado financeiro e a sustentabilidade do negócio.","tarefas":[{"titulo":"Ler os 5 primeiros capítulos de “A Meta”, de Eliyahu Goldratt","comoFazer":"É um romance de negócios: um gerente tem 3 meses para salvar sua fábrica e, com a ajuda de um mentor, descobre qual é a verdadeira meta de uma empresa e como os gargalos limitam o resultado. É leitura obrigatória em muitas escolas de administração e muito fácil de ler.","comprovacao":"Traga qual é “a meta” segundo o livro e como ela se aplica à sua empresa."},{"titulo":"Montar o Business Model Canvas da sua empresa","comoFazer":"O Canvas é uma ferramenta de uma página que mostra como um negócio funciona em 9 blocos: segmentos de clientes, proposta de valor, canais, relacionamento com clientes, fontes de receita, recursos principais, atividades principais, parcerias principais e estrutura de custos. Pesquise o modelo e preencha para sua empresa.","comprovacao":"Traga o Canvas preenchido e em qual bloco o seu trabalho mais contribui."},{"titulo":"Assistir a 3 episódios de “Shark Tank Brasil”","comoFazer":"No programa, empreendedores apresentam seus negócios a investidores, que fazem perguntas sobre faturamento, margem, custo de aquisição de clientes e escala. Assista observando o que os investidores perguntam e por que aceitam ou recusam as propostas.","comprovacao":"Traga as perguntas mais frequentes dos investidores e as responda sobre a sua empresa ou área."},{"titulo":"Entender como a empresa ganha e gasta dinheiro","comoFazer":"Descubra as principais fontes de receita e os principais custos da empresa. Se for de capital aberto, consulte o site de Relações com Investidores. Se não for, use informações internas, apresentações de resultado ou pesquise sobre empresas parecidas.","comprovacao":"Traga um resumo simples: de onde vem o dinheiro, para onde vai e o que sobra."},{"titulo":"Fazer um curso gratuito sobre modelo de negócios","comoFazer":"O Sebrae oferece cursos on-line gratuitos sobre gestão e modelo de negócios, inclusive sobre o Canvas. Procure no portal de cursos do Sebrae um curso curto sobre modelagem de negócios ou gestão financeira básica e conclua.","comprovacao":"Traga o certificado e 3 aprendizados que se aplicam ao seu trabalho."},{"titulo":"Calcular o custo de um processo ou de um erro","comoFazer":"Escolha um processo do seu trabalho e estime quanto ele custa: horas das pessoas envolvidas (multiplique pelo custo aproximado da hora), materiais, sistemas. Ou calcule o custo de um erro recorrente: retrabalho, cliente perdido, multa. Números simples já trazem muita clareza.","comprovacao":"Traga o cálculo e o que ele revela."}]},
{"numero":75,"nome":"Visão de Futuro","descricao":"Visão de futuro é antecipar como o mundo, o mercado e o trabalho tendem a mudar nos próximos anos e se preparar para isso, desenvolvendo as competências e as ideias que serão necessárias.","tarefas":[{"titulo":"Ler o capítulo “Trabalho”, de “21 Lições para o Século 21”, de Yuval Noah Harari","comoFazer":"O historiador reflete sobre como a inteligência artificial e a automação vão transformar o mercado de trabalho e que tipo de habilidades serão necessárias. O capítulo pode ser lido de forma independente do resto do livro.","comprovacao":"Traga as principais ideias do capítulo e como elas podem afetar a sua profissão."},{"titulo":"Assistir a 2 episódios de “Black Mirror”, na Netflix","comoFazer":"A série imagina como a tecnologia pode transformar (e às vezes distorcer) a vida humana num futuro próximo. Cada episódio é uma história independente. Sugestões: “Queda Livre” (sobre avaliações e reputação) e “Hang the DJ” (sobre algoritmos que decidem por nós). Assista pensando no mundo do trabalho.","comprovacao":"Traga uma reflexão sobre o futuro que cada episódio mostra e o que pode ser relevante para sua área."},{"titulo":"Conhecer o relatório “Futuro dos Empregos” do Fórum Econômico Mundial","comoFazer":"O Fórum Econômico Mundial publica regularmente o relatório “Future of Jobs”, que mostra as profissões e competências que devem crescer e diminuir. Veículos como Exame, Valor e InfoMoney publicam resumos a cada edição. Leia o resumo da edição mais recente.","comprovacao":"Traga as 5 competências em alta e como você está em cada uma."},{"titulo":"Fazer uma “Roda do Futuro”","comoFazer":"Escreva uma tendência no centro de uma folha (ex.: “automação de tarefas administrativas”). Ao redor, escreva as consequências diretas dela. Depois, ao redor de cada consequência, escreva as consequências dessas consequências. O resultado é um mapa de possíveis impactos.","comprovacao":"Traga a roda desenhada e o impacto que considera mais relevante para o seu trabalho."},{"titulo":"Mapear as competências do futuro para sua função","comoFazer":"Imagine como será sua função daqui a 5 anos. Quais tarefas provavelmente serão automatizadas? Quais continuarão exigindo pessoas? Quais novas tarefas vão surgir? Com base nisso, liste as competências que você vai precisar desenvolver.","comprovacao":"Traga a análise e um plano para desenvolver a competência mais urgente."},{"titulo":"Aplicar os 3 Horizontes à sua carreira","comoFazer":"O modelo dos 3 Horizontes divide o futuro em: Horizonte 1 (o que sustenta você hoje), Horizonte 2 (o que está surgindo e pode crescer) e Horizonte 3 (o que ainda é embrionário, mas pode ser o futuro). Aplique à sua carreira: o que te sustenta hoje, o que você está começando a desenvolver e o que pode ser sua aposta de longo prazo.","comprovacao":"Traga os 3 horizontes preenchidos e uma ação para cada um."}]},
{"numero":76,"nome":"Adaptabilidade à Mudança","descricao":"Adaptabilidade à mudança é atravessar transições (de estrutura, de liderança, de função, de ferramenta) de forma construtiva, lidando com as perdas do que ficou para trás e se engajando no novo.","tarefas":[{"titulo":"Assistir ao filme “Náufrago”","comoFazer":"Um executivo obcecado por tempo e produtividade sofre um acidente de avião e fica anos sozinho numa ilha deserta. Tudo o que sabia fazer perde o sentido, e ele precisa reaprender a viver do zero. Observe as fases pelas quais ele passa até se adaptar e, depois, ao voltar para casa.","comprovacao":"Traga as fases de adaptação do personagem e uma mudança da sua vida em que passou por algo parecido."},{"titulo":"Usar o Modelo de Transição de William Bridges","comoFazer":"Bridges diz que toda mudança tem 3 fases: o Fim (deixar para trás o jeito antigo), a Zona Neutra (um período confuso em que o velho já não serve e o novo ainda não está claro) e o Novo Começo. Pesquise sobre o modelo e pense em uma mudança que está vivendo: em que fase você está?","comprovacao":"Traga a mudança, a fase em que está e o que te ajudaria a avançar."},{"titulo":"Fazer a lista “O que perco, o que ganho”","comoFazer":"Resistimos à mudança muitas vezes porque focamos só no que vamos perder. Pegue uma mudança atual e faça duas colunas: o que perco com ela e o que ganho com ela. Seja honesto nas duas. Depois reflita sobre o que pode fazer para reduzir as perdas.","comprovacao":"Traga as duas colunas e a reflexão."},{"titulo":"Ser um dos primeiros a adotar algo novo","comoFazer":"Quando surgir uma nova ferramenta, sistema, processo ou regra, em vez de esperar o último momento, seja um dos primeiros a aprender e usar. Estude antes, teste, descubra os atalhos. Se não houver nada novo no momento, escolha uma ferramenta que a empresa já tem e você ainda não domina.","comprovacao":"Traga o que adotou, como aprendeu e o que achou."},{"titulo":"Escrever uma carta de despedida do “jeito antigo”","comoFazer":"Parece estranho, mas funciona. Escreva uma carta curta se despedindo de um jeito de trabalhar, uma equipe, um sistema ou uma função que ficou para trás: agradeça pelo que foi bom, reconheça o que não servia mais e diga o que leva de aprendizado para o novo momento.","comprovacao":"Traga a carta escrita e como se sentiu ao escrevê-la."},{"titulo":"Definir suas “âncoras de estabilidade”","comoFazer":"Em tempos de mudança, ajuda muito ter coisas que continuam iguais. Liste as âncoras que você pode manter mesmo com tudo mudando: seus valores, uma rotina matinal, um hábito de estudo, pessoas de confiança, um ritual de fim de expediente. Reforce essas âncoras durante o período de mudança.","comprovacao":"Traga a lista de âncoras e como está usando cada uma."}]},
{"numero":77,"nome":"Comunicação com Diferentes Públicos","descricao":"Comunicação com diferentes públicos é adaptar a mensagem, a linguagem, o nível de detalhe e o canal a quem vai receber, seja um cliente, um colega técnico, a diretoria ou alguém leigo no assunto.","tarefas":[{"titulo":"Assistir a um vídeo da série “5 Níveis de Dificuldade”, da revista WIRED","comoFazer":"Nessa série do YouTube, um especialista explica o mesmo conceito para 5 pessoas diferentes: uma criança, um adolescente, um universitário, um pós-graduando e outro especialista. Escolha um vídeo sobre um tema que te interesse (há sobre música, física, computação, entre outros).","comprovacao":"Traga como o especialista mudou a explicação para cada público: vocabulário, exemplos, profundidade."},{"titulo":"Assistir ao filme “A Chegada”","comoFazer":"Uma linguista é chamada para se comunicar com seres de outro planeta, que não compartilham nenhuma língua ou referência com os humanos. Ela precisa construir a comunicação do zero, entendendo como o outro pensa. É uma metáfora poderosa sobre comunicação com públicos muito diferentes.","comprovacao":"Traga as estratégias que a protagonista usou para se comunicar e o que se aplica ao seu dia a dia."},{"titulo":"Explicar o mesmo assunto para 3 públicos","comoFazer":"Escolha um tema do seu trabalho e escreva 3 explicações: uma para uma criança de 10 anos, uma para um cliente ou colega de outra área e uma para a diretoria (focando em impacto e resultado, em no máximo 3 frases).","comprovacao":"Traga as 3 versões."},{"titulo":"Criar uma “persona” para o seu público","comoFazer":"Antes de uma comunicação importante, descreva a pessoa que vai recebê-la: cargo, o que ela já sabe sobre o assunto, o que mais a preocupa, quanto tempo tem para ler ou ouvir, que tipo de linguagem prefere. Depois escreva a mensagem pensando nessa pessoa.","comprovacao":"Traga a persona e a mensagem escrita para ela."},{"titulo":"Traduzir um texto técnico para linguagem simples","comoFazer":"Pegue um texto técnico do seu trabalho (um procedimento, um relatório, uma norma) e reescreva para alguém que não é da área entender. Troque termos técnicos por palavras do dia a dia, use exemplos e frases curtas.","comprovacao":"Traga o texto original e a versão traduzida."},{"titulo":"Estudar comunicadores de divulgação científica","comoFazer":"Assista a 2 vídeos de canais brasileiros que explicam temas complexos para o grande público, como o “Manual do Mundo” ou o “Nerdologia”. Observe as técnicas: como começam, que exemplos usam, como simplificam sem distorcer, como mantêm a atenção.","comprovacao":"Traga 5 técnicas que identificou e como usar uma delas no seu trabalho."}]},
{"numero":78,"nome":"Gestão de Pressão","descricao":"Gestão de pressão é manter o desempenho, a clareza e o equilíbrio emocional em situações de alta exigência, prazos apertados e cobranças, sem se paralisar nem se desgastar além da conta.","tarefas":[{"titulo":"Assistir ao TED “Como transformar o estresse em seu amigo”, de Kelly McGonigal","comoFazer":"A psicóloga de Stanford mostra que o estresse em si não é o maior problema: o que faz mal é acreditar que ele faz mal. Ela explica como mudar a forma de encarar o estresse muda a reação do corpo. Assista no site do TED ou no YouTube.","comprovacao":"Traga 3 aprendizados e como vai reinterpretar uma situação de pressão que vive hoje."},{"titulo":"Ler os 2 primeiros capítulos de “Atenção Plena”, de Mark Williams e Danny Penman","comoFazer":"Os autores, pesquisadores da Universidade de Oxford, apresentam um programa de 8 semanas de mindfulness para lidar com ansiedade e estresse. O livro acompanha meditações guiadas. Leia os primeiros capítulos e experimente a primeira prática.","comprovacao":"Traga o que aprendeu e como foi a experiência com a primeira prática."},{"titulo":"Meditar com o aplicativo Lojong por 10 dias","comoFazer":"O Lojong é um aplicativo brasileiro de meditação, com programas para iniciantes e práticas curtas, a partir de 5 minutos. Faça uma prática por dia durante 10 dias, de preferência no mesmo horário.","comprovacao":"Traga um print do seu histórico no aplicativo e o que percebeu ao final dos 10 dias."},{"titulo":"Fazer um “despejo mental” nos dias de pressão","comoFazer":"Quando a pressão aumentar, pare 10 minutos e escreva numa folha absolutamente tudo o que está na sua cabeça: tarefas, preocupações, medos, lembretes. Depois separe em 3 grupos: o que depende de mim e é para hoje, o que depende de mim e pode esperar, e o que não depende de mim. Faça isso em pelo menos 3 dias difíceis.","comprovacao":"Traga as folhas (ou fotos) e como se sentiu depois do exercício."},{"titulo":"Assistir ao filme “Ford vs Ferrari”","comoFazer":"O filme conta a história real do engenheiro Carroll Shelby e do piloto Ken Miles, contratados pela Ford para vencer a Ferrari nas 24 Horas de Le Mans. Eles enfrentam pressão da corrida, dos prazos e da própria diretoria da Ford. Observe como cada um lida com a pressão.","comprovacao":"Traga 3 momentos de pressão e como os personagens reagiram, identificando o que funcionou e o que não funcionou."},{"titulo":"Incluir pausas de recuperação na rotina","comoFazer":"Pesquisas mostram que o cérebro funciona melhor em ciclos de cerca de 90 minutos de foco seguidos de uma pausa curta. Durante 2 semanas, a cada 90 minutos de trabalho intenso, faça 5 minutos de pausa real: levante, beba água, respire, olhe pela janela, sem celular.","comprovacao":"Traga o registro das pausas e se percebeu diferença na energia ao final do dia."}]},
{"numero":79,"nome":"Orientação para Resultados","descricao":"Orientação para resultados é manter-se comprometido com metas desafiadoras, acompanhar o próprio desempenho e buscar a excelência de forma consistente, entregando valor com regularidade.","tarefas":[{"titulo":"Ler os 3 primeiros capítulos de “As 4 Disciplinas da Execução”, de Chris McChesney, Sean Covey e Jim Huling","comoFazer":"Os autores apresentam um método para executar metas importantes no meio da correria do dia a dia: focar no crucialmente importante, agir nas medidas de direção, manter um placar envolvente e criar uma cadência de responsabilidade. Leia pensando em uma meta que você tem.","comprovacao":"Traga as 4 disciplinas aplicadas a uma meta sua."},{"titulo":"Assistir ao documentário “Jiro Sonha com Sushi”","comoFazer":"O documentário acompanha Jiro Ono, um mestre de sushi japonês que, com mais de 85 anos, ainda busca melhorar todos os dias. Seu restaurante, com apenas 10 lugares, recebeu 3 estrelas Michelin. É um retrato da busca obsessiva pela excelência.","comprovacao":"Traga 3 atitudes de Jiro ligadas a resultados e excelência e uma que você pode adotar."},{"titulo":"Diferenciar medidas de direção e medidas de resultado","comoFazer":"Medida de resultado é o objetivo final (ex.: “vender R$ 100 mil”). Medida de direção é a ação que você controla e que leva ao resultado (ex.: “fazer 20 visitas por semana”). Escolha uma meta sua e defina 2 medidas de direção. Acompanhe por 4 semanas.","comprovacao":"Traga a meta, as medidas de direção e o acompanhamento das 4 semanas."},{"titulo":"Criar um placar pessoal","comoFazer":"Monte um placar visual (em papel, quadro ou planilha) com sua meta principal e as medidas de direção. O placar deve mostrar, em 5 segundos, se você está ganhando ou perdendo. Atualize toda semana.","comprovacao":"Traga uma foto do placar no início e depois de 4 semanas."},{"titulo":"Escrever metas no formato SMART","comoFazer":"Uma meta SMART é: eSpecífica, Mensurável, Atingível, Relevante e com Tempo definido. Pegue 3 metas vagas que você tem (“melhorar meu atendimento”, “ser mais organizado”) e reescreva no formato SMART.","comprovacao":"Traga as 3 metas antes e depois."},{"titulo":"Quantificar seus resultados","comoFazer":"Liste as 5 principais entregas que fez nos últimos 6 meses e, para cada uma, escreva o resultado em números: tempo economizado, dinheiro gerado ou poupado, clientes atendidos, erros evitados, prazos cumpridos. Se não souber os números exatos, faça uma estimativa honesta.","comprovacao":"Traga a lista das 5 entregas com os resultados quantificados."}]},
{"numero":80,"nome":"Visão Sistêmica","descricao":"Visão sistêmica é compreender a empresa como um conjunto de áreas, processos e pessoas interligados, percebendo como o seu trabalho afeta e é afetado pelo todo.","tarefas":[{"titulo":"Assistir ao documentário “O Dilema das Redes”, na Netflix","comoFazer":"O documentário mostra, com depoimentos de ex-funcionários de grandes empresas de tecnologia, como as redes sociais funcionam como um sistema: algoritmos, anúncios, comportamento dos usuários e interesses das empresas se alimentam mutuamente, gerando efeitos que ninguém planejou sozinho.","comprovacao":"Traga o “sistema” que o documentário descreve, com as partes e as conexões entre elas."},{"titulo":"Mapear o SIPOC de um processo","comoFazer":"SIPOC é uma ferramenta que mostra um processo de ponta a ponta: Fornecedores (Suppliers), Entradas (Inputs), Processo, Saídas (Outputs) e Clientes (Customers). Escolha um processo do qual você participa e preencha as 5 colunas.","comprovacao":"Traga o SIPOC preenchido e o ponto do processo em que você atua."},{"titulo":"Mapear as interdependências entre as áreas","comoFazer":"Desenhe as principais áreas da empresa (ou as que se relacionam com a sua) e ligue com setas o que cada uma entrega para a outra: informações, materiais, aprovações, serviços. Use o organograma e sua observação do dia a dia.","comprovacao":"Traga o mapa e a área da qual a sua mais depende."},{"titulo":"Conhecer o trabalho de outra área","comoFazer":"Escolha uma área que se relaciona com a sua e procure entender como ela trabalha: leia seus procedimentos, relatórios ou apresentações, observe as demandas que ela recebe e envia. Se houver abertura, acompanhe alguém de lá por uma hora ou converse rapidamente.","comprovacao":"Traga um resumo de como a área funciona e onde ela se conecta com o seu trabalho."},{"titulo":"Rastrear uma entrega até o cliente final","comoFazer":"Escolha algo que você produz (um relatório, um cadastro, um atendimento, uma peça) e descubra o caminho completo que isso faz até chegar ao cliente final da empresa. Quem usa? O que faz com isso? Que decisões dependem disso?","comprovacao":"Traga o caminho desenhado e o que descobriu sobre a importância do seu trabalho."},{"titulo":"Calcular o efeito cascata de um atraso seu","comoFazer":"Escolha uma entrega sua e imagine que ela atrasou 2 dias. Liste todas as pessoas e áreas que seriam afetadas e como: quem ficaria esperando, que prazos seriam comprometidos, que clientes perceberiam.","comprovacao":"Traga o mapa do efeito cascata."}]},
{"numero":81,"nome":"Adaptabilidade Cognitiva","descricao":"Adaptabilidade cognitiva é a capacidade de mudar a forma de pensar: enxergar um problema por diferentes ângulos, trocar de estratégia mental quando uma não funciona e rever crenças diante de novas informações.","tarefas":[{"titulo":"Ler os 2 primeiros capítulos de “Pense de Novo”, de Adam Grant","comoFazer":"O autor mostra que, num mundo que muda rápido, a capacidade de repensar e desaprender é tão importante quanto a de pensar e aprender. Ele apresenta 3 modos mentais em que costumamos cair (pregador, promotor e político) e propõe um quarto: o de cientista. Leia identificando qual modo você mais usa.","comprovacao":"Traga o modo que você mais usa, com exemplos, e como agiria no modo cientista."},{"titulo":"Assistir ao filme “Ponto de Vista”","comoFazer":"O filme conta um atentado contra o presidente dos Estados Unidos a partir do ponto de vista de 8 pessoas diferentes. A cada nova perspectiva, o espectador descobre informações que mudam completamente a compreensão do que aconteceu.","comprovacao":"Traga como sua interpretação da história mudou ao longo do filme e uma situação do trabalho em que outra perspectiva mudaria sua visão."},{"titulo":"Usar os Seis Chapéus do Pensamento","comoFazer":"Criada por Edward de Bono, a técnica propõe olhar um problema com 6 “chapéus”, um de cada vez: Branco (fatos e dados), Vermelho (emoções e intuição), Preto (riscos e cuidados), Amarelo (benefícios), Verde (criatividade e alternativas) e Azul (organização do pensamento). Escolha uma decisão ou problema e analise com cada chapéu.","comprovacao":"Traga a análise com os 6 chapéus."},{"titulo":"Resolver o mesmo problema de 3 formas diferentes","comoFazer":"Escolha um problema do trabalho e proponha 3 soluções usando lógicas completamente diferentes: uma mais barata, uma mais rápida e uma mais criativa (ou: uma usando tecnologia, uma usando pessoas, uma mudando o processo). O objetivo é treinar a mente a não parar na primeira ideia.","comprovacao":"Traga as 3 soluções e qual escolheria."},{"titulo":"Jogar o “Contexto” por 7 dias","comoFazer":"O Contexto (contexto.me) é um jogo brasileiro gratuito em que você precisa descobrir uma palavra secreta, e cada tentativa mostra o quão perto você está pelo sentido, não pelas letras. Para acertar, é preciso mudar de estratégia o tempo todo. Jogue uma partida por dia durante 7 dias.","comprovacao":"Traga o número de tentativas de cada dia e as estratégias que mudou ao longo da semana."},{"titulo":"Registrar opiniões que você mudou","comoFazer":"Liste 3 opiniões ou crenças (sobre trabalho, pessoas, métodos) que você mudou nos últimos anos. Para cada uma, anote: o que eu pensava antes, o que penso hoje e o que me fez mudar. Depois pense em uma crença atual que talvez mereça ser revista.","comprovacao":"Traga as 3 opiniões e a crença que vai rever."}]},
{"numero":82,"nome":"Agilidade de Aprendizagem","descricao":"Agilidade de aprendizagem é aprender rápido com experiências novas, inclusive com os erros, e aplicar esse aprendizado em situações diferentes daquelas em que ele aconteceu.","tarefas":[{"titulo":"Fazer a Revisão Pós-Ação (AAR) após cada entrega importante","comoFazer":"A Revisão Pós-Ação foi criada pelo Exército dos Estados Unidos e é usada por empresas do mundo todo. Depois de uma entrega, reunião ou projeto, responda 4 perguntas: O que era esperado que acontecesse? O que realmente aconteceu? Por que houve diferença? O que vou fazer igual e o que vou fazer diferente da próxima vez? Faça isso por 3 semanas.","comprovacao":"Traga pelo menos 4 revisões preenchidas."},{"titulo":"Aplicar o Ciclo de Aprendizagem de Kolb","comoFazer":"David Kolb propôs que aprendemos em 4 etapas: ter uma experiência concreta, refletir sobre ela, tirar conclusões (formar conceitos) e testar essas conclusões na prática. Escolha uma experiência recente de trabalho e passe pelas 4 etapas por escrito, terminando com um teste prático.","comprovacao":"Traga as 4 etapas preenchidas e o resultado do teste."},{"titulo":"Montar seu plano 70-20-10","comoFazer":"O modelo 70-20-10 diz que aprendemos cerca de 70% com experiências práticas, 20% com outras pessoas (feedback, observação, conversas) e 10% com cursos e leituras. Escolha uma competência que quer desenvolver e planeje ações nas 3 frentes.","comprovacao":"Traga o plano com ações nas 3 frentes e o que já colocou em prática."},{"titulo":"Aprender uma ferramenta nova em 7 dias e aplicá-la","comoFazer":"Escolha uma ferramenta útil para o seu trabalho que você não domina (Canva, Excel avançado, Power BI, Notion, Trello). Estude 20 minutos por dia durante 7 dias usando tutoriais gratuitos no YouTube ou na página da própria ferramenta. No sétimo dia, use a ferramenta em uma tarefa real.","comprovacao":"Traga o que produziu com a ferramenta."},{"titulo":"Fazer um curso rápido na Escola Virtual da Fundação Bradesco","comoFazer":"A Escola Virtual da Fundação Bradesco oferece dezenas de cursos gratuitos e curtos, com certificado, sobre temas como Excel, gestão, finanças e comunicação. Escolha um que tenha relação com o seu trabalho e conclua em até 2 semanas.","comprovacao":"Traga o certificado e como aplicou o que aprendeu."},{"titulo":"Aprender com os erros dos outros","comoFazer":"Não é preciso errar tudo para aprender. Escolha um caso de fracasso conhecido (uma empresa que quebrou, um produto que não deu certo, um projeto que fracassou) e pesquise o que aconteceu. Anote as lições e como se aplicam à sua realidade.","comprovacao":"Traga o resumo do caso e 3 lições para o seu trabalho."}]},
{"numero":83,"nome":"Autogestão","descricao":"Autogestão é administrar a si mesmo: seu tempo, sua energia, suas emoções, suas metas e seu desenvolvimento, sem depender de alguém cobrando ou organizando por você.","tarefas":[{"titulo":"Ler o capítulo “Gerenciando a Si Mesmo”, do livro “Desafios Gerenciais para o Século XXI”, de Peter Drucker","comoFazer":"Nesse texto clássico, o pai da administração moderna propõe que cada profissional se pergunte: Quais são meus pontos fortes? Como eu trabalho melhor? Quais são meus valores? Onde é meu lugar? Qual deve ser minha contribuição? Leia com calma e responda às perguntas.","comprovacao":"Traga suas respostas às perguntas de Drucker."},{"titulo":"Assistir ao documentário “Minimalismo: Um Documentário sobre as Coisas Importantes”, na Netflix","comoFazer":"O documentário acompanha pessoas que decidiram viver com menos coisas, menos compromissos e mais intenção. Mais do que sobre objetos, é sobre escolher conscientemente onde colocar tempo, energia e atenção.","comprovacao":"Traga 3 reflexões do documentário e o que você poderia “simplificar” na sua rotina de trabalho."},{"titulo":"Fazer um planejamento semanal fixo","comoFazer":"Durante 4 semanas, reserve 30 minutos toda sexta à tarde ou segunda de manhã para planejar a semana: revise o que ficou pendente, veja os compromissos da agenda, defina as 3 prioridades da semana e reserve horários para elas.","comprovacao":"Traga os 4 planejamentos e o quanto de cada um foi cumprido."},{"titulo":"Montar um painel de hábitos por 2 semanas","comoFazer":"Escolha 4 hábitos que influenciam seu desempenho (sono, pausas, atividade física, planejamento do dia) e acompanhe diariamente numa tabela ou aplicativo de hábitos. Veja como esses hábitos se relacionam com a sua produtividade.","comprovacao":"Traga o painel preenchido e a relação que percebeu entre hábitos e desempenho."},{"titulo":"Definir metas trimestrais pessoais","comoFazer":"Escolha 3 metas para os próximos 3 meses: uma de resultado no trabalho, uma de desenvolvimento pessoal e uma de bem-estar. Para cada uma, defina como vai medir e quais são as ações semanais. Revise a cada 2 semanas.","comprovacao":"Traga as 3 metas e o acompanhamento."},{"titulo":"Criar um sistema pessoal de organização","comoFazer":"Escolha uma ferramenta (agenda de papel, Notion, Google Agenda com Tarefas, Trello) e monte um sistema único para: compromissos, tarefas, ideias e anotações. A regra é: tudo entra ali, nada fica só na cabeça. Use por um mês.","comprovacao":"Traga um print ou foto do sistema e o que mudou na sua organização."}]},
{"numero":84,"nome":"Capacidade de Síntese","descricao":"Capacidade de síntese é extrair o essencial de um conjunto de informações e comunicá-lo de forma curta e clara, sem perder o que é importante.","tarefas":[{"titulo":"Fazer o exercício “1 frase, 3 tópicos, 1 parágrafo”","comoFazer":"Escolha um relatório, artigo ou apresentação longa do seu trabalho. Resuma de 3 formas: em uma única frase, em 3 tópicos e em um parágrafo de até 5 linhas. Esse exercício treina diferentes níveis de síntese.","comprovacao":"Traga o material original (ou o título) e as 3 versões de resumo."},{"titulo":"Resumir um artigo longo em 100 palavras","comoFazer":"Escolha um artigo longo de revista ou jornal (de 1.500 palavras ou mais) sobre um tema do seu interesse. Leia com atenção e escreva um resumo de exatamente 100 palavras. Depois compare com o original: faltou algo essencial?","comprovacao":"Traga o resumo de 100 palavras e o link do artigo."},{"titulo":"Fazer mapas mentais","comoFazer":"O mapa mental organiza as ideias a partir de um tema central, com ramificações para os subtemas. Pesquise como fazer um (é bem simples) e use para resumir 3 conteúdos: uma reunião, um capítulo de livro e um processo do trabalho. Pode ser à mão ou em ferramentas gratuitas como o Canva.","comprovacao":"Traga os 3 mapas mentais."},{"titulo":"Resumir um episódio de podcast em 5 linhas","comoFazer":"Escolha 3 episódios do podcast “Café da Manhã”, da Folha de S.Paulo, que analisa um tema do noticiário em cerca de 30 minutos. Depois de ouvir cada um, escreva um resumo de no máximo 5 linhas com: o tema, os principais pontos e a conclusão.","comprovacao":"Traga os 3 resumos."},{"titulo":"Resumir as reuniões de que participar","comoFazer":"Durante 2 semanas, depois de cada reunião, escreva um resumo de no máximo 5 linhas: o que foi decidido, quem vai fazer o quê e até quando. Se fizer sentido, compartilhe com os participantes.","comprovacao":"Traga pelo menos 5 resumos."},{"titulo":"Criar título e subtítulo para suas entregas","comoFazer":"Como um jornalista, crie para cada relatório ou e-mail importante um título que diga a conclusão principal e um subtítulo de uma linha com o contexto. Exemplo: título “Vendas caíram 12% por falta de estoque em março”; subtítulo “Produtos A e B ficaram 15 dias em falta nas lojas do Sul”. Use durante 2 semanas.","comprovacao":"Traga pelo menos 4 exemplos."}]},
{"numero":85,"nome":"Clareza na Comunicação","descricao":"Clareza na comunicação é transmitir uma mensagem de forma que o outro entenda exatamente o que você quis dizer, sem ambiguidades, sem jargões desnecessários e sem precisar de muitas explicações adicionais.","tarefas":[{"titulo":"Ler o capítulo de introdução de “Ideias que Colam”, de Chip e Dan Heath","comoFazer":"Os autores investigaram por que algumas ideias são lembradas e outras esquecidas. Eles apresentam 6 princípios: simplicidade, surpresa, concretude, credibilidade, emoção e histórias. Explicam também a “maldição do conhecimento”: quando sabemos muito sobre algo, esquecemos como é não saber. Leia com atenção.","comprovacao":"Traga os 6 princípios e um exemplo de “maldição do conhecimento” no seu trabalho."},{"titulo":"Estudar o Guia de Linguagem Simples","comoFazer":"No Brasil, existe um movimento de Linguagem Simples, adotado por governos e empresas para tornar documentos mais fáceis de entender. A Prefeitura de São Paulo e outros órgãos publicaram guias gratuitos. Pesquise “guia de linguagem simples” e leia um deles.","comprovacao":"Traga as 5 regras que mais se aplicam ao seu trabalho e um texto seu reescrito com elas."},{"titulo":"Fazer o “teste da criança de 12 anos”","comoFazer":"Escolha uma explicação ou mensagem do seu trabalho e reescreva de forma que uma criança de 12 anos entenderia. Se possível, peça para alguém de fora da área ler e explicar com as próprias palavras o que entendeu. Se não, grave-se lendo e ouça como se nunca tivesse ouvido falar do assunto.","comprovacao":"Traga o texto original, a versão simplificada e o que descobriu no teste."},{"titulo":"Montar sua lista de jargões","comoFazer":"Durante uma semana, anote todas as siglas, termos técnicos e expressões internas que você usa nas suas comunicações. Para cada um, escreva uma alternativa em linguagem comum. Use a lista para revisar suas mensagens, principalmente para pessoas de fora da área.","comprovacao":"Traga a lista de jargões com as alternativas."},{"titulo":"Assistir ao desafio das “instruções exatas”","comoFazer":"Procure no YouTube por “Exact Instructions Challenge” (desafio das instruções exatas). Nos vídeos, um pai segue literalmente as instruções dos filhos para fazer um sanduíche, e o resultado é hilário, mostrando o quanto nossas instruções são incompletas. Depois escreva o passo a passo de uma tarefa do seu trabalho e siga literalmente, como no vídeo.","comprovacao":"Traga o passo a passo, os pontos em que ele falhou e a versão corrigida."},{"titulo":"Confirmar o entendimento ao final das comunicações","comoFazer":"Durante 2 semanas, ao passar uma orientação importante, feche com uma confirmação: numa conversa, pergunte “Para eu ter certeza de que fui claro, como você vai fazer?”; num e-mail, termine com um resumo em tópicos do que precisa ser feito, por quem e até quando.","comprovacao":"Traga pelo menos 3 exemplos e se a confirmação revelou algum mal-entendido."}]},
{"numero":86,"nome":"Comprometimento","descricao":"Comprometimento é se envolver de verdade com o trabalho e com os objetivos da equipe e da empresa: dar o seu melhor, cumprir o que promete e se manter engajado mesmo quando surgem dificuldades.","tarefas":[{"titulo":"Assistir ao filme “Rudy”","comoFazer":"O filme conta a história real de um jovem baixinho, sem talento óbvio para o esporte e sem dinheiro, cujo sonho é jogar no time de futebol americano da Universidade de Notre Dame. Ninguém acredita nele, mas seu comprometimento conquista treinadores e colegas.","comprovacao":"Traga 3 atitudes de comprometimento do personagem e como se aplicam ao seu trabalho."},{"titulo":"Conectar seu trabalho a um propósito","comoFazer":"Responda por escrito: Quem é beneficiado pelo meu trabalho? O que aconteceria se ele não fosse feito, ou fosse malfeito? De que forma ele contribui para algo maior (os clientes, a empresa, a sociedade)? Pessoas que enxergam o sentido do que fazem tendem a se comprometer mais.","comprovacao":"Traga as respostas e uma frase que resuma o propósito do seu trabalho."},{"titulo":"Cumprir 100% dos prazos por 2 semanas","comoFazer":"Durante 2 semanas, estabeleça o desafio de cumprir 100% dos prazos que assumir. Registre cada prazo e o resultado. Se perceber que não vai conseguir, a regra é avisar antes, com uma nova proposta. Isso também conta como compromisso cumprido.","comprovacao":"Traga o registro de prazos e o percentual de cumprimento."},{"titulo":"Conhecer os valores da empresa e escolher um para viver","comoFazer":"Leia a missão, a visão e os valores da empresa. Escolha o valor com que mais se identifica e defina 3 comportamentos concretos que mostram esse valor no seu dia a dia. Pratique durante um mês.","comprovacao":"Traga o valor escolhido, os 3 comportamentos e exemplos de quando os praticou."},{"titulo":"Fazer um compromisso público com você mesmo","comoFazer":"Escolha uma melhoria que quer fazer no seu trabalho e escreva um compromisso formal: o que vai fazer, até quando e como vai medir. Deixe visível (na mesa, na tela do computador) e, se quiser aumentar o compromisso, conte para alguém de confiança.","comprovacao":"Traga o compromisso escrito e o resultado ao final do prazo."},{"titulo":"Ir além em uma entrega","comoFazer":"Escolha uma entrega das próximas semanas e, além de cumprir o que foi pedido, acrescente algo que agregue valor sem que ninguém peça: uma análise extra, uma sugestão de melhoria, um cuidado a mais com a apresentação, um resumo que facilite a vida de quem vai receber.","comprovacao":"Traga a entrega, o que você acrescentou e a reação de quem recebeu."}]},
{"numero":87,"nome":"Consciência Organizacional","descricao":"Consciência organizacional é entender como a empresa realmente funciona: estrutura, cultura, quem decide o quê, as relações de poder formais e informais e o que é valorizado na prática.","tarefas":[{"titulo":"Ler os 2 primeiros capítulos de “Cultura Organizacional e Liderança”, de Edgar Schein","comoFazer":"O autor é considerado o pai do estudo da cultura organizacional. Ele explica que a cultura tem 3 níveis: os artefatos (o que se vê: escritório, roupas, rituais), os valores declarados (o que a empresa diz que valoriza) e os pressupostos básicos (o que realmente guia o comportamento, muitas vezes sem ninguém perceber). Leia com atenção.","comprovacao":"Traga a explicação dos 3 níveis com suas palavras."},{"titulo":"Analisar a cultura da sua empresa pelos 3 níveis de Schein","comoFazer":"Com base no que aprendeu, observe sua empresa durante uma semana e preencha: quais são os artefatos visíveis? Quais são os valores declarados (no site, nas paredes, nos discursos)? E quais pressupostos realmente guiam o comportamento? Há diferença entre o que se diz e o que se faz?","comprovacao":"Traga a análise dos 3 níveis e as diferenças encontradas."},{"titulo":"Assistir a 3 episódios da série “The Office”","comoFazer":"A série, em formato de falso documentário, mostra o dia a dia de um escritório com um chefe desastrado. Por trás do humor, há uma ótima observação de cultura organizacional: alianças, fofocas, regras não escritas, jogos de poder e o que realmente importa no ambiente.","comprovacao":"Traga 3 dinâmicas organizacionais que aparecem na série e se você reconhece algo parecido no seu ambiente."},{"titulo":"Mapear o poder formal e o informal","comoFazer":"Desenhe o organograma da sua área (o poder formal). Depois, com outra cor, marque o poder informal: quem as pessoas procuram quando precisam de ajuda, quem influencia as decisões mesmo sem cargo, quem sabe das coisas antes de todo mundo.","comprovacao":"Traga o mapa com as duas camadas (sem precisar identificar nomes, se preferir usar funções)."},{"titulo":"Entender como uma decisão importante foi tomada","comoFazer":"Escolha uma decisão relevante da empresa ou da sua área (uma mudança, um investimento, uma nova regra) e investigue: quem propôs? Quem participou? Quem aprovou? Quanto tempo levou? Que fatores pesaram? Use comunicados, atas e o que você observou.","comprovacao":"Traga o caminho da decisão e o que ele revela sobre como a empresa funciona."},{"titulo":"Ler os materiais institucionais da empresa","comoFazer":"Reúna e leia os materiais que a empresa produz sobre si mesma: site institucional, relatório anual, apresentação para novos funcionários, publicações no LinkedIn, comunicados internos. Identifique como a empresa se vê e o que quer que os outros vejam.","comprovacao":"Traga um resumo de uma página: história, momento atual, prioridades e cultura declarada."}]},
{"numero":88,"nome":"Construção de Relacionamentos","descricao":"Construção de relacionamentos é criar, desde o início, vínculos profissionais sólidos e de confiança, com atitudes consistentes que mostram respeito, interesse e confiabilidade.","tarefas":[{"titulo":"Ler os 3 primeiros capítulos de “A Velocidade da Confiança”, de Stephen M. R. Covey","comoFazer":"O autor mostra que a confiança é o que faz as relações e os negócios andarem mais rápido e com menos custo. Ele apresenta 13 comportamentos que constroem confiança, como falar com franqueza, demonstrar respeito, criar transparência e cumprir compromissos. Leia e anote os 13 comportamentos.","comprovacao":"Traga os 13 comportamentos e uma nota de 1 a 5 para você em cada um."},{"titulo":"Assistir ao filme “Intocáveis”","comoFazer":"O filme francês conta a história real de um milionário tetraplégico e do jovem da periferia contratado para cuidar dele. Dois mundos completamente diferentes que, com sinceridade, humor e respeito, constroem uma amizade profunda. Observe o que faz a relação dar certo.","comprovacao":"Traga 3 elementos que construíram a relação entre os dois e como aplicá-los no trabalho."},{"titulo":"Criar uma planilha de relacionamentos","comoFazer":"Liste as 10 pessoas mais importantes para o seu trabalho (dentro e fora da empresa). Para cada uma, anote: como está a relação hoje (de 1 a 5), qual foi o último contato, o que ela valoriza e uma ação para fortalecer a relação. Revise a cada mês.","comprovacao":"Traga a planilha preenchida e as ações realizadas no mês."},{"titulo":"Aproximar-se de alguém com quem ainda não tem relação","comoFazer":"Identifique uma pessoa importante para o seu trabalho com quem você ainda não tem proximidade (de outra área, um cliente, alguém novo na equipe). Dê o primeiro passo: um convite para um café, uma mensagem se apresentando, uma oferta de ajuda. Se não houver oportunidade presencial, comece por uma interação no LinkedIn ou por e-mail.","comprovacao":"Traga o primeiro passo que deu e como a pessoa respondeu."},{"titulo":"Fazer follow-ups personalizados","comoFazer":"Durante 3 semanas, depois de conversas importantes, retome o contato com algo personalizado: “Lembrei de você quando vi este artigo”, “Como foi aquela apresentação que você estava preparando?”, “Consegui resolver aquilo que conversamos, obrigado pela dica”. Isso mostra que você presta atenção.","comprovacao":"Traga os follow-ups feitos e as respostas recebidas."},{"titulo":"Cumprir pequenas promessas","comoFazer":"A confiança é construída nas coisas pequenas. Durante 2 semanas, anote todas as pequenas promessas que fizer (“te mando o arquivo mais tarde”, “vou ver isso e te falo”, “te ligo amanhã”) e cumpra todas. Muitas relações se desgastam justamente nessas pequenas promessas esquecidas.","comprovacao":"Traga a lista de promessas e quantas foram cumpridas."}]},
{"numero":89,"nome":"Cooperação","descricao":"Cooperação é disposição para trabalhar junto, compartilhar recursos e informações e ajustar o próprio trabalho para que o resultado do grupo seja melhor, mesmo quando isso exige abrir mão de algo individualmente.","tarefas":[{"titulo":"Jogar “A Evolução da Confiança”","comoFazer":"É um jogo interativo gratuito, criado por Nicky Case e traduzido para o português, que dura cerca de 30 minutos. Ele mostra, de forma divertida, por que a cooperação às vezes fracassa e o que faz ela funcionar, a partir de uma ideia da teoria dos jogos chamada “dilema do prisioneiro”. Procure por “A Evolução da Confiança Nicky Case”.","comprovacao":"Traga as 3 principais lições do jogo sobre cooperação."},{"titulo":"Assistir ao TED “Comportamento moral nos animais”, de Frans de Waal","comoFazer":"O primatologista mostra experimentos com macacos e elefantes que revelam que a cooperação e o senso de justiça não são exclusividade dos humanos. Há uma cena famosa de um macaco que recebe pepino enquanto o colega recebe uva. Assista no site do TED ou no YouTube.","comprovacao":"Traga 2 experimentos que mais te chamaram atenção e o que eles ensinam sobre cooperação no trabalho."},{"titulo":"Assistir à animação “A Fuga das Galinhas”","comoFazer":"As galinhas de uma fazenda precisam cooperar para escapar antes de virar torta. Cada uma tem um talento e um jeito diferente, e só com a união de todas o plano funciona. É leve e cheio de lições.","comprovacao":"Traga como a cooperação aconteceu no filme e o que você pode levar para sua equipe."},{"titulo":"Criar um tutorial para compartilhar conhecimento","comoFazer":"Pense em algo que você sabe fazer bem e que ajudaria colegas: um atalho no sistema, um processo que só você domina, uma planilha útil. Crie um tutorial simples (passo a passo escrito, com prints, ou um vídeo curto gravando a tela) e disponibilize para a equipe.","comprovacao":"Traga o tutorial criado."},{"titulo":"Identificar onde seu trabalho facilita o dos outros","comoFazer":"Liste as pessoas que dependem do seu trabalho e pergunte-se: em que formato ou momento eu poderia entregar para facilitar a vida delas? Talvez um relatório em outro formato, uma informação antecipada, um padrão de nomes de arquivo. Faça pelo menos um ajuste.","comprovacao":"Traga o ajuste feito e para quem."},{"titulo":"Ajustar-se para ajudar o grupo","comoFazer":"Nas próximas semanas, fique atento a um momento em que você possa ceder algo pelo bem do grupo: trocar um horário, assumir uma parte que ninguém quer, adiar uma prioridade sua para ajudar uma entrega da equipe. Se não surgir, ofereça-se ativamente para apoiar em um momento de pico.","comprovacao":"Traga a situação, o que você cedeu ou ofereceu e o resultado para o grupo."}]},
{"numero":90,"nome":"Gestão de Crises","descricao":"Gestão de crises é agir com rapidez, calma e método diante de situações graves e inesperadas, protegendo pessoas, reduzindo danos, comunicando com clareza e conduzindo a recuperação.","tarefas":[{"titulo":"Assistir ao filme “Contágio”","comoFazer":"Lançado em 2011, o filme mostra a propagação de um vírus mortal pelo mundo e a reação de autoridades de saúde, governos, empresas e cidadãos. Anos depois, muita gente se impressionou com a semelhança com a pandemia de Covid-19. Observe as decisões dos gestores da crise e os erros de comunicação.","comprovacao":"Traga 3 decisões acertadas e 3 erros na gestão da crise mostrada no filme."},{"titulo":"Estudar o caso Tylenol de 1982","comoFazer":"Em 1982, 7 pessoas morreram nos Estados Unidos após tomar cápsulas de Tylenol envenenadas por um criminoso. A Johnson & Johnson recolheu 31 milhões de frascos e se comunicou com total transparência. O caso virou referência mundial em gestão de crise. Pesquise sobre ele.","comprovacao":"Traga o resumo do caso e as lições que ele ensina."},{"titulo":"Criar um plano de contingência","comoFazer":"Escolha uma atividade crítica do seu trabalho e pense no pior cenário possível (o sistema cair no dia do fechamento, a pessoa-chave ficar doente, um fornecedor falhar). Monte um plano: sinais de alerta, primeiras ações, quem avisar, alternativas e como voltar ao normal.","comprovacao":"Traga o plano de contingência."},{"titulo":"Preparar as mensagens-chave de uma crise","comoFazer":"Em uma crise, comunicar mal piora tudo. Imagine uma crise possível na sua área e prepare: 3 mensagens-chave (o que aconteceu, o que está sendo feito, o que as pessoas devem fazer), para quem comunicar primeiro e por qual canal. Seja honesto e objetivo.","comprovacao":"Traga as mensagens preparadas."},{"titulo":"Fazer uma simulação de crise “de mesa”","comoFazer":"Empresas fazem simulações em que a equipe se reúne e reage a um cenário de crise, passo a passo. Faça sua própria versão: escreva um cenário de crise realista, divida em 3 momentos (a notícia chega, a situação piora, a crise começa a ser controlada) e responda o que faria em cada um.","comprovacao":"Traga o cenário e suas respostas para os 3 momentos."},{"titulo":"Analisar uma crise que você viveu","comoFazer":"Pense em uma crise ou situação grave que viveu no trabalho (ou fora dele). Responda: como ela começou? Quais foram os primeiros sinais? O que foi bem feito? O que faltou? O que você faria diferente hoje?","comprovacao":"Traga a análise escrita."}]},
{"numero":91,"nome":"Gestão de Expectativas","descricao":"Gestão de expectativas é alinhar desde o início o que será entregue, como e quando, e manter as pessoas informadas ao longo do caminho, para evitar frustrações, surpresas e desgastes.","tarefas":[{"titulo":"Assistir ao TED “O paradoxo da escolha”, de Barry Schwartz","comoFazer":"O psicólogo mostra que, quanto mais opções e mais expectativas temos, menos satisfeitos ficamos com o resultado. Ele diz, com humor, que o segredo da felicidade são expectativas baixas. Assista no site do TED ou no YouTube, pensando nas expectativas que você cria nas pessoas.","comprovacao":"Traga 3 ideias da palestra e como elas se aplicam às expectativas no seu trabalho."},{"titulo":"Aplicar a regra “prometa menos, entregue mais”","comoFazer":"Durante 3 semanas, ao combinar prazos e entregas, prometa algo que você tem segurança de cumprir com folga, e depois entregue antes ou além. Cuidado para não exagerar na margem a ponto de parecer pouco comprometido: a ideia é ser realista, não pessimista.","comprovacao":"Traga as entregas combinadas, o que foi prometido e o que foi entregue."},{"titulo":"Criar um checklist de alinhamento","comoFazer":"Monte uma lista de perguntas para fazer sempre que receber uma demanda nova: Qual é o objetivo? O que exatamente precisa ser entregue? Em que formato? Até quando? Quem mais precisa aprovar? Como vou saber que ficou bom? Use em todas as demandas por 2 semanas.","comprovacao":"Traga o checklist e 3 demandas em que ele foi usado."},{"titulo":"Enviar atualizações de status padronizadas","comoFazer":"Crie um modelo curto de atualização com: o que foi feito, o que está em andamento, riscos ou atrasos e próximos passos. Durante 3 semanas, envie (ou prepare, se não houver abertura para enviar) essas atualizações para quem aguarda suas entregas, sem esperar ser cobrado.","comprovacao":"Traga o modelo e as atualizações enviadas."},{"titulo":"Renegociar um prazo cedo","comoFazer":"Na próxima vez que perceber que um prazo está em risco, não espere o último dia. Assim que perceber, comunique: o que aconteceu, qual é o novo prazo realista e o que você pode entregar parcialmente até lá. Quanto mais cedo, mais fácil a outra pessoa se reorganizar.","comprovacao":"Traga a situação, a mensagem que enviou e a reação da pessoa."},{"titulo":"Analisar uma frustração causada por expectativas desalinhadas","comoFazer":"Pense em uma situação em que alguém ficou frustrado com você (ou você com alguém) porque esperava algo diferente. Responda: o que cada um esperava? Onde estava o desalinhamento? Em que momento ele poderia ter sido evitado?","comprovacao":"Traga a análise e o que fará diferente daqui para frente."}]},
{"numero":92,"nome":"Gestão de Riscos","descricao":"Gestão de riscos é identificar o que pode dar errado, avaliar a probabilidade e o impacto de cada risco e agir antes para evitar, reduzir ou preparar uma resposta.","tarefas":[{"titulo":"Assistir ao filme “Horizonte Profundo: Desastre no Golfo”","comoFazer":"O filme conta a história real da explosão da plataforma de petróleo Deepwater Horizon, em 2010, que causou mortes e um dos maiores desastres ambientais da história. Os sinais de risco estavam lá, mas foram ignorados por pressão de prazo e custo. Observe cada alerta que foi deixado de lado.","comprovacao":"Traga os sinais de risco ignorados e o que deveria ter sido feito em cada um."},{"titulo":"Montar uma Matriz de Probabilidade x Impacto","comoFazer":"Liste os 10 principais riscos da sua atividade ou de um projeto (atrasos, erros, falhas de sistema, dependência de uma só pessoa, mudanças de regras). Dê notas de 1 a 5 para a probabilidade e para o impacto. Multiplique as notas e ordene os riscos do maior para o menor.","comprovacao":"Traga a matriz preenchida e os 3 riscos mais críticos."},{"titulo":"Definir respostas para os riscos","comoFazer":"Para os 3 riscos mais críticos, escolha uma das 4 estratégias de resposta: evitar (mudar o plano para eliminar o risco), mitigar (reduzir a chance ou o impacto), transferir (passar para outro, como um seguro ou fornecedor) ou aceitar (conviver com ele, com um plano B). Descreva as ações.","comprovacao":"Traga a estratégia e as ações para cada risco."},{"titulo":"Criar um registro de riscos","comoFazer":"Monte uma planilha simples com: risco, probabilidade, impacto, responsável, ação preventiva, status. Alimente com os riscos que identificou e revise a cada 2 semanas durante um mês, atualizando o que mudou.","comprovacao":"Traga a planilha com as revisões."},{"titulo":"Fazer uma Análise de Modos de Falha (FMEA simplificada)","comoFazer":"Escolha um processo do seu trabalho. Para cada etapa, pergunte: o que pode falhar aqui? Qual seria o efeito? Qual seria a causa? Como posso detectar antes que aconteça? Esse método é muito usado na indústria para prevenir falhas.","comprovacao":"Traga a análise etapa por etapa."},{"titulo":"Identificar os “pontos únicos de falha” da sua rotina","comoFazer":"Ponto único de falha é algo que, se falhar, para tudo: um arquivo sem cópia, um conhecimento que só você tem, uma senha que só uma pessoa sabe, um fornecedor sem alternativa. Liste os pontos únicos de falha do seu trabalho e crie uma proteção para pelo menos 2.","comprovacao":"Traga a lista e as proteções criadas."}]},
{"numero":93,"nome":"Inteligência Social","descricao":"Inteligência social é compreender as dinâmicas sociais, perceber o que está acontecendo entre as pessoas e se comportar de forma adequada em diferentes contextos e grupos.","tarefas":[{"titulo":"Ler os 3 primeiros capítulos de “Inteligência Social”, de Daniel Goleman","comoFazer":"Depois do sucesso de “Inteligência Emocional”, o autor escreveu sobre a capacidade de entender e se relacionar com os outros. Ele explica, com base na neurociência, como nossos cérebros se conectam nas interações e como nos influenciamos mutuamente. Leia anotando os conceitos principais.","comprovacao":"Traga 3 conceitos do livro e como aparecem nas suas interações de trabalho."},{"titulo":"Assistir ao filme “A Rede Social”","comoFazer":"O filme conta a criação do Facebook por Mark Zuckerberg. É um ótimo contraexemplo: um personagem genial que tem dificuldade em ler as pessoas, perceber o efeito das suas atitudes e manter relações. Observe as situações sociais que ele interpreta mal.","comprovacao":"Traga 3 situações em que falta inteligência social ao protagonista e como elas poderiam ter sido conduzidas."},{"titulo":"Observar as dinâmicas de um grupo","comoFazer":"Nas próximas 3 reuniões ou encontros em grupo, observe: quem fala mais? Quem é ouvido de verdade? Quem concorda com quem? Quem fica de fora? Como as decisões realmente acontecem? Anote sem julgar.","comprovacao":"Traga suas observações e 2 padrões que percebeu."},{"titulo":"Adaptar seu comportamento a diferentes contextos","comoFazer":"Liste 5 contextos diferentes do seu trabalho (reunião com a diretoria, conversa com colegas, atendimento a cliente, evento informal, reunião por vídeo). Para cada um, descreva como deve ser o tom, a linguagem, o nível de formalidade e a postura mais adequados. Observe se você se adapta bem na prática.","comprovacao":"Traga a descrição dos 5 contextos e onde você precisa se ajustar."},{"titulo":"Lembrar e usar os nomes das pessoas","comoFazer":"Dale Carnegie dizia que o nome de uma pessoa é, para ela, o som mais doce em qualquer idioma. Durante 2 semanas, faça um esforço consciente: ao conhecer alguém, repita o nome na conversa, associe a uma imagem e anote depois. Use o nome nas interações seguintes.","comprovacao":"Traga quantos nomes novos você guardou e como as pessoas reagiram ao serem chamadas pelo nome."},{"titulo":"Fazer perguntas de interesse genuíno","comoFazer":"Durante uma semana, em conversas informais, faça pelo menos uma pergunta por dia que mostre interesse real pela pessoa: sobre um projeto dela, uma opinião, uma experiência, algo que ela comentou antes. Ouça a resposta com atenção, sem desviar para você.","comprovacao":"Traga as perguntas feitas e o que descobriu sobre as pessoas."}]},
{"numero":94,"nome":"Orientação para Melhoria Contínua","descricao":"Orientação para melhoria contínua é o hábito de buscar, todos os dias, pequenas formas de fazer melhor: questionar o jeito atual, eliminar desperdícios e padronizar o que funciona.","tarefas":[{"titulo":"Ler os 2 primeiros capítulos de “Kaizen: A Estratégia para o Sucesso Competitivo”, de Masaaki Imai","comoFazer":"Kaizen é uma palavra japonesa que significa “mudança para melhor” e é a base da filosofia de melhoria contínua da Toyota. O autor mostra que pequenas melhorias diárias, feitas por todos, geram resultados enormes ao longo do tempo. Leia anotando os princípios.","comprovacao":"Traga 3 princípios do Kaizen e como aplicaria cada um na sua rotina."},{"titulo":"Fazer uma melhoria de 1% por dia durante 2 semanas","comoFazer":"Todo dia útil, durante 2 semanas, faça uma pequena melhoria no seu trabalho: um atalho novo, um arquivo organizado, um modelo criado, uma etapa eliminada, uma mensagem mais clara. Precisa ser pequeno o suficiente para caber no dia.","comprovacao":"Traga a lista das 10 melhorias."},{"titulo":"Aplicar o 5S no seu ambiente de trabalho","comoFazer":"O 5S é um método japonês muito usado no Brasil: Seiri (utilização: separar o que é necessário do que não é), Seiton (organização: cada coisa no seu lugar), Seiso (limpeza), Seiketsu (padronização) e Shitsuke (disciplina para manter). Aplique à sua mesa física e ao seu computador.","comprovacao":"Traga fotos ou prints do antes e depois."},{"titulo":"Fazer uma retrospectiva pessoal a cada 15 dias","comoFazer":"Durante 2 meses, a cada 15 dias, responda: O que funcionou bem e devo manter? O que não funcionou e devo parar? O que devo começar a fazer? Escolha uma ação de cada e aplique até a próxima retrospectiva.","comprovacao":"Traga as 4 retrospectivas."},{"titulo":"Manter um registro de melhorias","comoFazer":"Crie uma planilha para registrar melhorias que você fez ou propôs: data, o que era, o que mudou e qual foi o ganho (tempo, qualidade, custo). Alimente por 2 meses. Além de mostrar sua evolução, é um ótimo material para avaliações de desempenho.","comprovacao":"Traga o registro com as melhorias."},{"titulo":"Padronizar um processo que você faz","comoFazer":"Escolha uma atividade que você faz com frequência e que às vezes sai de um jeito, às vezes de outro. Escreva um Procedimento Operacional Padrão (POP): objetivo, quando fazer, passo a passo detalhado, cuidados e resultado esperado. Use o POP nas próximas vezes e ajuste se necessário.","comprovacao":"Traga o POP escrito."}]},
{"numero":95,"nome":"Pensamento Inovador","descricao":"Pensamento inovador é questionar o óbvio, combinar ideias de áreas diferentes e enxergar soluções novas para problemas antigos, colocando o usuário no centro.","tarefas":[{"titulo":"Ler os 2 primeiros capítulos de “Design Thinking”, de Tim Brown","comoFazer":"O autor é presidente da IDEO, uma das empresas de inovação mais famosas do mundo. Ele explica o Design Thinking, uma forma de inovar a partir da empatia com as pessoas: entender profundamente o problema, gerar muitas ideias, prototipar e testar rápido. Leia pensando em um problema do seu trabalho.","comprovacao":"Traga as etapas do Design Thinking aplicadas ao seu problema."},{"titulo":"Assistir ao filme “Air: A História Por Trás do Logo”","comoFazer":"O filme conta como um funcionário da Nike, em 1984, apostou numa ideia fora do padrão: construir uma linha inteira de tênis em torno de um único jogador ainda novato, Michael Jordan. Todos achavam arriscado demais. Observe como ele pensa diferente e defende a ideia.","comprovacao":"Traga o que tornou a ideia inovadora e como ela foi defendida."},{"titulo":"Assistir ao TED “De onde vêm as boas ideias”, de Steven Johnson","comoFazer":"O autor mostra que as grandes ideias raramente surgem num momento de genialidade isolado. Elas nascem da conexão entre ideias parciais de pessoas diferentes, muitas vezes em ambientes de troca, como os cafés da Inglaterra do século 17. Assista no site do TED ou no YouTube.","comprovacao":"Traga 3 ideias da palestra e como criar mais “conexões de ideias” na sua rotina."},{"titulo":"Usar a técnica da “palavra aleatória”","comoFazer":"Criada por Edward de Bono, essa técnica de pensamento lateral força o cérebro a sair do caminho habitual. Escolha um problema, abra um livro ou dicionário numa página aleatória e escolha uma palavra qualquer (ex.: “ponte”). Pense em como essa palavra poderia inspirar uma solução. Faça com 3 palavras diferentes.","comprovacao":"Traga as 3 palavras e as ideias que surgiram."},{"titulo":"Criar soluções por analogia","comoFazer":"Escolha um problema do seu trabalho e pergunte: “Como a natureza resolveria isso?”, “Como um restaurante resolveria isso?”, “Como um aplicativo resolveria isso?”, “Como a Disney resolveria isso?”. Gere uma ideia para cada analogia.","comprovacao":"Traga as 4 analogias e as ideias geradas."},{"titulo":"Questionar os pressupostos","comoFazer":"Escolha um processo ou produto da sua área e liste 5 “verdades” que todos aceitam sem questionar (“o cliente precisa vir até nós”, “o relatório tem que ser mensal”, “essa aprovação é obrigatória”). Para cada uma, pergunte: “E se o contrário fosse verdade?”. Veja que ideias surgem.","comprovacao":"Traga os 5 pressupostos e as ideias que surgiram ao invertê-los."}]},
{"numero":96,"nome":"Persuasão","descricao":"Persuasão é a capacidade de convencer pessoas a aceitar uma ideia, proposta ou ação por meio de bons argumentos, credibilidade e conexão com o que é importante para elas, de forma ética e transparente.","tarefas":[{"titulo":"Ler os 2 primeiros capítulos de “As Armas da Persuasão”, de Robert Cialdini","comoFazer":"É o livro mais famoso sobre persuasão. O autor, psicólogo, apresenta 6 princípios que levam as pessoas a dizer “sim”: reciprocidade, compromisso e coerência, prova social, afeição, autoridade e escassez. Leia com atenção, inclusive para reconhecer quando alguém usa esses princípios com você.","comprovacao":"Traga os 6 princípios com um exemplo de cada no seu dia a dia."},{"titulo":"Assistir ao filme “Obrigado por Fumar”","comoFazer":"O protagonista é o porta-voz da indústria do tabaco e consegue defender o indefensável com argumentos habilidosos. É uma sátira que mostra técnicas de persuasão, e também seus limites éticos. Assista observando as técnicas e reflita sobre onde termina a persuasão e começa a manipulação.","comprovacao":"Traga 3 técnicas de persuasão do personagem e sua avaliação ética sobre cada uma."},{"titulo":"Usar Ethos, Pathos e Logos","comoFazer":"Aristóteles dizia que a persuasão se apoia em 3 pilares: Ethos (credibilidade de quem fala), Pathos (emoção de quem ouve) e Logos (lógica do argumento). Escolha uma proposta que você quer defender e construa o argumento com os 3 pilares.","comprovacao":"Traga o argumento com os 3 pilares identificados."},{"titulo":"Estruturar uma proposta com a Sequência Motivada de Monroe","comoFazer":"É uma estrutura clássica para convencer em 5 passos: Atenção (desperte o interesse), Necessidade (mostre o problema), Satisfação (apresente a solução), Visualização (mostre como será com a solução) e Ação (diga o que precisa acontecer). Use para preparar uma proposta real.","comprovacao":"Traga a proposta estruturada nos 5 passos."},{"titulo":"Analisar comerciais e discursos","comoFazer":"Escolha 3 comerciais de TV ou internet e 1 discurso (de um líder, de um palestrante ou de uma apresentação de produto). Identifique as técnicas de persuasão usadas: emoção, prova social, autoridade, escassez, histórias, números.","comprovacao":"Traga a análise dos 4 materiais."},{"titulo":"Escrever e testar o pitch de uma ideia","comoFazer":"Escolha uma ideia que você gostaria de ver aplicada no trabalho e escreva um pitch de 1 minuto. Grave-se apresentando e ouça como se fosse quem vai decidir: você se convenceria? Ajuste e grave de novo. Se tiver oportunidade, apresente para quem decide.","comprovacao":"Traga as duas versões do pitch (escrita ou gravada) e, se apresentou, o resultado."}]},
{"numero":97,"nome":"Senso Crítico","descricao":"Senso crítico é avaliar com cuidado o que se lê, ouve e vê, inclusive o próprio trabalho, questionando dados, fontes e conclusões e formando opiniões baseadas em evidências.","tarefas":[{"titulo":"Ler os 3 primeiros capítulos de “Factfulness”, de Hans Rosling","comoFazer":"O autor, médico e estatístico sueco, mostra que a maioria das pessoas tem uma visão mais negativa do mundo do que os dados mostram, por causa de instintos que distorcem nossa percepção. Ele apresenta 10 desses instintos e como controlá-los. O livro começa com um teste de 13 perguntas: responda antes de ler.","comprovacao":"Traga seu resultado no teste e os instintos que mais te afetam."},{"titulo":"Assistir ao TED “As melhores estatísticas que você já viu”, de Hans Rosling","comoFazer":"Nessa palestra, uma das mais famosas do TED, o mesmo autor usa gráficos animados para derrubar ideias prontas sobre países “ricos” e “pobres”. É uma aula sobre como olhar os dados antes de acreditar nas opiniões. Assista no site do TED ou no YouTube.","comprovacao":"Traga 2 ideias prontas que a palestra derrubou e uma ideia pronta que existe no seu trabalho."},{"titulo":"Comparar duas fontes sobre o mesmo fato","comoFazer":"Escolha uma notícia importante da semana e leia como ela foi publicada por 2 veículos com linhas editoriais diferentes. Compare: quais fatos aparecem nos dois? O que cada um destaca ou omite? Que palavras usam? Que conclusão cada um sugere?","comprovacao":"Traga a comparação e o que você concluiu sobre o fato."},{"titulo":"Avaliar a qualidade de uma fonte com o teste CRAAP","comoFazer":"O teste CRAAP é usado por bibliotecas para avaliar fontes em 5 critérios: Atualidade (é recente?), Relevância (responde à minha pergunta?), Autoridade (quem escreveu tem credibilidade?), Precisão (há evidências e referências?) e Propósito (quer informar, vender ou convencer?). Aplique a 3 fontes que você usou recentemente no trabalho.","comprovacao":"Traga a avaliação das 3 fontes."},{"titulo":"Identificar gráficos e números enganosos","comoFazer":"Pesquise por “gráficos enganosos” e veja exemplos de truques comuns: eixo que não começa no zero, escala distorcida, amostra pequena, porcentagens sem base. Depois procure pelo menos 2 exemplos reais (em notícias, redes sociais ou apresentações) e explique o problema de cada um.","comprovacao":"Traga os 2 exemplos com a explicação."},{"titulo":"Fazer uma autocrítica estruturada do seu trabalho","comoFazer":"Escolha uma entrega recente sua e avalie como se fosse de outra pessoa: os dados estão corretos e com fonte? As conclusões se sustentam? Há alguma premissa não verificada? O que um crítico apontaria? O que faltou?","comprovacao":"Traga a autocrítica e o que melhoraria na entrega."}]},
{"numero":98,"nome":"Solução de Problemas Complexos","descricao":"Solução de problemas complexos é lidar com problemas que têm muitas causas, muitas partes envolvidas e nenhuma resposta óbvia, decompondo, testando hipóteses e aprendendo ao longo do caminho.","tarefas":[{"titulo":"Ler a primeira parte de “A Arte de Resolver Problemas”, de George Pólya","comoFazer":"O matemático húngaro propôs um método em 4 etapas que se aplica a qualquer tipo de problema: compreender o problema, estabelecer um plano, executar o plano e fazer o retrospecto. Ele apresenta perguntas úteis para cada etapa, como “Você já viu um problema parecido?”. Leia e anote as perguntas.","comprovacao":"Traga as 4 etapas aplicadas a um problema complexo do seu trabalho."},{"titulo":"Classificar problemas com o Modelo Cynefin","comoFazer":"O Cynefin, criado por Dave Snowden, classifica os problemas em 5 domínios: Claros (a solução é óbvia), Complicados (exigem análise de especialista), Complexos (só se entende testando), Caóticos (é preciso agir primeiro para estabilizar) e Confusos (não se sabe em qual domínio está). Cada domínio pede uma abordagem diferente. Pesquise sobre o modelo e classifique 5 problemas da sua área.","comprovacao":"Traga os 5 problemas classificados e a abordagem adequada para cada um."},{"titulo":"Construir uma Árvore de Problemas","comoFazer":"Coloque o problema principal no centro de uma folha. Abaixo dele, escreva as causas, e as causas das causas (as raízes). Acima, escreva os efeitos (os galhos). Tente dividir as causas em grupos que não se sobreponham e que, juntos, cubram tudo (o que consultores chamam de MECE).","comprovacao":"Traga a árvore desenhada e as raízes que considera mais importantes."},{"titulo":"Trabalhar com hipóteses","comoFazer":"Em problemas complexos, é melhor levantar hipóteses e testá-las do que tentar analisar tudo antes de agir. Escolha um problema e escreva 3 hipóteses sobre sua causa principal. Para cada uma, defina: que dado ou teste confirmaria ou descartaria essa hipótese? Faça pelo menos um dos testes.","comprovacao":"Traga as 3 hipóteses, os testes pensados e o resultado do teste feito."},{"titulo":"Resolver problemas de Fermi","comoFazer":"Enrico Fermi, físico italiano, gostava de fazer perguntas aparentemente impossíveis de responder, como “Quantos afinadores de piano existem em Chicago?”. Para resolver, é preciso quebrar o problema em partes menores e estimar cada uma. Resolva estas 3: Quantas pizzas são vendidas por dia em São Paulo? Quantos litros de café sua empresa consome por ano? Quantas horas de reunião sua área tem por mês?","comprovacao":"Traga os 3 problemas com o raciocínio passo a passo e a estimativa final."},{"titulo":"Dividir um problema grande em pequenos experimentos","comoFazer":"Escolha um problema complexo que parece grande demais para resolver de uma vez. Divida em 3 a 5 experimentos pequenos, de baixo custo e rápidos, que ajudem a entender melhor o problema ou testar partes da solução. Realize pelo menos um.","comprovacao":"Traga o plano de experimentos e o resultado do primeiro."}]},
{"numero":99,"nome":"Visão Integrada","descricao":"Visão integrada é enxergar ao mesmo tempo as diferentes dimensões de uma empresa (clientes, finanças, processos, pessoas) e como elas se influenciam, considerando todas ao tomar decisões.","tarefas":[{"titulo":"Conhecer o Balanced Scorecard","comoFazer":"Criado por Robert Kaplan e David Norton, o Balanced Scorecard mostra que uma empresa precisa ser avaliada por 4 perspectivas integradas: financeira, clientes, processos internos e aprendizado e crescimento. Uma alimenta a outra: pessoas capacitadas melhoram processos, que satisfazem clientes, que geram resultado financeiro. Pesquise sobre o modelo e monte um exemplo para sua área.","comprovacao":"Traga um objetivo e um indicador para cada uma das 4 perspectivas, mostrando como se conectam."},{"titulo":"Mapear a Cadeia de Valor da empresa","comoFazer":"Michael Porter propôs a Cadeia de Valor: as atividades principais (logística de entrada, operações, logística de saída, marketing e vendas, pós-venda) e as de apoio (infraestrutura, gestão de pessoas, tecnologia, compras). Desenhe a cadeia da sua empresa e marque onde está a sua área.","comprovacao":"Traga a cadeia desenhada e como sua área contribui para o valor final."},{"titulo":"Construir uma Árvore de Indicadores","comoFazer":"Pegue o principal indicador da empresa ou da sua área (lucro, faturamento, satisfação do cliente) e desdobre: de quais indicadores ele depende? E esses, de quais dependem? Continue até chegar a indicadores que o seu trabalho influencia diretamente.","comprovacao":"Traga a árvore e o caminho que liga o seu trabalho ao indicador principal."},{"titulo":"Resumir a empresa em uma página","comoFazer":"Escreva uma página com a visão integrada da empresa: quem são os clientes e o que compram, quais são os principais produtos ou serviços, como a empresa se organiza, quais são os principais números e os principais desafios do momento. Use informações públicas e internas.","comprovacao":"Traga a página escrita."},{"titulo":"Analisar o impacto de uma decisão em 4 dimensões","comoFazer":"Escolha uma decisão recente ou em discussão na sua área. Analise o impacto em 4 dimensões: clientes (como são afetados?), finanças (custo, receita), processos (o que muda na operação?) e pessoas (carga de trabalho, motivação, capacitação). Verifique se a decisão considerou todas.","comprovacao":"Traga a análise nas 4 dimensões e o que ficou de fora da decisão original."},{"titulo":"Estudar uma área diferente da sua","comoFazer":"Escolha uma área da empresa com a qual você quase não tem contato (financeiro, jurídico, logística, marketing). Estude o que ela faz, quais são seus indicadores e seus desafios, usando documentos, intranet e apresentações. Se houver abertura, converse 15 minutos com alguém de lá.","comprovacao":"Traga um resumo da área e 2 formas como ela influencia (ou é influenciada por) a sua."}]}
];

function normalizarNome(valor: unknown): string {
  return String(valor ?? "")
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/\s+/g, " ")
    .trim()
    .toLocaleLowerCase("pt-BR");
}

const POR_NOME = new Map(COMPETENCIAS_TAREFAS.map((item) => [normalizarNome(item.nome), item]));

export function competenciaTarefasPorNome(nome: unknown): CompetenciaTarefasCatalogo | null {
  return POR_NOME.get(normalizarNome(nome)) || null;
}

export function idTarefaCompetencia(competenciaNumero: number, tarefaNumero: number): string {
  return `${competenciaNumero}:${tarefaNumero}`;
}

export function tarefaCompetenciaPorId(id: unknown): {
  competencia: CompetenciaTarefasCatalogo;
  tarefa: TarefaCompetenciaCatalogo;
  tarefaNumero: number;
} | null {
  const match = String(id ?? "").trim().match(/^(\d+):(\d+)$/);
  if (!match) return null;
  const competenciaNumero = Number(match[1]);
  const tarefaNumero = Number(match[2]);
  const competencia = COMPETENCIAS_TAREFAS.find((item) => item.numero === competenciaNumero);
  const tarefa = competencia?.tarefas?.[tarefaNumero - 1];
  return competencia && tarefa ? { competencia, tarefa, tarefaNumero } : null;
}
